    ApplyPendingMaintenanceActionMessage.add_member(:apply_action, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ApplyAction', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The pending maintenance action to apply to this resource.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ca-certificate-rotation</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>db-upgrade</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>hardware-maintenance</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>os-upgrade</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>system-update</code>\n               </p>\n            </li>\n         </ul>\n         <p>For more information about these actions, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_UpgradeDBInstance.Maintenance.html#maintenance-actions-aurora\">Maintenance actions for Amazon Aurora</a> or \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Maintenance.html#maintenance-actions-rds\">Maintenance actions for Amazon RDS</a>.</p>", "smithy.api#required" => {}}))
    ApplyPendingMaintenanceActionMessage.add_member(:opt_in_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptInType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A value that specifies the type of opt-in request, or undoes an opt-in request. An opt-in \n           request of type <code>immediate</code> can't be undone.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>immediate</code> - Apply the maintenance action immediately.</p>\n            </li>\n            <li>\n               <p>\n                  <code>next-maintenance</code> - Apply the maintenance action during\n            the next maintenance window for the resource.</p>\n            </li>\n            <li>\n               <p>\n                  <code>undo-opt-in</code> - Cancel any existing <code>next-maintenance</code>\n            opt-in requests.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
