    BacktrackDBClusterMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The DB cluster identifier of the DB cluster to be backtracked. This parameter is\n            stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 alphanumeric characters or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster1</code>\n         </p>", "smithy.api#required" => {}}))
    BacktrackDBClusterMessage.add_member(:backtrack_to, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'BacktrackTo', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The timestamp of the time to backtrack the DB cluster to, specified in ISO\n            8601 format. For more information about ISO 8601, see the <a href=\"http://en.wikipedia.org/wiki/ISO_8601\">ISO8601 Wikipedia\n            page.</a>\n         </p>\n         <note>\n            <p>If the specified time isn't a consistent time for the DB cluster, \n                Aurora automatically chooses the nearest possible consistent time for the DB cluster.</p>\n         </note>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain a valid ISO 8601 timestamp.</p>\n            </li>\n            <li>\n               <p>Can't contain a timestamp set in the future.</p>\n            </li>\n         </ul>\n         <p>Example: <code>2017-07-08T18:00Z</code>\n         </p>", "smithy.api#required" => {}}))
    BacktrackDBClusterMessage.add_member(:force, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'Force', traits: {"smithy.api#documentation" => "<p>Specifies whether to force the DB cluster to backtrack when binary logging is\n            enabled. Otherwise, an error occurs when binary logging is enabled.</p>"}))
    BacktrackDBClusterMessage.add_member(:use_earliest_time_on_point_in_time_unavailable, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseEarliestTimeOnPointInTimeUnavailable', traits: {"smithy.api#documentation" => "<p>Specifies whether to backtrack the DB cluster to the earliest possible\n            backtrack time when <i>BacktrackTo</i> is set to a timestamp earlier than the earliest\n            backtrack time. When this parameter is disabled and <i>BacktrackTo</i> is set to a timestamp earlier than the earliest\n            backtrack time, an error occurs.</p>"}))
    BacktrackDBClusterMessage.type = Types::BacktrackDBClusterMessage
    BacktrackDBClusterOutput.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>Contains a user-supplied DB cluster identifier. This identifier is the unique key that identifies a DB cluster.</p>"}))
    BacktrackDBClusterOutput.add_member(:backtrack_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BacktrackIdentifier', traits: {"smithy.api#documentation" => "<p>Contains the backtrack identifier.</p>"}))
    BacktrackDBClusterOutput.add_member(:backtrack_to, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'BacktrackTo', traits: {"smithy.api#documentation" => "<p>The timestamp of the time to which the DB cluster was backtracked.</p>"}))
    BacktrackDBClusterOutput.add_member(:backtracked_from, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'BacktrackedFrom', traits: {"smithy.api#documentation" => "<p>The timestamp of the time from which the DB cluster was backtracked.</p>"}))
    BacktrackDBClusterOutput.add_member(:backtrack_request_creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'BacktrackRequestCreationTime', traits: {"smithy.api#documentation" => "<p>The timestamp of the time at which the backtrack was requested.</p>"}))
    BacktrackDBClusterOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the backtrack. This property returns one of the following\n            values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>applying</code> - The backtrack is currently being applied to or rolled back from the DB cluster.</p>\n            </li>\n            <li>\n               <p>\n                  <code>completed</code> - The backtrack has successfully been applied to or rolled back from the DB cluster.</p>\n            </li>\n            <li>\n               <p>\n                  <code>failed</code> - An error occurred while the backtrack was applied to or rolled back from the DB cluster.</p>\n            </li>\n            <li>\n               <p>\n                  <code>pending</code> - The backtrack is currently pending application to or rollback from the DB cluster.</p>\n            </li>\n         </ul>"}))
    BacktrackDBClusterOutput.type = Types::BacktrackDBClusterOutput
