    BlueGreenDeployment.add_member(:source, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseArn, location_name: 'Source', traits: {"smithy.api#documentation" => "<p>The source database for the blue/green deployment.</p>\n         <p>Before switchover, the source database is the production database in the blue environment.</p>"}))
    BlueGreenDeployment.add_member(:target, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseArn, location_name: 'Target', traits: {"smithy.api#documentation" => "<p>The target database for the blue/green deployment.</p>\n         <p>Before switchover, the target database is the clone database in the green environment.</p>"}))
    BlueGreenDeployment.add_member(:switchover_details, Smithy::Schema::Shapes::ShapeRef.new(shape: SwitchoverDetailList, location_name: 'SwitchoverDetails', traits: {"smithy.api#documentation" => "<p>The details about each source and target resource in the blue/green deployment.</p>"}))
    BlueGreenDeployment.add_member(:tasks, Smithy::Schema::Shapes::ShapeRef.new(shape: BlueGreenDeploymentTaskList, location_name: 'Tasks', traits: {"smithy.api#documentation" => "<p>Either tasks to be performed or tasks that have been completed on the target database before switchover.</p>"}))
    BlueGreenDeployment.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: BlueGreenDeploymentStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the blue/green deployment.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>PROVISIONING</code> - Resources are being created in the green environment.</p>\n            </li>\n            <li>\n               <p>\n                  <code>AVAILABLE</code> - Resources are available in the green environment.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SWITCHOVER_IN_PROGRESS</code> - The deployment is being switched from the blue environment to the \n                    green environment.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SWITCHOVER_COMPLETED</code> - Switchover from the blue environment to the green environment is complete.</p>\n            </li>\n            <li>\n               <p>\n                  <code>INVALID_CONFIGURATION</code> - Resources in the green environment are invalid, so switchover isn't possible.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SWITCHOVER_FAILED</code> - Switchover was attempted but failed.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETING</code> - The blue/green deployment is being deleted.</p>\n            </li>\n         </ul>"}))
    BlueGreenDeployment.add_member(:status_details, Smithy::Schema::Shapes::ShapeRef.new(shape: BlueGreenDeploymentStatusDetails, location_name: 'StatusDetails', traits: {"smithy.api#documentation" => "<p>Additional information about the status of the blue/green deployment.</p>"}))
    BlueGreenDeployment.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'CreateTime', traits: {"smithy.api#documentation" => "<p>The time when the blue/green deployment was created, in Universal Coordinated Time\n            (UTC).</p>"}))
    BlueGreenDeployment.add_member(:delete_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'DeleteTime', traits: {"smithy.api#documentation" => "<p>The time when the blue/green deployment was deleted, in Universal Coordinated Time\n            (UTC).</p>"}))
