    CancelExportTaskOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The progress status of the export task. The status can be one of the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CANCELED</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>CANCELING</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>COMPLETE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>IN_PROGRESS</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>STARTING</code>\n               </p>\n            </li>\n         </ul>"}))
