    CloudwatchLogsExportConfiguration.add_member(:enable_log_types, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableLogTypes', traits: {"smithy.api#documentation" => "<p>The list of log types to enable.</p>\n         <p>The following values are valid for each DB engine:</p>\n         <ul>\n            <li>\n               <p>Aurora MySQL - <code>audit | error | general | slowquery</code>\n               </p>\n            </li>\n            <li>\n               <p>Aurora PostgreSQL - <code>postgresql</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>error | general | slowquery</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql | upgrade</code>\n               </p>\n            </li>\n         </ul>"}))
    CloudwatchLogsExportConfiguration.add_member(:disable_log_types, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'DisableLogTypes', traits: {"smithy.api#documentation" => "<p>The list of log types to disable.</p>\n         <p>The following values are valid for each DB engine:</p>\n         <ul>\n            <li>\n               <p>Aurora MySQL - <code>audit | error | general | slowquery</code>\n               </p>\n            </li>\n            <li>\n               <p>Aurora PostgreSQL - <code>postgresql</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>error | general | slowquery</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql | upgrade</code>\n               </p>\n            </li>\n         </ul>"}))
