    ClusterPendingModifiedValues.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The allocated storage size in gibibytes (GiB) for all database engines except Amazon Aurora. For Aurora, \n            <code>AllocatedStorage</code> always returns 1, because Aurora DB cluster storage size isn't fixed, but \n            instead automatically adjusts as needed.</p>"}))
