    CopyDBParameterGroupMessage.add_member(:source_db_parameter_group_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDBParameterGroupIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier or ARN for the source DB parameter group.\n        For information about  \n        creating an ARN, \n        see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Tagging.ARN.html#USER_Tagging.ARN.Constructing\">\n            Constructing an ARN for Amazon RDS</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must specify a valid DB parameter group.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CopyDBParameterGroupMessage.add_member(:target_db_parameter_group_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetDBParameterGroupIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the copied DB parameter group.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be null, empty, or blank</p>\n            </li>\n            <li>\n               <p>Must contain from 1 to 255 letters, numbers, or hyphens</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-db-parameter-group</code>\n         </p>", "smithy.api#required" => {}}))
    CopyDBParameterGroupMessage.add_member(:target_db_parameter_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetDBParameterGroupDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A description for the copied DB parameter group.</p>", "smithy.api#required" => {}}))
