    CopyOptionGroupMessage.add_member(:source_option_group_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceOptionGroupIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the source option group.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must specify a valid option group.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CopyOptionGroupMessage.add_member(:target_option_group_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetOptionGroupIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the copied option group.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be null, empty, or blank</p>\n            </li>\n            <li>\n               <p>Must contain from 1 to 255 letters, numbers, or hyphens</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-option-group</code>\n         </p>", "smithy.api#required" => {}}))
    CopyOptionGroupMessage.add_member(:target_option_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetOptionGroupDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The description for the copied option group.</p>", "smithy.api#required" => {}}))
