    CreateBlueGreenDeploymentRequest.add_member(:blue_green_deployment_name, Smithy::Schema::Shapes::ShapeRef.new(shape: BlueGreenDeploymentName, location_name: 'BlueGreenDeploymentName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the blue/green deployment.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be the same as an existing blue/green deployment name in the same account and Amazon Web Services Region.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateBlueGreenDeploymentRequest.add_member(:source, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseArn, location_name: 'Source', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the source production database.</p>\n         <p>Specify the database that you want to clone. The blue/green deployment creates this database in \n           the green environment. You can make updates to the database in the green environment, such as an engine \n           version upgrade. When you are ready, you can switch the database in the green environment to be the \n           production database.</p>", "smithy.api#required" => {}}))
    CreateBlueGreenDeploymentRequest.add_member(:target_engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetEngineVersion, location_name: 'TargetEngineVersion', traits: {"smithy.api#documentation" => "<p>The engine version of the database in the green environment.</p>\n         <p>Specify the engine version to upgrade to in the green environment.</p>"}))
    CreateBlueGreenDeploymentRequest.add_member(:target_db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetDBParameterGroupName, location_name: 'TargetDBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The DB parameter group associated with the DB instance in the green environment.</p>\n         <p>To test parameter changes, specify a DB parameter group that is different from the one associated \n            with the source DB instance.</p>"}))
    CreateBlueGreenDeploymentRequest.add_member(:target_db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetDBClusterParameterGroupName, location_name: 'TargetDBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The DB cluster parameter group associated with the Aurora DB cluster in the green environment.</p>\n         <p>To test parameter changes, specify a DB cluster parameter group that is different from the one associated \n            with the source DB cluster.</p>"}))
    CreateBlueGreenDeploymentRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Tags to assign to the blue/green deployment.</p>"}))
    CreateBlueGreenDeploymentRequest.add_member(:target_db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetDBInstanceClass, location_name: 'TargetDBInstanceClass', traits: {"smithy.api#documentation" => "<p>Specify the DB instance class for the databases in the green environment.</p>\n         <p>This parameter only applies to RDS DB instances, because DB instances within an Aurora DB cluster can\n        have multiple different instance classes. If you're creating a blue/green deployment from an Aurora DB cluster,\n        don't specify this parameter. After the green environment is created, you can individually modify the instance classes \n        of the DB instances within the green DB cluster.</p>"}))
    CreateBlueGreenDeploymentRequest.add_member(:upgrade_target_storage_config, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UpgradeTargetStorageConfig', traits: {"smithy.api#documentation" => "<p>Whether to upgrade the storage file system configuration on the green database. This\n            option migrates the green DB instance from the older 32-bit file system to the preferred\n            configuration. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PIOPS.StorageTypes.html#USER_PIOPS.UpgradeFileSystem\">Upgrading the storage file system for a DB instance</a>.</p>"}))
    CreateBlueGreenDeploymentRequest.add_member(:target_iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'TargetIops', traits: {"smithy.api#documentation" => "<p>The amount of Provisioned IOPS (input/output operations per second) to allocate for the green DB instance.\n            For information about valid IOPS values, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_Storage.html\">Amazon RDS DB instance storage</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to Amazon Aurora blue/green deployments.</p>"}))
    CreateBlueGreenDeploymentRequest.add_member(:target_storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetStorageType, location_name: 'TargetStorageType', traits: {"smithy.api#documentation" => "<p>The storage type to associate with the green DB instance.</p>\n         <p>Valid Values: <code>gp2 | gp3 | io1 | io2</code>\n         </p>\n         <p>This setting doesn't apply to Amazon Aurora blue/green deployments.</p>"}))
    CreateBlueGreenDeploymentRequest.add_member(:target_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'TargetAllocatedStorage', traits: {"smithy.api#documentation" => "<p>The amount of storage in gibibytes (GiB) to allocate for the green DB instance. You can choose to\n            increase or decrease the allocated storage on the green DB instance.</p>\n         <p>This setting doesn't apply to Amazon Aurora blue/green deployments.</p>"}))
    CreateBlueGreenDeploymentRequest.add_member(:target_storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'TargetStorageThroughput', traits: {"smithy.api#documentation" => "<p>The storage throughput value for the green DB instance.</p>\n         <p>This setting applies only to the <code>gp3</code> storage type.</p>\n         <p>This setting doesn't apply to Amazon Aurora blue/green deployments.</p>"}))
    CreateBlueGreenDeploymentRequest.type = Types::CreateBlueGreenDeploymentRequest
