    CreateCustomDBEngineVersionMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomEngineName, location_name: 'Engine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The database engine. RDS Custom for Oracle supports the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>custom-oracle-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-ee-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-se2</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-se2-cdb</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateCustomDBEngineVersionMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomEngineVersion, location_name: 'EngineVersion', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of your CEV. The name format is 19.<i>customized_string</i>.\n            For example, a valid CEV name is <code>19.my_cev1</code>. This setting is required for RDS\n            Custom for Oracle, but optional for Amazon RDS. The combination of <code>Engine</code>\n            and <code>EngineVersion</code> is unique per customer per Region.</p>", "smithy.api#required" => {}}))
    CreateCustomDBEngineVersionMessage.add_member(:database_installation_files_s3_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: BucketName, location_name: 'DatabaseInstallationFilesS3BucketName', traits: {"smithy.api#documentation" => "<p>The name of an Amazon S3 bucket that contains database installation files for your CEV. For example, a valid \n            bucket name is <code>my-custom-installation-files</code>.</p>"}))
    CreateCustomDBEngineVersionMessage.add_member(:database_installation_files_s3_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String255, location_name: 'DatabaseInstallationFilesS3Prefix', traits: {"smithy.api#documentation" => "<p>The Amazon S3 directory that contains the database installation files for your CEV. For example, a valid \n            bucket name is <code>123456789012/cev1</code>. If this setting isn't specified, no prefix is assumed.</p>"}))
    CreateCustomDBEngineVersionMessage.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String255, location_name: 'ImageId', traits: {"smithy.api#documentation" => "<p>The ID of the Amazon Machine Image (AMI). For RDS Custom for SQL Server, an AMI ID is required \n            to create a CEV. For RDS Custom for Oracle, the default is the most recent AMI available, \n            but you can specify an AMI ID that was used in a different Oracle CEV. Find the AMIs \n            used by your CEVs by calling the <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_DescribeDBEngineVersions.html\">DescribeDBEngineVersions</a> operation.</p>"}))
    CreateCustomDBEngineVersionMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KmsKeyIdOrArn, location_name: 'KMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for an encrypted CEV. A symmetric encryption KMS key is required for \n            RDS Custom, but optional for Amazon RDS.</p>\n         <p>If you have an existing symmetric encryption KMS key in your account, you can use it with RDS Custom. \n            No further action is necessary. If you don't already have a symmetric encryption KMS key in your account, \n            follow the instructions in <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/create-keys.html#create-symmetric-cmk\">\n                Creating a symmetric encryption KMS key</a> in the <i>Amazon Web Services Key Management Service\n                    Developer Guide</i>.</p>\n         <p>You can choose the same symmetric encryption key when you create a CEV and a DB instance, or choose different keys.</p>"}))
    CreateCustomDBEngineVersionMessage.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>An optional description of your CEV.</p>"}))
    CreateCustomDBEngineVersionMessage.add_member(:manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomDBEngineVersionManifest, location_name: 'Manifest', traits: {"smithy.api#documentation" => "<p>The CEV manifest, which is a JSON document that describes the installation .zip files stored in Amazon S3. \n            Specify the name/value pairs in a file or a quoted string. RDS Custom applies the patches in the order in which \n            they are listed.</p>\n         <p>The following JSON fields are valid:</p>\n         <dl>\n            <dt>MediaImportTemplateVersion</dt>\n            <dd>\n               <p>Version of the CEV manifest. The date is in the format <code>YYYY-MM-DD</code>.</p>\n            </dd>\n            <dt>databaseInstallationFileNames</dt>\n            <dd>\n               <p>Ordered list of installation files for the CEV.</p>\n            </dd>\n            <dt>opatchFileNames</dt>\n            <dd>\n               <p>Ordered list of OPatch installers used for the Oracle DB engine.</p>\n            </dd>\n            <dt>psuRuPatchFileNames</dt>\n            <dd>\n               <p>The PSU and RU patches for this CEV.</p>\n            </dd>\n            <dt>OtherPatchFileNames</dt>\n            <dd>\n               <p>The patches that are not in the list of PSU and RU patches. \n                    Amazon RDS applies these patches after applying the PSU and RU patches.</p>\n            </dd>\n         </dl>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-cev.html#custom-cev.preparing.manifest\">\n            Creating the CEV manifest</a> in the <i>Amazon RDS User Guide</i>.</p>"}))
    CreateCustomDBEngineVersionMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    CreateCustomDBEngineVersionMessage.add_member(:source_custom_db_engine_version_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String255, location_name: 'SourceCustomDbEngineVersionIdentifier', traits: {"smithy.api#documentation" => "<p>The ARN of a CEV to use as a source for creating a new CEV. You can specify a different\n            Amazon Machine Imagine (AMI) by using either <code>Source</code> or\n                <code>UseAwsProvidedLatestImage</code>. You can't specify a different JSON manifest\n            when you specify <code>SourceCustomDbEngineVersionIdentifier</code>.</p>"}))
    CreateCustomDBEngineVersionMessage.add_member(:use_aws_provided_latest_image, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseAwsProvidedLatestImage', traits: {"smithy.api#documentation" => "<p>Specifies whether to use the latest service-provided Amazon Machine Image (AMI) for\n            the CEV. If you specify <code>UseAwsProvidedLatestImage</code>, you can't also specify\n                <code>ImageId</code>.</p>"}))
    CreateCustomDBEngineVersionMessage.type = Types::CreateCustomDBEngineVersionMessage
