    CreateCustomDBEngineVersionOutput.add_member(:db_engine_version_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBEngineVersionDescription', traits: {"smithy.api#documentation" => "<p>The description of the database engine version.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:default_character_set, Smithy::Schema::Shapes::ShapeRef.new(shape: CharacterSet, location_name: 'DefaultCharacterSet', traits: {"smithy.api#documentation" => "<p>The default character set for new instances of this engine version,\n            if the <code>CharacterSetName</code> parameter of the CreateDBInstance API\n            isn't specified.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:image, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomDBEngineVersionAMI, location_name: 'Image', traits: {"smithy.api#documentation" => "<p>The EC2 image</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:db_engine_media_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBEngineMediaType', traits: {"smithy.api#documentation" => "<p>A value that indicates the source media provider of the AMI based on the usage operation.  Applicable for RDS Custom for SQL Server.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supported_character_sets, Smithy::Schema::Shapes::ShapeRef.new(shape: SupportedCharacterSetsList, location_name: 'SupportedCharacterSets', traits: {"smithy.api#documentation" => "<p>A list of the character sets supported by this engine for the <code>CharacterSetName</code> parameter of the <code>CreateDBInstance</code> operation.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supported_nchar_character_sets, Smithy::Schema::Shapes::ShapeRef.new(shape: SupportedCharacterSetsList, location_name: 'SupportedNcharCharacterSets', traits: {"smithy.api#documentation" => "<p>A list of the character sets supported by the Oracle DB engine for the <code>NcharCharacterSetName</code> parameter of the <code>CreateDBInstance</code> operation.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:valid_upgrade_target, Smithy::Schema::Shapes::ShapeRef.new(shape: ValidUpgradeTargetList, location_name: 'ValidUpgradeTarget', traits: {"smithy.api#documentation" => "<p>A list of engine versions that this database engine version can be upgraded to.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supported_timezones, Smithy::Schema::Shapes::ShapeRef.new(shape: SupportedTimezonesList, location_name: 'SupportedTimezones', traits: {"smithy.api#documentation" => "<p>A list of the time zones supported by this engine for the\n            <code>Timezone</code> parameter of the <code>CreateDBInstance</code> action.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:exportable_log_types, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'ExportableLogTypes', traits: {"smithy.api#documentation" => "<p>The types of logs that the database engine has available for export to CloudWatch Logs.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supports_log_exports_to_cloudwatch_logs, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsLogExportsToCloudwatchLogs', traits: {"smithy.api#documentation" => "<p>Indicates whether the engine version supports exporting the log types specified by ExportableLogTypes to CloudWatch Logs.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supports_read_replica, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsReadReplica', traits: {"smithy.api#documentation" => "<p>Indicates whether the database engine version supports read replicas.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supported_engine_modes, Smithy::Schema::Shapes::ShapeRef.new(shape: EngineModeList, location_name: 'SupportedEngineModes', traits: {"smithy.api#documentation" => "<p>A list of the supported DB engine modes.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supported_feature_names, Smithy::Schema::Shapes::ShapeRef.new(shape: FeatureNameList, location_name: 'SupportedFeatureNames', traits: {"smithy.api#documentation" => "<p>A list of features supported by the DB engine.</p>\n         <p>The supported features vary by DB engine and DB engine version.</p>\n         <p>To determine the supported features for a specific DB engine and DB engine version using the CLI, \n        use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine <engine_name> --engine-version <engine_version></code>\n         </p>\n         <p>For example, to determine the supported features for RDS for PostgreSQL version 13.3 using the CLI, \n        use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine postgres --engine-version 13.3</code>\n         </p>\n         <p>The supported features are listed under <code>SupportedFeatureNames</code> in the output.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the DB engine version, either <code>available</code> or <code>deprecated</code>.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supports_parallel_query, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsParallelQuery', traits: {"smithy.api#documentation" => "<p>Indicates whether you can use Aurora parallel query with a specific DB engine version.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supports_global_databases, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsGlobalDatabases', traits: {"smithy.api#documentation" => "<p>Indicates whether you can use Aurora global databases with a specific DB engine version.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:major_engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MajorEngineVersion', traits: {"smithy.api#documentation" => "<p>The major engine version of the CEV.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:database_installation_files_s3_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseInstallationFilesS3BucketName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon S3 bucket that contains your database installation files.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:database_installation_files_s3_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseInstallationFilesS3Prefix', traits: {"smithy.api#documentation" => "<p>The Amazon S3 directory that contains the database installation files. \n            If not specified, then no prefix is assumed.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:db_engine_version_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBEngineVersionArn', traits: {"smithy.api#documentation" => "<p>The ARN of the custom engine version.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for an encrypted CEV. This parameter is required for \n            RDS Custom, but optional for Amazon RDS.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'CreateTime', traits: {"smithy.api#documentation" => "<p>The creation time of the DB engine version.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:tag_list, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'TagList'))
    CreateCustomDBEngineVersionOutput.add_member(:supports_babelfish, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsBabelfish', traits: {"smithy.api#documentation" => "<p>Indicates whether the engine version supports Babelfish for Aurora PostgreSQL.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:custom_db_engine_version_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomDBEngineVersionManifest, location_name: 'CustomDBEngineVersionManifest', traits: {"smithy.api#documentation" => "<p>JSON string that lists the installation files and parameters that RDS Custom uses to create a custom engine version (CEV). \n          RDS Custom applies the patches in the order in which they're listed in the manifest. You can set the Oracle home, Oracle base, \n          and UNIX/Linux user and group using the installation parameters. For more information, \n          see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-cev.preparing.html#custom-cev.preparing.manifest.fields\">JSON fields in the CEV manifest</a> in the <i>Amazon RDS User Guide</i>.\n      </p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supports_limitless_database, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsLimitlessDatabase', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports Aurora Limitless Database.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supports_certificate_rotation_without_restart, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'SupportsCertificateRotationWithoutRestart', traits: {"smithy.api#documentation" => "<p>Indicates whether the engine version supports rotating the server certificate without \n              rebooting the DB instance.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supported_ca_certificate_identifiers, Smithy::Schema::Shapes::ShapeRef.new(shape: CACertificateIdentifiersList, location_name: 'SupportedCACertificateIdentifiers', traits: {"smithy.api#documentation" => "<p>A list of the supported CA certificate identifiers.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n            instance</a> in the <i>Amazon RDS User Guide</i> and \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL.html\">\n            Using SSL/TLS to encrypt a connection to a DB cluster</a> in the <i>Amazon Aurora \n            User Guide</i>.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supports_local_write_forwarding, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'SupportsLocalWriteForwarding', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports forwarding write operations from reader DB instances \n            to the writer DB instance in the DB cluster. By default, write operations aren't allowed on reader DB instances.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:supports_integrations, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsIntegrations', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports zero-ETL integrations with\n            Amazon Redshift.</p>"}))
    CreateCustomDBEngineVersionOutput.add_member(:serverless_v2_features_support, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2FeaturesSupport, location_name: 'ServerlessV2FeaturesSupport', traits: {"smithy.api#documentation" => "<p>Specifies any Aurora Serverless v2 properties or limits that differ between Aurora engine versions.\n        You can test the values of this attribute when deciding which Aurora version to use in a new or upgraded\n        DB cluster. You can also retrieve the version of an existing DB cluster and check whether that version\n        supports certain Aurora Serverless v2 features before you attempt to use those features.\n      </p>"}))
    CreateCustomDBEngineVersionOutput.type = Types::CreateCustomDBEngineVersionOutput
    CreateDBClusterEndpointMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The DB cluster identifier of the DB cluster associated with the endpoint. This parameter is\n            stored as a lowercase string.</p>", "smithy.api#required" => {}}))
    CreateDBClusterEndpointMessage.add_member(:db_cluster_endpoint_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterEndpointIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier to use for the new endpoint. This parameter is stored as a lowercase string.</p>", "smithy.api#required" => {}}))
