    CreateDBClusterEndpointMessage.add_member(:static_members, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'StaticMembers', traits: {"smithy.api#documentation" => "<p>List of DB instance identifiers that are part of the custom endpoint group.</p>"}))
    CreateDBClusterEndpointMessage.add_member(:excluded_members, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'ExcludedMembers', traits: {"smithy.api#documentation" => "<p>List of DB instance identifiers that aren't part of the custom endpoint group.\n            All other eligible instances are reachable through the custom endpoint.\n            This parameter is relevant only if the list of static members is empty.</p>"}))
