    CreateDBClusterEndpointOutput.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The DB cluster identifier of the DB cluster associated with the endpoint. This parameter is\n            stored as a lowercase string.</p>"}))
    CreateDBClusterEndpointOutput.add_member(:db_cluster_endpoint_resource_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterEndpointResourceIdentifier', traits: {"smithy.api#documentation" => "<p>A unique system-generated identifier for an endpoint. It remains the same for the whole life of the endpoint.</p>"}))
