    CreateDBClusterEndpointOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The current status of the endpoint. One of: <code>creating</code>, <code>available</code>, <code>deleting</code>, <code>inactive</code>, <code>modifying</code>. The <code>inactive</code> state applies to an endpoint that can't be used for a certain kind of cluster,\n     such as a <code>writer</code> endpoint for a read-only secondary cluster in a global database.</p>"}))
    CreateDBClusterEndpointOutput.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EndpointType', traits: {"smithy.api#documentation" => "<p>The type of the endpoint. One of: <code>READER</code>, <code>WRITER</code>, <code>CUSTOM</code>.</p>"}))
    CreateDBClusterEndpointOutput.add_member(:custom_endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CustomEndpointType', traits: {"smithy.api#documentation" => "<p>The type associated with a custom endpoint. One of: <code>READER</code>,\n       <code>WRITER</code>, <code>ANY</code>.</p>"}))
    CreateDBClusterEndpointOutput.add_member(:static_members, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'StaticMembers', traits: {"smithy.api#documentation" => "<p>List of DB instance identifiers that are part of the custom endpoint group.</p>"}))
    CreateDBClusterEndpointOutput.add_member(:excluded_members, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'ExcludedMembers', traits: {"smithy.api#documentation" => "<p>List of DB instance identifiers that aren't part of the custom endpoint group.\n       All other eligible instances are reachable through the custom endpoint.\n       Only relevant if the list of static members is empty.</p>"}))
    CreateDBClusterEndpointOutput.add_member(:db_cluster_endpoint_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterEndpointArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the endpoint.</p>"}))
    CreateDBClusterEndpointOutput.type = Types::CreateDBClusterEndpointOutput
    CreateDBClusterMessage.add_member(:availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZones, location_name: 'AvailabilityZones', traits: {"smithy.api#documentation" => "<p>A list of Availability Zones (AZs) where you specifically want to create DB instances in the DB cluster.</p>\n         <p>For information on AZs, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Concepts.RegionsAndAvailabilityZones.html#Concepts.RegionsAndAvailabilityZones.AvailabilityZones\">Availability Zones</a>\n            in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't specify more than three AZs.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days for which automated backups are retained.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Default: <code>1</code>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a value from 1 to 35.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:character_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CharacterSetName', traits: {"smithy.api#documentation" => "<p>The name of the character set (<code>CharacterSet</code>) to associate the DB cluster with.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The name for your database of up to 64 alphanumeric characters. \n            A database named <code>postgres</code> is always created. If this parameter is specified, an additional database with this name is created.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for this DB cluster. This parameter is stored as a lowercase string.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 (for Aurora DB clusters) or 1 to 52 (for Multi-AZ DB\n                    clusters) letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster1</code>\n         </p>", "smithy.api#required" => {}}))
    CreateDBClusterMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB cluster parameter group to associate\n            with this DB cluster. If you don't specify a value, then \n          the default DB cluster parameter group for the specified DB engine and version is used.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the name of an existing DB cluster parameter group.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of EC2 VPC security groups to associate with this DB cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>A DB subnet group to associate with this DB cluster.</p>\n         <p>This setting is required to create a Multi-AZ DB cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the name of an existing DB subnet group.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>"}))
    CreateDBClusterMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The database engine to use for this DB cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>aurora-mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>aurora-postgresql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>postgres</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>neptune</code> - For information about using Amazon Neptune, see the\n                        <a href=\"https://docs.aws.amazon.com/neptune/latest/userguide/intro.html\">\n                     <i>Amazon Neptune User Guide</i>\n                  </a>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateDBClusterMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to use.</p>\n         <p>To list all of the available engine versions for Aurora MySQL version 2 (5.7-compatible) and version 3 (MySQL 8.0-compatible),\n            use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine aurora-mysql --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>You can supply either <code>5.7</code> or <code>8.0</code> to use the default engine version for Aurora MySQL version 2 or\n            version 3, respectively.</p>\n         <p>To list all of the available engine versions for Aurora PostgreSQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine aurora-postgresql --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>To list all of the available engine versions for RDS for MySQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine mysql --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>To list all of the available engine versions for RDS for PostgreSQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine postgres --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>For information about a specific engine, see the following topics:</p>\n         <ul>\n            <li>\n               <p>Aurora MySQL - see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/AuroraMySQL.Updates.html\">Database engine updates for Amazon Aurora MySQL</a> in the \n          <i>Amazon Aurora User Guide</i>.</p>\n            </li>\n            <li>\n               <p>Aurora PostgreSQL - see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/AuroraPostgreSQL.Updates.20180305.html\">Amazon Aurora PostgreSQL releases and engine versions</a> in the \n           <i>Amazon Aurora User Guide</i>.</p>\n            </li>\n            <li>\n               <p>RDS for MySQL - see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_MySQL.html#MySQL.Concepts.VersionMgmt\">Amazon RDS for MySQL</a> in the <i>Amazon RDS User Guide</i>.</p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_PostgreSQL.html#PostgreSQL.Concepts\">Amazon RDS for PostgreSQL</a> in the <i>Amazon RDS User Guide</i>.</p>\n            </li>\n         </ul>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the instances in the DB cluster accept connections.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values: <code>1150-65535</code>\n         </p>\n         <p>Default:</p>\n         <ul>\n            <li>\n               <p>RDS for MySQL and Aurora MySQL - <code>3306</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL and Aurora PostgreSQL - <code>5432</code>\n               </p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:master_username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUsername', traits: {"smithy.api#documentation" => "<p>The name of the master user for the DB cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 16 letters or numbers.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't be a reserved word for the chosen database engine.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>The password for the master database user.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 8 to 41 characters.</p>\n            </li>\n            <li>\n               <p>Can contain any printable ASCII character except \"/\", \"\"\", or \"@\".</p>\n            </li>\n            <li>\n               <p>Can't be specified if <code>ManageMasterUserPassword</code> is turned on.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The option group to associate the DB cluster with.</p>\n         <p>DB clusters are associated with a default option group that can't be modified.</p>"}))
    CreateDBClusterMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created\n        if automated backups are enabled\n        using the <code>BackupRetentionPeriod</code> parameter.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>The default is a 30-minute window selected at random from an\n        8-hour block of time for each Amazon Web Services Region. \n        To view the time blocks available, see \n        <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Aurora.Managing.Backups.html#Aurora.Managing.Backups.BackupWindow\">\n            Backup window</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>The default is a 30-minute window selected at random from an\n            8-hour block of time for each Amazon Web Services Region, occurring on a random day of the\n            week. To see the time blocks available, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_UpgradeDBInstance.Maintenance.html#AdjustingTheMaintenanceWindow.Aurora\">\n                Adjusting the Preferred DB Cluster Maintenance Window</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>ddd:hh24:mi-ddd:hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Days must be one of <code>Mon | Tue | Wed | Thu | Fri | Sat | Sun</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:replication_source_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationSourceIdentifier', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the source DB instance or DB cluster if this DB\n            cluster is created as a read replica.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Tags to assign to the DB cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:storage_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'StorageEncrypted', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB cluster is encrypted.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for an encrypted DB cluster.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n                 To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>When a KMS key isn't specified in <code>KmsKeyId</code>:</p>\n         <ul>\n            <li>\n               <p>If <code>ReplicationSourceIdentifier</code> identifies an encrypted\n                    source, then Amazon RDS uses the KMS key used to encrypt the\n                    source. Otherwise, Amazon RDS uses your default KMS key.</p>\n            </li>\n            <li>\n               <p>If the <code>StorageEncrypted</code> parameter is enabled and\n                        <code>ReplicationSourceIdentifier</code> isn't specified, then Amazon RDS\n                    uses your default KMS key.</p>\n            </li>\n         </ul>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>\n         <p>If you create a read replica of an encrypted DB cluster in another Amazon Web Services Region, make\n            sure to set <code>KmsKeyId</code> to a KMS key identifier that is valid in the destination Amazon Web Services\n            Region. This KMS key is used to encrypt the read replica in that Amazon Web Services Region.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:pre_signed_url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreSignedUrl', traits: {"smithy.api#documentation" => "<p>When you are replicating a DB cluster from one Amazon Web Services GovCloud (US) Region to another,\n            an URL that contains a Signature Version 4 signed request for the\n                <code>CreateDBCluster</code> operation to be called in the source Amazon Web Services Region where\n            the DB cluster is replicated from. Specify <code>PreSignedUrl</code> only when you are\n            performing cross-Region replication from an encrypted DB cluster.</p>\n         <p>The presigned URL must be a valid request for the <code>CreateDBCluster</code> API\n            operation that can run in the source Amazon Web Services Region that contains the encrypted DB\n            cluster to copy.</p>\n         <p>The presigned URL request must contain the following parameter values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>KmsKeyId</code> - The KMS key identifier for the KMS key to use to\n                    encrypt the copy of the DB cluster in the destination Amazon Web Services Region. This should\n                    refer to the same KMS key for both the <code>CreateDBCluster</code> operation\n                    that is called in the destination Amazon Web Services Region, and the operation contained in\n                    the presigned URL.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DestinationRegion</code> - The name of the Amazon Web Services Region that Aurora read replica will\n                    be created in.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ReplicationSourceIdentifier</code> - The DB cluster identifier for the encrypted DB cluster to be copied. \n                This identifier must be in the Amazon Resource Name (ARN) format for the source Amazon Web Services Region. For example, if you are copying an \n                encrypted DB cluster from the us-west-2 Amazon Web Services Region, then your <code>ReplicationSourceIdentifier</code> would look like\n                Example: <code>arn:aws:rds:us-west-2:123456789012:cluster:aurora-cluster1</code>.</p>\n            </li>\n         </ul>\n         <p>To learn how to generate a Signature Version 4 signed request, see \n            <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/API/sigv4-query-string-auth.html\">\n                Authenticating Requests: Using Query Parameters (Amazon Web Services Signature Version 4)</a> and\n            <a href=\"https://docs.aws.amazon.com/general/latest/gr/signature-version-4.html\">\n                Signature Version 4 Signing Process</a>.</p>\n         <note>\n            <p>If you are using an Amazon Web Services SDK tool or the CLI, you can specify\n                    <code>SourceRegion</code> (or <code>--source-region</code> for the CLI)\n                instead of specifying <code>PreSignedUrl</code> manually. Specifying\n                    <code>SourceRegion</code> autogenerates a presigned URL that is a valid request\n                for the operation that can run in the source Amazon Web Services Region.</p>\n         </note>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access\n            Management (IAM) accounts to database accounts. By default, mapping isn't\n            enabled.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.IAMDBAuth.html\"> IAM Database\n                Authentication</a> in the <i>Amazon Aurora User Guide</i> or\n                <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\">IAM database\n                authentication for MariaDB, MySQL, and PostgreSQL</a> in the <i>Amazon\n                RDS User Guide</i>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:backtrack_window, Smithy::Schema::Shapes::ShapeRef.new(shape: LongOptional, location_name: 'BacktrackWindow', traits: {"smithy.api#documentation" => "<p>The target backtrack window, in seconds. To disable backtracking, set this value to\n            <code>0</code>.</p>\n         <p>Valid for Cluster Type: Aurora MySQL DB clusters only</p>\n         <p>Default: <code>0</code>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If specified, this value must be set to a number from 0 to 259,200 (72 hours).</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>The list of log types that need to be enabled for exporting to CloudWatch Logs.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>The following values are valid for each DB engine:</p>\n         <ul>\n            <li>\n               <p>Aurora MySQL - <code>audit | error | general | instance | slowquery | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>Aurora PostgreSQL - <code>instance | postgresql | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>error | general | slowquery | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql | upgrade | iam-db-auth-error</code>\n               </p>\n            </li>\n         </ul>\n         <p>For more information about exporting CloudWatch Logs for Amazon RDS, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about exporting CloudWatch Logs for Amazon Aurora, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon Aurora User Guide</i>.</p>"}))
    CreateDBClusterMessage.add_member(:engine_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineMode', traits: {"smithy.api#documentation" => "<p>The DB engine mode of the DB cluster, either <code>provisioned</code> or <code>serverless</code>.</p>\n         <p>The <code>serverless</code> engine mode only applies for Aurora Serverless v1 DB clusters. Aurora Serverless v2 DB clusters use the \n        <code>provisioned</code> engine mode.</p>\n         <p>For information about limitations and requirements for Serverless DB clusters, see the \n            following sections in the <i>Amazon Aurora User Guide</i>:</p>\n         <ul>\n            <li>\n               <p>\n                  <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-serverless.html#aurora-serverless.limitations\">Limitations of Aurora\n                        Serverless v1</a>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-serverless-v2.requirements.html\">Requirements\n                        for Aurora Serverless v2</a>\n               </p>\n            </li>\n         </ul>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingConfiguration, location_name: 'ScalingConfiguration', traits: {"smithy.api#documentation" => "<p>For DB clusters in <code>serverless</code> DB engine mode, the scaling properties of the DB cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:rds_custom_cluster_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RdsCustomClusterConfiguration, location_name: 'RdsCustomClusterConfiguration', traits: {"smithy.api#documentation" => "<p>Reserved for future use.</p>"}))
    CreateDBClusterMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB cluster has deletion protection enabled. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:global_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'GlobalClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The global cluster ID of an Aurora cluster that becomes the primary cluster\n            in the new global database cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:enable_http_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableHttpEndpoint', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable the HTTP endpoint for the DB cluster. By default, the HTTP endpoint \n            isn't enabled.</p>\n         <p>When enabled, the HTTP endpoint provides a connectionless web service API (RDS Data API) for running\n            SQL queries on the DB cluster. You can also query your database\n            from inside the RDS console with the RDS query editor.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/data-api.html\">Using RDS Data API</a> in the \n            <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the DB cluster to snapshots of the DB cluster. \n            The default is not to copy them.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The Active Directory directory ID to create the DB cluster in.</p>\n         <p>For Amazon Aurora DB clusters, Amazon RDS can use Kerberos authentication to authenticate users that connect to the DB cluster.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/kerberos-authentication.html\">Kerberos authentication</a>\n            in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM role to use when making API calls to the Directory Service.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:enable_global_write_forwarding, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableGlobalWriteForwarding', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable this DB cluster to forward write operations to the primary cluster of a global cluster\n      (Aurora global database). By default, write operations are not allowed on Aurora DB clusters that\n      are secondary clusters in an Aurora global database.</p>\n         <p>You can set this value only on Aurora DB clusters that are members of an Aurora global database. With this parameter\n      enabled, a secondary cluster can forward writes to the current primary cluster, and the resulting changes are replicated back to\n      this cluster. For the primary DB cluster of an Aurora global database, this value is used immediately if the\n        primary is demoted by a global cluster API operation, but it does nothing until then.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:db_cluster_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterInstanceClass', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of each DB instance in the Multi-AZ DB cluster, for example <code>db.m6gd.xlarge</code>.\n            Not all DB instance classes are available in all Amazon Web Services Regions, or for all database engines.</p>\n         <p>For the full list of DB instance classes and availability for your engine, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">DB instance class</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting is required to create a Multi-AZ DB cluster.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The amount of storage in gibibytes (GiB) to allocate to each DB instance in the Multi-AZ DB cluster.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters only</p>\n         <p>This setting is required to create a Multi-AZ DB cluster.</p>"}))
    CreateDBClusterMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type to associate with the DB cluster.</p>\n         <p>For information on storage types for Aurora DB clusters, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Aurora.Overview.StorageReliability.html#aurora-storage-type\">Storage configurations for Amazon Aurora DB clusters</a>. For information on storage types for Multi-AZ DB\n            clusters, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/create-multi-az-db-cluster.html#create-multi-az-db-cluster-settings\">Settings for creating Multi-AZ DB clusters</a>.</p>\n         <p>This setting is required to create a Multi-AZ DB cluster.</p>\n         <p>When specified for a Multi-AZ DB cluster, a value for the <code>Iops</code> parameter is required.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>Aurora DB clusters - <code>aurora | aurora-iopt1</code>\n               </p>\n            </li>\n            <li>\n               <p>Multi-AZ DB clusters - <code>io1 | io2 | gp3</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default:</p>\n         <ul>\n            <li>\n               <p>Aurora DB clusters - <code>aurora</code>\n               </p>\n            </li>\n            <li>\n               <p>Multi-AZ DB clusters - <code>io1</code>\n               </p>\n            </li>\n         </ul>\n         <note>\n            <p>When you create an Aurora DB cluster with the storage type set to <code>aurora-iopt1</code>, the storage type is returned\n                in the response. The storage type isn't returned when you set it to <code>aurora</code>.</p>\n         </note>"}))
    CreateDBClusterMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The amount of Provisioned IOPS (input/output operations per second) to be initially allocated \n            for each DB instance in the Multi-AZ DB cluster.</p>\n         <p>For information about valid IOPS values, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_Storage.html#USER_PIOPS\">Provisioned IOPS storage</a> in the <i>Amazon RDS\n                User Guide</i>.</p>\n         <p>This setting is required to create a Multi-AZ DB cluster.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters only</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a multiple between .5 and 50 of the storage amount for the DB cluster.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB cluster is publicly accessible.</p>\n         <p>When the DB cluster is publicly accessible and you connect from outside of the DB cluster's virtual private cloud (VPC), \n              its Domain Name System (DNS) endpoint resolves to the public IP address. When you connect from within the same VPC as the DB cluster, \n              the endpoint resolves to the private IP address. Access to the DB cluster is ultimately controlled by the security group it uses. That public\n              access isn't permitted if the security group assigned to the DB cluster doesn't permit it.</p>\n         <p>When the DB cluster isn't publicly accessible, it is an internal DB cluster with a DNS name that resolves to a private IP address.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters only</p>\n         <p>Default: The default behavior varies depending on whether <code>DBSubnetGroupName</code> is specified.</p>\n         <p>If <code>DBSubnetGroupName</code> isn't specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the default VPC in the target Region doesn’t have an internet gateway attached to it, the DB cluster is private.</p>\n            </li>\n            <li>\n               <p>If the default VPC in the target Region has an internet gateway attached to it, the DB cluster is public.</p>\n            </li>\n         </ul>\n         <p>If <code>DBSubnetGroupName</code> is specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the subnets are part of a VPC that doesn’t have an internet gateway attached to it, the DB cluster is private.</p>\n            </li>\n            <li>\n               <p>If the subnets are part of a VPC that has an internet gateway attached to it, the DB cluster is public.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether minor engine upgrades are applied automatically to the DB cluster during the maintenance window. \n            By default, minor engine upgrades are applied automatically.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB cluster.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    CreateDBClusterMessage.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are collected for the DB cluster. To turn off \n            collecting Enhanced Monitoring metrics, specify <code>0</code>.</p>\n         <p>If <code>MonitoringRoleArn</code> is specified, also set <code>MonitoringInterval</code>\n            to a value other than <code>0</code>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values: <code>0 | 1 | 5 | 10 | 15 | 30 | 60</code>\n         </p>\n         <p>Default: <code>0</code>\n         </p>"}))
    CreateDBClusterMessage.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the IAM role that permits RDS to send Enhanced Monitoring metrics to Amazon CloudWatch Logs. \n            An example is <code>arn:aws:iam:123456789012:role/emaccess</code>. For information on creating a monitoring role,\n            see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Monitoring.OS.html#USER_Monitoring.OS.Enabling\">Setting \n                up and enabling Enhanced Monitoring</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>If <code>MonitoringInterval</code> is set to a value other than <code>0</code>, supply a <code>MonitoringRoleArn</code> value.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:database_insights_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseInsightsMode, location_name: 'DatabaseInsightsMode', traits: {"smithy.api#documentation" => "<p>The mode of Database Insights to enable for the DB cluster.</p>\n         <p>If you set this value to <code>advanced</code>, you must also set the <code>PerformanceInsightsEnabled</code>\n            parameter to <code>true</code> and the <code>PerformanceInsightsRetentionPeriod</code> parameter to 465.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:enable_performance_insights, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnablePerformanceInsights', traits: {"smithy.api#documentation" => "<p>Specifies whether to turn on Performance Insights for the DB cluster.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PerfInsights.html\">\n            Using Amazon Performance Insights</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>If you don't specify a value for <code>PerformanceInsightsKMSKeyId</code>, then Amazon RDS \n            uses your default KMS key. There is a default KMS key for your Amazon Web Services account. \n            Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:performance_insights_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PerformanceInsightsRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain Performance Insights data.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>7</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <i>month</i> * 31, where <i>month</i> is a number of months from 1-23. \n                Examples: <code>93</code> (3 months * 31), <code>341</code> (11 months * 31), <code>589</code> (19 months * 31)</p>\n            </li>\n            <li>\n               <p>\n                  <code>731</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: <code>7</code> days</p>\n         <p>If you specify a retention period that isn't valid, such as <code>94</code>,  Amazon RDS issues an error.</p>"}))
    CreateDBClusterMessage.add_member(:enable_limitless_database, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableLimitlessDatabase', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable Aurora Limitless Database. You must enable Aurora Limitless Database to create a DB shard group.</p>\n         <p>Valid for: Aurora DB clusters only</p>\n         <note>\n            <p>This setting is no longer used. Instead use the <code>ClusterScalabilityType</code> setting.</p>\n         </note>"}))
    CreateDBClusterMessage.add_member(:serverless_v2_scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2ScalingConfiguration, location_name: 'ServerlessV2ScalingConfiguration'))
    CreateDBClusterMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB cluster.</p>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB cluster. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon Aurora User Guide.</i>\n         </p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>\n         <p>Valid Values: <code>IPV4 | DUAL</code>\n         </p>"}))
    CreateDBClusterMessage.add_member(:cluster_scalability_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ClusterScalabilityType, location_name: 'ClusterScalabilityType', traits: {"smithy.api#documentation" => "<p>Specifies the scalability mode of the Aurora DB cluster. When set to <code>limitless</code>, the cluster operates as an Aurora Limitless Database.\n            When set to <code>standard</code> (the default), the cluster uses normal DB instance creation.</p>\n         <p>Valid for: Aurora DB clusters only</p>\n         <note>\n            <p>You can't modify this setting after you create the DB cluster.</p>\n         </note>"}))
    CreateDBClusterMessage.add_member(:db_system_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSystemId', traits: {"smithy.api#documentation" => "<p>Reserved for future use.</p>"}))
    CreateDBClusterMessage.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide</i> and <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon Aurora User Guide.</i>\n         </p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't manage the master user password with Amazon Web Services Secrets Manager if <code>MasterUserPassword</code> \n                    is specified.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and \n            managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets \n            Manager for the DB cluster.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>If you don't specify <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> \n            KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't \n            use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer \n            managed KMS key.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:enable_local_write_forwarding, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableLocalWriteForwarding', traits: {"smithy.api#documentation" => "<p>Specifies whether read replicas can forward write operations to the writer DB instance in the DB cluster. By\n            default, write operations aren't allowed on reader DB instances.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    CreateDBClusterMessage.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>The CA certificate identifier to use for the DB cluster's server certificate.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n            instance</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters</p>"}))
    CreateDBClusterMessage.add_member(:engine_lifecycle_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineLifecycleSupport', traits: {"smithy.api#documentation" => "<p>The life cycle type for this DB cluster.</p>\n         <note>\n            <p>By default, this value is set to <code>open-source-rds-extended-support</code>, which enrolls your DB cluster into Amazon RDS Extended Support. \n              At the end of standard support, you can avoid charges for Extended Support by setting the value to <code>open-source-rds-extended-support-disabled</code>. In this case, \n             creating the DB cluster will fail if the DB major version is past its end of standard support date.</p>\n         </note>\n         <p>You can use this setting to enroll your DB cluster into Amazon RDS Extended Support. With RDS Extended Support, \n        you can run the selected major engine version on your DB cluster past the end of standard support for that engine version. For more information, see the following sections:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora - <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon Aurora</a> in the <i>Amazon Aurora User Guide</i>\n               </p>\n            </li>\n            <li>\n               <p>Amazon RDS - <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon RDS</a> in the <i>Amazon RDS User Guide</i>\n               </p>\n            </li>\n         </ul>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values: <code>open-source-rds-extended-support | open-source-rds-extended-support-disabled</code>\n         </p>\n         <p>Default: <code>open-source-rds-extended-support</code>\n         </p>"}))
    CreateDBClusterMessage.type = Types::CreateDBClusterMessage
    CreateDBClusterParameterGroupMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB cluster parameter group.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must not match the name of an existing DB cluster parameter group.</p>\n            </li>\n         </ul>\n         <note>\n            <p>This value is stored as a lowercase string.</p>\n         </note>", "smithy.api#required" => {}}))
    CreateDBClusterParameterGroupMessage.add_member(:db_parameter_group_family, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupFamily', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The DB cluster parameter group family name. A DB cluster parameter group can be associated with one and only one DB cluster \n          parameter group family, and can be applied only to a DB cluster running a database engine and engine version compatible with that DB cluster parameter group family.</p>\n         <p>\n            <b>Aurora MySQL</b>\n         </p>\n         <p>Example: <code>aurora-mysql5.7</code>, <code>aurora-mysql8.0</code>\n         </p>\n         <p>\n            <b>Aurora PostgreSQL</b>\n         </p>\n         <p>Example: <code>aurora-postgresql14</code>\n         </p>\n         <p>\n            <b>RDS for MySQL</b>\n         </p>\n         <p>Example: <code>mysql8.0</code>\n         </p>\n         <p>\n            <b>RDS for PostgreSQL</b>\n         </p>\n         <p>Example: <code>postgres13</code>\n         </p>\n         <p>To list all of the available parameter group families for a DB engine, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --query \"DBEngineVersions[].DBParameterGroupFamily\" --engine <engine></code>\n         </p>\n         <p>For example, to list all of the available parameter group families for the Aurora PostgreSQL DB engine, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --query \"DBEngineVersions[].DBParameterGroupFamily\" --engine aurora-postgresql</code>\n         </p>\n         <note>\n            <p>The output contains duplicates.</p>\n         </note>\n         <p>The following are the valid DB engine values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>aurora-mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>aurora-postgresql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>postgres</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateDBClusterParameterGroupMessage.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Description', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The description for the DB cluster parameter group.</p>", "smithy.api#required" => {}}))
    CreateDBClusterParameterGroupMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Tags to assign to the DB cluster parameter group.</p>"}))
    CreateDBClusterParameterGroupMessage.type = Types::CreateDBClusterParameterGroupMessage
    CreateDBClusterParameterGroupResult.add_member(:db_cluster_parameter_group, Smithy::Schema::Shapes::ShapeRef.new(shape: DBClusterParameterGroup, location_name: 'DBClusterParameterGroup'))
    CreateDBClusterParameterGroupResult.type = Types::CreateDBClusterParameterGroupResult
    CreateDBClusterResult.add_member(:db_cluster, Smithy::Schema::Shapes::ShapeRef.new(shape: DBCluster, location_name: 'DBCluster'))
    CreateDBClusterResult.type = Types::CreateDBClusterResult
    CreateDBClusterSnapshotMessage.add_member(:db_cluster_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterSnapshotIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier of the DB cluster snapshot. This parameter is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster1-snapshot1</code>\n         </p>", "smithy.api#required" => {}}))
    CreateDBClusterSnapshotMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier of the DB cluster to create a snapshot for. This parameter isn't case-sensitive.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing DBCluster.</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster1</code>\n         </p>", "smithy.api#required" => {}}))
    CreateDBClusterSnapshotMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags to be assigned to the DB cluster snapshot.</p>"}))
    CreateDBClusterSnapshotMessage.type = Types::CreateDBClusterSnapshotMessage
    CreateDBClusterSnapshotResult.add_member(:db_cluster_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: DBClusterSnapshot, location_name: 'DBClusterSnapshot'))
    CreateDBClusterSnapshotResult.type = Types::CreateDBClusterSnapshotResult
    CreateDBInstanceMessage.add_member(:db_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBName', traits: {"smithy.api#documentation" => "<p>The meaning of this parameter differs according to the database engine you use.</p>\n         <dl>\n            <dt>Amazon Aurora MySQL</dt>\n            <dd>\n               <p>The name of the database to create when the primary DB instance of the Aurora MySQL DB cluster is\n                  created. If this parameter isn't specified for an Aurora MySQL DB cluster, no database is created \n                  in the DB cluster.</p>\n               <p>Constraints:</p>\n               <ul>\n                  <li>\n                     <p>Must contain 1 to 64 alphanumeric characters.</p>\n                  </li>\n                  <li>\n                     <p>Must begin with a letter. Subsequent characters can be letters, underscores, or digits (0-9).</p>\n                  </li>\n                  <li>\n                     <p>Can't be a word reserved by the database engine.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>Amazon Aurora PostgreSQL</dt>\n            <dd>\n               <p>The name of the database to create when the primary DB instance of the Aurora PostgreSQL DB cluster is\n                    created. A database named <code>postgres</code> is always created. If this parameter is specified, an additional database with this name is created.</p>\n               <p>Constraints:</p>\n               <ul>\n                  <li>\n                     <p>It must contain 1 to 63 alphanumeric characters.</p>\n                  </li>\n                  <li>\n                     <p>Must begin with a letter. Subsequent characters can be letters, underscores, or digits\n                          (0 to 9).</p>\n                  </li>\n                  <li>\n                     <p>Can't be a word reserved by the database engine.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>Amazon RDS Custom for Oracle</dt>\n            <dd>\n               <p>The Oracle System ID (SID) of the created RDS Custom DB instance. If you don't specify a value, the default value is <code>ORCL</code> for non-CDBs and\n                <code>RDSCDB</code> for CDBs.</p>\n               <p>Default: <code>ORCL</code>\n               </p>\n               <p>Constraints:</p>\n               <ul>\n                  <li>\n                     <p>Must contain 1 to 8 alphanumeric characters.</p>\n                  </li>\n                  <li>\n                     <p>Must contain a letter.</p>\n                  </li>\n                  <li>\n                     <p>Can't be a word reserved by the database engine.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>Amazon RDS Custom for SQL Server</dt>\n            <dd>\n               <p>Not applicable. Must be null.</p>\n            </dd>\n            <dt>RDS for Db2</dt>\n            <dd>\n               <p>The name of the database to create when the DB instance is created. If\n                        this parameter isn't specified, no database is created in the DB instance.\n                        In some cases, we recommend that you don't add a database name. For more\n                        information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/db2-db-instance-prereqs.html#db2-prereqs-additional-considerations\">Additional considerations</a> in the <i>Amazon RDS User\n                            Guide</i>.</p>\n               <p>Constraints:</p>\n               <ul>\n                  <li>\n                     <p>Must contain 1 to 64 letters or numbers.</p>\n                  </li>\n                  <li>\n                     <p>Must begin with a letter. Subsequent characters can be letters,\n                                underscores, or digits (0-9).</p>\n                  </li>\n                  <li>\n                     <p>Can't be a word reserved by the specified database engine.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for MariaDB</dt>\n            <dd>\n               <p>The name of the database to create when the DB instance is created. If this parameter isn't specified, no database is created in the DB instance.</p>\n               <p>Constraints:</p>\n               <ul>\n                  <li>\n                     <p>Must contain 1 to 64 letters or numbers.</p>\n                  </li>\n                  <li>\n                     <p>Must begin with a letter. Subsequent characters can be letters, underscores, or digits (0-9).</p>\n                  </li>\n                  <li>\n                     <p>Can't be a word reserved by the specified database engine.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for MySQL</dt>\n            <dd>\n               <p>The name of the database to create when the DB instance is created. If this parameter isn't specified, no database is created in the DB instance.</p>\n               <p>Constraints:</p>\n               <ul>\n                  <li>\n                     <p>Must contain 1 to 64 letters or numbers.</p>\n                  </li>\n                  <li>\n                     <p>Must begin with a letter. Subsequent characters can be letters, underscores, or digits (0-9).</p>\n                  </li>\n                  <li>\n                     <p>Can't be a word reserved by the specified database engine.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for Oracle</dt>\n            <dd>\n               <p>The Oracle System ID (SID) of the created DB instance. If you don't specify a value, \n                    the default value is <code>ORCL</code>. You can't specify the \n                    string <code>null</code>, or any other reserved word, for <code>DBName</code>.</p>\n               <p>Default: <code>ORCL</code>\n               </p>\n               <p>Constraints:</p>\n               <ul>\n                  <li>\n                     <p>Can't be longer than 8 characters.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for PostgreSQL</dt>\n            <dd>\n               <p>The name of the database to create when the DB instance is created. A database named <code>postgres</code> is always created. If this parameter is specified, an additional database with this name is created.</p>\n               <p>Constraints:</p>\n               <ul>\n                  <li>\n                     <p>Must contain 1 to 63 letters, numbers, or underscores.</p>\n                  </li>\n                  <li>\n                     <p>Must begin with a letter. Subsequent characters can be letters, underscores, or digits (0-9).</p>\n                  </li>\n                  <li>\n                     <p>Can't be a word reserved by the specified database engine.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for SQL Server</dt>\n            <dd>\n               <p>Not applicable. Must be null.</p>\n            </dd>\n         </dl>"}))
    CreateDBInstanceMessage.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for this DB instance. This parameter is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbinstance</code>\n         </p>", "smithy.api#required" => {}}))
    CreateDBInstanceMessage.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The amount of storage in gibibytes (GiB) to allocate for the DB instance.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. Aurora cluster volumes automatically grow as the amount of data in your \n                    database increases, though you are only charged for the space that you use in an Aurora cluster volume.</p>\n         <dl>\n            <dt>Amazon RDS Custom</dt>\n            <dd>\n               <p>Constraints to the amount of storage for each storage type are the following:</p>\n               <ul>\n                  <li>\n                     <p>General Purpose (SSD) storage (gp2, gp3): Must be an integer from 40 to 65536 for RDS Custom for Oracle, \n                            16384 for RDS Custom for SQL Server.</p>\n                  </li>\n                  <li>\n                     <p>Provisioned IOPS storage (io1, io2): Must be an integer from 40 to 65536 for RDS Custom for Oracle, \n                           16384 for RDS Custom for SQL Server.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for Db2</dt>\n            <dd>\n               <p>Constraints to the amount of storage for each storage type are the following:</p>\n               <ul>\n                  <li>\n                     <p>General Purpose (SSD) storage (gp3): Must be an integer from 20 to 65536.</p>\n                  </li>\n                  <li>\n                     <p>Provisioned IOPS storage (io1, io2): Must be an integer from 100 to 65536.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for MariaDB</dt>\n            <dd>\n               <p>Constraints to the amount of storage for each storage type are the following:</p>\n               <ul>\n                  <li>\n                     <p>General Purpose (SSD) storage (gp2, gp3): Must be an integer from 20 to 65536.</p>\n                  </li>\n                  <li>\n                     <p>Provisioned IOPS storage (io1, io2): Must be an integer from 100 to 65536.</p>\n                  </li>\n                  <li>\n                     <p>Magnetic storage (standard): Must be an integer from 5 to 3072.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for MySQL</dt>\n            <dd>\n               <p>Constraints to the amount of storage for each storage type are the following:</p>\n               <ul>\n                  <li>\n                     <p>General Purpose (SSD) storage (gp2, gp3): Must be an integer from 20 to 65536.</p>\n                  </li>\n                  <li>\n                     <p>Provisioned IOPS storage (io1, io2): Must be an integer from 100 to 65536.</p>\n                  </li>\n                  <li>\n                     <p>Magnetic storage (standard): Must be an integer from 5 to 3072.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for Oracle</dt>\n            <dd>\n               <p>Constraints to the amount of storage for each storage type are the following:</p>\n               <ul>\n                  <li>\n                     <p>General Purpose (SSD) storage (gp2, gp3): Must be an integer from 20 to 65536.</p>\n                  </li>\n                  <li>\n                     <p>Provisioned IOPS storage (io1, io2): Must be an integer from 100 to 65536.</p>\n                  </li>\n                  <li>\n                     <p>Magnetic storage (standard): Must be an integer from 10 to 3072.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for PostgreSQL</dt>\n            <dd>\n               <p>Constraints to the amount of storage for each storage type are the following:</p>\n               <ul>\n                  <li>\n                     <p>General Purpose (SSD) storage (gp2, gp3): Must be an integer from 20 to 65536.</p>\n                  </li>\n                  <li>\n                     <p>Provisioned IOPS storage (io1, io2): Must be an integer from 100 to 65536.</p>\n                  </li>\n                  <li>\n                     <p>Magnetic storage (standard): Must be an integer from 5 to 3072.</p>\n                  </li>\n               </ul>\n            </dd>\n            <dt>RDS for SQL Server</dt>\n            <dd>\n               <p>Constraints to the amount of storage for each storage type are the following:</p>\n               <ul>\n                  <li>\n                     <p>General Purpose (SSD) storage (gp2, gp3):</p>\n                     <ul>\n                        <li>\n                           <p>Enterprise and Standard editions: Must be an integer from 20 to 16384.</p>\n                        </li>\n                        <li>\n                           <p>Web and Express editions: Must be an integer from 20 to 16384.</p>\n                        </li>\n                     </ul>\n                  </li>\n                  <li>\n                     <p>Provisioned IOPS storage (io1, io2):</p>\n                     <ul>\n                        <li>\n                           <p>Enterprise and Standard editions: Must be an integer from 100 to 16384.</p>\n                        </li>\n                        <li>\n                           <p>Web and Express editions: Must be an integer from 100 to 16384.</p>\n                        </li>\n                     </ul>\n                  </li>\n                  <li>\n                     <p>Magnetic storage (standard):</p>\n                     <ul>\n                        <li>\n                           <p>Enterprise and Standard editions: Must be an integer from 20 to 1024.</p>\n                        </li>\n                        <li>\n                           <p>Web and Express editions: Must be an integer from 20 to 1024.</p>\n                        </li>\n                     </ul>\n                  </li>\n               </ul>\n            </dd>\n         </dl>"}))
    CreateDBInstanceMessage.add_member(:db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceClass', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The compute and memory capacity of the DB instance, for example <code>db.m5.large</code>.\n          Not all DB instance classes are available in all Amazon Web Services Regions, or for all database engines.\n          For the full list of DB instance classes, and availability for your engine, see\n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">DB instance \n          classes</a> in the <i>Amazon RDS User Guide</i> or \n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Concepts.DBInstanceClass.html\">Aurora \n          DB instance classes</a> in the <i>Amazon Aurora User Guide</i>.</p>", "smithy.api#required" => {}}))
    CreateDBInstanceMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The database engine to use for this DB instance.</p>\n         <p>Not every database engine is available in every Amazon Web Services Region.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>aurora-mysql</code> (for Aurora MySQL DB instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>aurora-postgresql</code> (for Aurora PostgreSQL DB instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-ee</code> (for RDS Custom for Oracle DB instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-ee-cdb</code> (for RDS Custom for Oracle DB instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-se2</code> (for RDS Custom for Oracle DB instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-se2-cdb</code> (for RDS Custom for Oracle DB\n                    instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-sqlserver-ee</code> (for RDS Custom for SQL Server DB instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-sqlserver-se</code> (for RDS Custom for SQL Server DB instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-sqlserver-web</code> (for RDS Custom for SQL Server DB instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-sqlserver-dev</code> (for RDS Custom for SQL Server DB instances)</p>\n            </li>\n            <li>\n               <p>\n                  <code>db2-ae</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>db2-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mariadb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>postgres</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ex</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-web</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateDBInstanceMessage.add_member(:master_username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUsername', traits: {"smithy.api#documentation" => "<p>The name for the master user.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The name for the master user is managed by the DB cluster.</p>\n         <p>This setting is required for RDS DB instances.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 16 letters, numbers, or underscores.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't be a reserved word for the chosen database engine.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>The password for the master user.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The password for the master user is managed by the DB\n            cluster.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be specified if <code>ManageMasterUserPassword</code> is turned on.</p>\n            </li>\n            <li>\n               <p>Can include any printable ASCII character except \"/\", \"\"\", or \"@\". For RDS for Oracle, can't include the \"&\" (ampersand) or  the \"'\" (single quotes) character.</p>\n            </li>\n         </ul>\n         <p>Length Constraints:</p>\n         <ul>\n            <li>\n               <p>RDS for Db2 - Must contain from 8 to 255 characters.</p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - Must contain from 8 to 41 characters.</p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - Must contain from 8 to 128 characters.</p>\n            </li>\n            <li>\n               <p>RDS for MySQL - Must contain from 8 to 41 characters.</p>\n            </li>\n            <li>\n               <p>RDS for Oracle - Must contain from 8 to 30 characters.</p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - Must contain from 8 to 128 characters.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:db_security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: DBSecurityGroupNameList, location_name: 'DBSecurityGroups', traits: {"smithy.api#documentation" => "<p>A list of DB security groups to associate with this DB instance.</p>\n         <p>This setting applies to the legacy EC2-Classic platform, which is no longer used to create \n            new DB instances. Use the <code>VpcSecurityGroupIds</code> setting instead.</p>"}))
    CreateDBInstanceMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of Amazon EC2 VPC security groups to associate with this DB instance.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The associated list of EC2 VPC security groups is managed by\n          the DB cluster.</p>\n         <p>Default: The default EC2 VPC security group for the DB subnet group's VPC.</p>"}))
    CreateDBInstanceMessage.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZone', traits: {"smithy.api#documentation" => "<p>The Availability Zone (AZ) where the database will be created. For information on\n        Amazon Web Services Regions and Availability Zones, see \n        <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.RegionsAndAvailabilityZones.html\">Regions\n        and Availability Zones</a>.</p>\n         <p>For Amazon Aurora, each Aurora DB cluster hosts copies of its storage in three separate Availability Zones. Specify one of these \n            Availability Zones. Aurora automatically chooses an appropriate Availability Zone if you don't specify one.</p>\n         <p>Default: A random, system-chosen Availability Zone in the endpoint's Amazon Web Services Region.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>The <code>AvailabilityZone</code> parameter can't be specified if the DB instance is a Multi-AZ deployment.</p>\n            </li>\n            <li>\n               <p>The specified Availability Zone must be in the same Amazon Web Services Region as the current endpoint.</p>\n            </li>\n         </ul>\n         <p>Example: <code>us-east-1d</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>A DB subnet group to associate with this DB instance.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the name of an existing DB subnet group.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The time range each week during which system maintenance can occur. \n          For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Maintenance.html#Concepts.DBMaintenance\">Amazon RDS Maintenance Window</a> \n          in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>The default is a 30-minute window selected at random from an\n            8-hour block of time for each Amazon Web Services Region, occurring on a random day of the\n            week.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>ddd:hh24:mi-ddd:hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>The day values must be <code>mon | tue | wed | thu | fri | sat | sun</code>. </p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred backup window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to associate with this DB instance. If you don't specify a value, then \n          Amazon RDS uses the default DB parameter group for the specified DB engine and version.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 255 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days for which automated backups are retained. Setting this parameter to a positive number enables \n          backups. Setting this parameter to <code>0</code> disables automated backups.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The retention period for automated backups is managed by the DB cluster.</p>\n         <p>Default: <code>1</code>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a value from 0 to 35.</p>\n            </li>\n            <li>\n               <p>Can't be set to 0 if the DB instance is a source to read replicas.</p>\n            </li>\n            <li>\n               <p>Can't be set to 0 for an RDS Custom for Oracle DB instance.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created\n        if automated backups are enabled,\n        using the <code>BackupRetentionPeriod</code> parameter.\n          The default is a 30-minute window selected at random from an\n          8-hour block of time for each Amazon Web Services Region. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_WorkingWithAutomatedBackups.html#USER_WorkingWithAutomatedBackups.BackupWindow\">Backup window</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The daily time range for creating automated backups is managed by\n          the DB cluster.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the database accepts connections.</p>\n         <p>This setting doesn't apply to Aurora DB instances. The port number is managed by the cluster.</p>\n         <p>Valid Values: <code>1150-65535</code>\n         </p>\n         <p>Default:</p>\n         <ul>\n            <li>\n               <p>RDS for Db2 - <code>50000</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - <code>3306</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - <code>1433</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>3306</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Oracle - <code>1521</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>5432</code>\n               </p>\n            </li>\n         </ul>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>For RDS for Microsoft SQL Server, the value can't be <code>1234</code>, <code>1434</code>,\n                <code>3260</code>, <code>3343</code>, <code>3389</code>, <code>47001</code>, or\n                <code>49152-49156</code>.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is a Multi-AZ deployment. You can't set \n          the <code>AvailabilityZone</code> parameter if the DB instance is a Multi-AZ deployment.</p>\n         <p>This setting doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora (DB instance Availability Zones (AZs) are managed by the DB cluster.)</p>\n            </li>\n            <li>\n               <p>RDS Custom</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to use.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The version number of the database engine the DB\n            instance uses is managed by the DB cluster.</p>\n         <p>For a list of valid engine versions, use the <code>DescribeDBEngineVersions</code>\n            operation.</p>\n         <p>The following are the database engines and links to information about the major and minor versions that are available with \n          Amazon RDS. Not every database engine is available for every Amazon Web Services Region.</p>\n         <dl>\n            <dt>Amazon RDS Custom for Oracle</dt>\n            <dd>\n               <p>A custom engine version (CEV) that you have previously created. This setting is required for RDS Custom for Oracle. The CEV \n                name has the following format: 19.<i>customized_string</i>. A valid CEV name is  \n                <code>19.my_cev1</code>. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-creating.html#custom-creating.create\">\n                Creating an RDS Custom for Oracle DB instance</a> in the <i>Amazon RDS User Guide</i>.</p>\n            </dd>\n            <dt>Amazon RDS Custom for SQL Server</dt>\n            <dd>\n               <p>See <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-reqs-limits-MS.html\">RDS Custom for SQL Server general requirements</a> \n                in the <i>Amazon RDS User Guide</i>.</p>\n            </dd>\n            <dt>RDS for Db2</dt>\n            <dd>\n               <p>For information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_Db2.html#Db2.Concepts.VersionMgmt\">Db2 on Amazon RDS versions</a> in the \n                <i>Amazon RDS User Guide</i>.</p>\n            </dd>\n            <dt>RDS for MariaDB</dt>\n            <dd>\n               <p>For information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_MariaDB.html#MariaDB.Concepts.VersionMgmt\">MariaDB on Amazon RDS versions</a> in the \n                <i>Amazon RDS User Guide</i>.</p>\n            </dd>\n            <dt>RDS for Microsoft SQL Server</dt>\n            <dd>\n               <p>For information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_SQLServer.html#SQLServer.Concepts.General.VersionSupport\">Microsoft SQL Server versions on Amazon RDS</a> in the \n                  <i>Amazon RDS User Guide</i>.</p>\n            </dd>\n            <dt>RDS for MySQL</dt>\n            <dd>\n               <p>For information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_MySQL.html#MySQL.Concepts.VersionMgmt\">MySQL on Amazon RDS versions</a> in the \n                <i>Amazon RDS User Guide</i>.</p>\n            </dd>\n            <dt>RDS for Oracle</dt>\n            <dd>\n               <p>For information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Appendix.Oracle.PatchComposition.html\">Oracle Database Engine release notes</a> in the \n                <i>Amazon RDS User Guide</i>.</p>\n            </dd>\n            <dt>RDS for PostgreSQL</dt>\n            <dd>\n               <p>For information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_PostgreSQL.html#PostgreSQL.Concepts\">Amazon RDS for PostgreSQL versions and extensions</a> in the \n                  <i>Amazon RDS User Guide</i>.</p>\n            </dd>\n         </dl>"}))
    CreateDBInstanceMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether minor engine upgrades are applied automatically to the DB instance during the maintenance window. \n          By default, minor engine upgrades are applied automatically.</p>\n         <p>If you create an RDS Custom DB instance, you must set <code>AutoMinorVersionUpgrade</code> to \n          <code>false</code>.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    CreateDBInstanceMessage.add_member(:license_model, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LicenseModel', traits: {"smithy.api#documentation" => "<p>The license model information for this DB instance.</p>\n         <note>\n            <p>License models for RDS for Db2 require additional configuration. The Bring Your\n                Own License (BYOL) model requires a custom parameter group and an Amazon Web Services License Manager self-managed license. The Db2 license through\n                Amazon Web Services Marketplace model requires an Amazon Web Services Marketplace subscription. For more\n                information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/db2-licensing.html\">Amazon RDS for Db2 licensing\n                    options</a> in the <i>Amazon RDS User Guide</i>.</p>\n            <p>The default for RDS for Db2 is <code>bring-your-own-license</code>.</p>\n         </note>\n         <p>This setting doesn't apply to Amazon Aurora or RDS Custom DB instances.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>RDS for Db2 - <code>bring-your-own-license | marketplace-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - <code>general-public-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - <code>license-included</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>general-public-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Oracle - <code>bring-your-own-license | license-included</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql-license</code>\n               </p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The amount of Provisioned IOPS (input/output operations per second) to initially allocate for the DB instance.\n          For information about valid IOPS values, see \n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_Storage.html\">Amazon RDS DB instance storage</a> \n          in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. Storage is managed by the DB cluster.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>For RDS for Db2, MariaDB, MySQL, Oracle, and PostgreSQL - Must be a multiple between .5 and 50 \n          of the storage amount for the DB instance.</p>\n            </li>\n            <li>\n               <p>For RDS for SQL Server - Must be a multiple between 1 and 50 of the storage amount for the DB instance.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The option group to associate the DB instance with.</p>\n         <p>Permanent options, such as the TDE option for Oracle Advanced Security TDE, can't be removed \n          from an option group. Also, that option group can't be removed from a DB instance after it is \n          associated with a DB instance.</p>\n         <p>This setting doesn't apply to Amazon Aurora or RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:character_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CharacterSetName', traits: {"smithy.api#documentation" => "<p>For supported engines, the character set (<code>CharacterSet</code>) to associate the DB instance with.</p>\n         <p>This setting doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora - The character set is managed by\n          the DB cluster. For more information, see <code>CreateDBCluster</code>.</p>\n            </li>\n            <li>\n               <p>RDS Custom - However, if you need to change the character set, \n          you can change it on the database itself.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:nchar_character_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NcharCharacterSetName', traits: {"smithy.api#documentation" => "<p>The name of the NCHAR character set for the Oracle DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is publicly accessible.</p>\n         <p>When the DB instance is publicly accessible and you connect from outside of the DB instance's virtual private cloud (VPC), \n              its Domain Name System (DNS) endpoint resolves to the public IP address. When you connect from within the same VPC as the DB instance, \n              the endpoint resolves to the private IP address. Access to the DB instance is ultimately controlled by the security group it uses. \n              That public access is not permitted if the security group assigned to the DB instance doesn't permit it.</p>\n         <p>When the DB instance isn't publicly accessible, it is an internal DB instance with a DNS name that resolves to a private IP address.</p>\n         <p>Default: The default behavior varies depending on whether <code>DBSubnetGroupName</code> is specified.</p>\n         <p>If <code>DBSubnetGroupName</code> isn't specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the default VPC in the target Region doesn’t have an internet gateway attached to it, the DB instance is private.</p>\n            </li>\n            <li>\n               <p>If the default VPC in the target Region has an internet gateway attached to it, the DB instance is public.</p>\n            </li>\n         </ul>\n         <p>If <code>DBSubnetGroupName</code> is specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the subnets are part of a VPC that doesn’t have an internet gateway attached to it, the DB instance is private.</p>\n            </li>\n            <li>\n               <p>If the subnets are part of a VPC that has an internet gateway attached to it, the DB instance is public.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Tags to assign to the DB instance.</p>"}))
    CreateDBInstanceMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of the DB cluster that this DB instance will belong to.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type to associate with the DB instance.</p>\n         <p>If you specify <code>io1</code>, <code>io2</code>, or <code>gp3</code>, you must also include a value for the\n            <code>Iops</code> parameter.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. Storage is managed by the DB cluster.</p>\n         <p>Valid Values: <code>gp2 | gp3 | io1 | io2 | standard</code>\n         </p>\n         <p>Default: <code>io1</code>, if the <code>Iops</code> parameter is specified. Otherwise,\n                <code>gp3</code>.</p>"}))
    CreateDBInstanceMessage.add_member(:tde_credential_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialArn', traits: {"smithy.api#documentation" => "<p>The ARN from the key store with which to associate the instance for TDE encryption.</p>\n         <p>This setting doesn't apply to Amazon Aurora or RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:tde_credential_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialPassword', traits: {"smithy.api#documentation" => "<p>The password for the given ARN from the key store in order to access the device.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:storage_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'StorageEncrypted', traits: {"smithy.api#documentation" => "<p>Specifes whether the DB instance is encrypted. By default, it isn't encrypted.</p>\n         <p>For RDS Custom DB instances, either enable this setting or leave it unset. Otherwise, Amazon RDS reports an error.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The encryption for DB instances is managed by the DB cluster.</p>"}))
    CreateDBInstanceMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for an encrypted DB instance.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n          To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The Amazon Web Services KMS key identifier is managed by\n          the DB cluster. For more information, see <code>CreateDBCluster</code>.</p>\n         <p>If <code>StorageEncrypted</code> is enabled, and you do\n        not specify a value for the <code>KmsKeyId</code> parameter, then\n        Amazon RDS uses your default KMS key. There is a  \n        default KMS key for your Amazon Web Services account. Your Amazon Web Services account has a different\n        default KMS key for each Amazon Web Services Region.</p>\n         <p>For Amazon RDS Custom, a KMS key is required for DB instances. For most RDS engines, if you leave this parameter empty \n          while enabling <code>StorageEncrypted</code>, the engine uses the default KMS key. However, RDS Custom \n          doesn't use the default key when this parameter is empty. You must explicitly specify a key.</p>"}))
    CreateDBInstanceMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The Active Directory directory ID to create the DB instance in. Currently, you can create only Db2, MySQL, Microsoft SQL \n          Server, Oracle, and PostgreSQL DB instances in an Active Directory Domain.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/kerberos-authentication.html\">\n           Kerberos Authentication</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora (The domain is managed by the DB cluster.)</p>\n            </li>\n            <li>\n               <p>RDS Custom</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:domain_fqdn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainFqdn', traits: {"smithy.api#documentation" => "<p>The fully qualified domain name (FQDN) of an Active Directory domain.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mymanagedADtest.mymanagedAD.mydomain</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:domain_ou, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainOu', traits: {"smithy.api#documentation" => "<p>The Active Directory organizational unit for your DB instance to join.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the distinguished name format.</p>\n            </li>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>OU=mymanagedADtestOU,DC=mymanagedADtest,DC=mymanagedAD,DC=mydomain</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:domain_auth_secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainAuthSecretArn', traits: {"smithy.api#documentation" => "<p>The ARN for the Secrets Manager secret with the credentials for the user joining the domain.</p>\n         <p>Example: <code>arn:aws:secretsmanager:region:account-number:secret:myselfmanagedADtestsecret-123456</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:domain_dns_ips, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'DomainDnsIps', traits: {"smithy.api#documentation" => "<p>The IPv4 DNS IP addresses of your primary and secondary Active Directory domain controllers.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Two IP addresses must be provided.  If there isn't a secondary domain controller, use the IP address of the primary domain controller for both entries in the list.</p>\n            </li>\n         </ul>\n         <p>Example: <code>123.124.125.126,234.235.236.237</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy tags from the DB instance to snapshots of the DB instance. By default, tags are not copied.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. Copying tags to snapshots is managed by the DB cluster. Setting this\n          value for an Aurora DB instance has no effect on the DB cluster setting.</p>"}))
    CreateDBInstanceMessage.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are collected for \n          the DB instance. To disable collection of Enhanced Monitoring metrics, specify <code>0</code>.</p>\n         <p>If <code>MonitoringRoleArn</code> is specified, then you must set <code>MonitoringInterval</code>\n      to a value other than <code>0</code>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Valid Values: <code>0 | 1 | 5 | 10 | 15 | 30 | 60</code>\n         </p>\n         <p>Default: <code>0</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN for the IAM role that permits RDS to send enhanced monitoring metrics to Amazon CloudWatch Logs. For\n          example, <code>arn:aws:iam:123456789012:role/emaccess</code>. For information on creating a monitoring role,\n      see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Monitoring.OS.html#USER_Monitoring.OS.Enabling\">Setting Up and Enabling Enhanced Monitoring</a> \n          in the <i>Amazon RDS User Guide</i>.</p>\n         <p>If <code>MonitoringInterval</code> is set to a value other than <code>0</code>, then you must supply a <code>MonitoringRoleArn</code> value.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM role to use when making API calls to the Directory Service.</p>\n         <p>This setting doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora (The domain is managed by the DB cluster.)</p>\n            </li>\n            <li>\n               <p>RDS Custom</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:promotion_tier, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PromotionTier', traits: {"smithy.api#documentation" => "<p>The order of priority in which an Aurora Replica is promoted to the primary instance \n          after a failure of the existing primary instance. For more information, \n      see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Concepts.AuroraHighAvailability.html#Aurora.Managing.FaultTolerance\">\n          Fault Tolerance for an Aurora DB Cluster</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Default: <code>1</code>\n         </p>\n         <p>Valid Values: <code>0 - 15</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:timezone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Timezone', traits: {"smithy.api#documentation" => "<p>The time zone of the DB instance. \n            The time zone parameter is currently supported only by <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/db2-time-zone\">RDS for Db2</a> and\n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_SQLServer.html#SQLServer.Concepts.General.TimeZone\">RDS for SQL Server</a>.</p>"}))
    CreateDBInstanceMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access Management\n            (IAM) accounts to database accounts. By default, mapping isn't enabled.</p>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\">\n                IAM Database Authentication for MySQL and PostgreSQL</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora (Mapping Amazon Web Services IAM accounts to database accounts is managed by the DB cluster.)</p>\n            </li>\n            <li>\n               <p>RDS Custom</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:database_insights_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseInsightsMode, location_name: 'DatabaseInsightsMode', traits: {"smithy.api#documentation" => "<p>The mode of Database Insights to enable for the DB instance.</p>\n         <note>\n            <p>Aurora DB instances inherit this value from the DB cluster, so you can't change this value.</p>\n         </note>"}))
    CreateDBInstanceMessage.add_member(:enable_performance_insights, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnablePerformanceInsights', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable Performance Insights for the DB instance. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PerfInsights.html\">Using Amazon Performance Insights</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>If you don't specify a value for <code>PerformanceInsightsKMSKeyId</code>, then Amazon RDS \n            uses your default KMS key. There is a default KMS key for your Amazon Web Services account. \n            Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:performance_insights_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PerformanceInsightsRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain Performance Insights data.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>7</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <i>month</i> * 31, where <i>month</i> is a number of months from 1-23. \n                Examples: <code>93</code> (3 months * 31), <code>341</code> (11 months * 31), <code>589</code> (19 months * 31)</p>\n            </li>\n            <li>\n               <p>\n                  <code>731</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: <code>7</code> days</p>\n         <p>If you specify a retention period that isn't valid, such as <code>94</code>,  Amazon RDS returns an error.</p>"}))
    CreateDBInstanceMessage.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>The list of log types to enable for exporting to CloudWatch Logs. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">\n            Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora (CloudWatch Logs exports are managed by the DB cluster.)</p>\n            </li>\n            <li>\n               <p>RDS Custom</p>\n            </li>\n         </ul>\n         <p>The following values are valid for each DB engine:</p>\n         <ul>\n            <li>\n               <p>RDS for Db2 - <code>diag.log | notify.log | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - <code>audit | error | general | slowquery | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - <code>agent | error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>audit | error | general | slowquery | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Oracle - <code>alert | audit | listener | trace | oemagent</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql | upgrade | iam-db-auth-error</code>\n               </p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessorFeatureList, location_name: 'ProcessorFeatures', traits: {"smithy.api#documentation" => "<p>The number of CPU cores and the number of threads per core for the DB instance class of the DB instance.</p>\n         <p>This setting doesn't apply to Amazon Aurora or RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance has deletion protection enabled. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_DeleteInstance.html\">\n                Deleting a DB Instance</a>.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. You can enable or disable deletion protection for the DB cluster. \n            For more information, see <code>CreateDBCluster</code>. DB instances in a DB \n            cluster can be deleted even when deletion protection is enabled for the DB cluster.</p>"}))
    CreateDBInstanceMessage.add_member(:max_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxAllocatedStorage', traits: {"smithy.api#documentation" => "<p>The upper limit in gibibytes (GiB) to which Amazon RDS can automatically scale the storage of the DB instance.</p>\n         <p>For more information about this setting, including limitations that apply to it, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PIOPS.StorageTypes.html#USER_PIOPS.Autoscaling\">\n                Managing capacity automatically with Amazon RDS storage autoscaling</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora (Storage is managed by the DB cluster.)</p>\n            </li>\n            <li>\n               <p>RDS Custom</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:enable_customer_owned_ip, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableCustomerOwnedIp', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable a customer-owned IP address (CoIP) for an RDS\n            on Outposts DB instance.</p>\n         <p>A <i>CoIP</i> provides local or external connectivity to resources in\n            your Outpost subnets through your on-premises network. For some use cases, a CoIP can\n            provide lower latency for connections to the DB instance from outside of its virtual\n            private cloud (VPC) on your local network.</p>\n         <p>For more information about RDS on Outposts, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-on-outposts.html\">Working with Amazon RDS on Amazon Web Services Outposts</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about CoIPs, see <a href=\"https://docs.aws.amazon.com/outposts/latest/userguide/routing.html#ip-addressing\">Customer-owned IP addresses</a> \n            in the <i>Amazon Web Services Outposts User Guide</i>.</p>"}))
    CreateDBInstanceMessage.add_member(:custom_iam_instance_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CustomIamInstanceProfile', traits: {"smithy.api#documentation" => "<p>The instance profile associated with the underlying Amazon EC2 instance of an \n            RDS Custom DB instance.</p>\n         <p>This setting is required for RDS Custom.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>The profile must exist in your account.</p>\n            </li>\n            <li>\n               <p>The profile must have an IAM role that Amazon EC2 has permissions to assume.</p>\n            </li>\n            <li>\n               <p>The instance profile name and the associated IAM role name must start with the prefix <code>AWSRDSCustom</code>.</p>\n            </li>\n         </ul>\n         <p>For the list of permissions required for the IAM role, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-setup-orcl.html#custom-setup-orcl.iam-vpc\">\n                Configure IAM and your VPC</a> in the <i>Amazon RDS User Guide</i>.</p>"}))
    CreateDBInstanceMessage.add_member(:backup_target, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BackupTarget', traits: {"smithy.api#documentation" => "<p>The location for storing automated backups and manual snapshots.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>local</code> (Dedicated Local Zone)</p>\n            </li>\n            <li>\n               <p>\n                  <code>outposts</code> (Amazon Web Services Outposts)</p>\n            </li>\n            <li>\n               <p>\n                  <code>region</code> (Amazon Web Services Region)</p>\n            </li>\n         </ul>\n         <p>Default: <code>region</code>\n         </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-on-outposts.html\">Working \n            with Amazon RDS on Amazon Web Services Outposts</a> in the <i>Amazon RDS User Guide</i>.</p>"}))
    CreateDBInstanceMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB instance.</p>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB instance. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Valid Values: <code>IPV4 | DUAL</code>\n         </p>"}))
    CreateDBInstanceMessage.add_member(:storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'StorageThroughput', traits: {"smithy.api#documentation" => "<p>The storage throughput value, in mebibyte per second (MiBps), for the DB instance.</p>\n         <p>This setting applies only to the <code>gp3</code> storage type.</p>\n         <p>This setting doesn't apply to Amazon Aurora or RDS Custom DB instances.</p>"}))
    CreateDBInstanceMessage.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't manage the master user password with Amazon Web Services Secrets Manager if <code>MasterUserPassword</code> \n                    is specified.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and \n            managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets \n            Manager for the DB instance.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>If you don't specify <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> \n            KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't \n            use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer \n            managed KMS key.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>"}))
    CreateDBInstanceMessage.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>The CA certificate identifier to use for the DB instance's server certificate.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n            instance</a> in the <i>Amazon RDS User Guide</i> and \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL.html\">\n            Using SSL/TLS to encrypt a connection to a DB cluster</a> in the <i>Amazon Aurora \n            User Guide</i>.</p>"}))
    CreateDBInstanceMessage.add_member(:db_system_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSystemId', traits: {"smithy.api#documentation" => "<p>The Oracle system identifier (SID), which is the name of the Oracle database instance that \n            manages your database files. In this context, the term \"Oracle database instance\" refers exclusively \n            to the system global area (SGA) and Oracle background processes. If you don't specify a SID, \n            the value defaults to <code>RDSCDB</code>. The Oracle SID is also the name of your CDB.</p>"}))
    CreateDBInstanceMessage.add_member(:dedicated_log_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DedicatedLogVolume', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB instance has a dedicated log volume (DLV) enabled.</p>"}))
    CreateDBInstanceMessage.add_member(:multi_tenant, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiTenant', traits: {"smithy.api#documentation" => "<p>Specifies whether to use the multi-tenant configuration or the single-tenant\n            configuration (default). This parameter only applies to RDS for Oracle container\n            database (CDB) engines.</p>\n         <p>Note the following restrictions: </p>\n         <ul>\n            <li>\n               <p>The DB engine that you specify in the request must support the multi-tenant\n                    configuration. If you attempt to enable the multi-tenant configuration on a DB\n                    engine that doesn't support it, the request fails.</p>\n            </li>\n            <li>\n               <p>If you specify the multi-tenant configuration when you create your DB instance,\n                    you can't later modify this DB instance to use the single-tenant configuration.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceMessage.add_member(:engine_lifecycle_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineLifecycleSupport', traits: {"smithy.api#documentation" => "<p>The life cycle type for this DB instance.</p>\n         <note>\n            <p>By default, this value is set to <code>open-source-rds-extended-support</code>, which enrolls your DB instance into Amazon RDS Extended Support. \n              At the end of standard support, you can avoid charges for Extended Support by setting the value to <code>open-source-rds-extended-support-disabled</code>. In this case, \n              creating the DB instance will fail if the DB major version is past its end of standard support date.</p>\n         </note>\n         <p>This setting applies only to RDS for MySQL and RDS for PostgreSQL. For Amazon Aurora DB instances, the life cycle type is managed by the DB cluster.</p>\n         <p>You can use this setting to enroll your DB instance into Amazon RDS Extended Support. With RDS Extended Support, \n        you can run the selected major engine version on your DB instance past the end of standard support for that engine version. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon RDS</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Valid Values: <code>open-source-rds-extended-support | open-source-rds-extended-support-disabled</code>\n         </p>\n         <p>Default: <code>open-source-rds-extended-support</code>\n         </p>"}))
    CreateDBInstanceMessage.type = Types::CreateDBInstanceMessage
    CreateDBInstanceReadReplicaMessage.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The DB instance identifier of the read replica. This identifier is the unique key\n            that identifies a DB instance. This parameter is stored as a lowercase string.</p>", "smithy.api#required" => {}}))
    CreateDBInstanceReadReplicaMessage.add_member(:source_db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDBInstanceIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of the DB instance that will act as the source for the read replica.\n            Each DB instance can have up to 15 read replicas, except for the following\n            engines:</p>\n         <ul>\n            <li>\n               <p>Db2 - Can have up to three replicas.</p>\n            </li>\n            <li>\n               <p>Oracle - Can have up to five read replicas.</p>\n            </li>\n            <li>\n               <p>SQL Server - Can have up to five read replicas.</p>\n            </li>\n         </ul>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be the identifier of an existing Db2, MariaDB, MySQL, Oracle, PostgreSQL, or SQL Server DB\n                    instance.</p>\n            </li>\n            <li>\n               <p>Can't be specified if the <code>SourceDBClusterIdentifier</code> parameter is\n                    also specified.</p>\n            </li>\n            <li>\n               <p>For the limitations of Oracle read replicas, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/oracle-read-replicas.limitations.html#oracle-read-replicas.limitations.versions-and-licenses\">Version and licensing considerations for RDS for Oracle replicas</a> in the\n                  <i>Amazon RDS User Guide</i>.</p>\n            </li>\n            <li>\n               <p>For the limitations of SQL Server read replicas, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/SQLServer.ReadReplicas.html#SQLServer.ReadReplicas.Limitations\">Read replica limitations with SQL Server</a> in the <i>Amazon RDS User Guide</i>.</p>\n            </li>\n            <li>\n               <p>The specified DB instance must have automatic backups enabled, that is, its backup\n                    retention period must be greater than 0.</p>\n            </li>\n            <li>\n               <p>If the source DB instance is in the same Amazon Web Services Region as the read replica, specify a valid DB\n                    instance identifier.</p>\n            </li>\n            <li>\n               <p>If the source DB instance is in a different Amazon Web Services Region from the read\n                    replica, specify a valid DB instance ARN. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Tagging.ARN.html#USER_Tagging.ARN.Constructing\">Constructing an ARN for Amazon RDS</a> in the <i>Amazon RDS User\n                        Guide</i>. This doesn't apply to SQL Server or RDS Custom, which\n                    don't support cross-Region replicas.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceClass', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of the read replica, for example\n                db.m4.large. Not all DB instance classes are available in all Amazon Web Services\n            Regions, or for all database engines. For the full list of DB instance classes, and\n            availability for your engine, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">DB Instance Class</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Default: Inherits the value from the source DB instance.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZone', traits: {"smithy.api#documentation" => "<p>The Availability Zone (AZ) where the read replica will be created.</p>\n         <p>Default: A random, system-chosen Availability Zone in the endpoint's Amazon Web Services Region.</p>\n         <p>Example: <code>us-east-1d</code>\n         </p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number that the DB instance uses for connections.</p>\n         <p>Valid Values: <code>1150-65535</code>\n         </p>\n         <p>Default: Inherits the value from the source DB instance.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p>Specifies whether the read replica is in a Multi-AZ deployment.</p>\n         <p>You can create a read replica as a Multi-AZ DB instance. RDS creates a standby of your\n            replica in another Availability Zone for failover support for the replica. Creating your\n            read replica as a Multi-AZ DB instance is independent of whether the source is a\n            Multi-AZ DB instance or a Multi-AZ DB cluster.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether to automatically apply minor engine upgrades to the\n            read replica during the maintenance window.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Default: Inherits the value from the source DB instance.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The amount of Provisioned IOPS (input/output operations per second) to initially allocate for the DB instance.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The option group to associate the DB instance with. If not specified, RDS uses the option group\n            associated with the source DB instance or cluster.</p>\n         <note>\n            <p>For SQL Server, you must use the option group associated with the source.</p>\n         </note>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to associate with this read replica DB\n            instance.</p>\n         <p>For the Db2 DB engine, if your source DB instance uses the Bring Your Own License\n            model, then a custom parameter group must be associated with the replica. For a same\n            Amazon Web Services Region replica, if you don't specify a custom parameter group, Amazon RDS\n            associates the custom parameter group associated with the source DB instance. For a\n            cross-Region replica, you must specify a custom parameter group. This custom parameter\n            group must include your IBM Site ID and IBM Customer ID. For more information, see\n                <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/db2-licensing.html#db2-prereqs-ibm-info\"> IBM IDs\n                for Bring Your Own License for Db2</a>. </p>\n         <p>For Single-AZ or Multi-AZ DB instance read replica instances, if you don't specify a\n            value for <code>DBParameterGroupName</code>, then Amazon RDS uses the\n                <code>DBParameterGroup</code> of the source DB instance for a same Region read\n            replica, or the default <code>DBParameterGroup</code> for the specified DB engine for a\n            cross-Region read replica.</p>\n         <p>For Multi-AZ DB cluster same Region read replica instances, if you don't specify a\n            value for <code>DBParameterGroupName</code>, then Amazon RDS uses the default\n                <code>DBParameterGroup</code>.</p>\n         <p>Specifying a parameter group for this operation is only supported for MySQL DB\n            instances for cross-Region read replicas, for Multi-AZ DB cluster read replica\n            instances, for Db2 DB instances, and for Oracle DB instances. It isn't supported for\n            MySQL DB instances for same Region read replicas or for RDS Custom.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 255 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is publicly accessible.</p>\n         <p>When the DB cluster is publicly accessible, its Domain Name System (DNS) endpoint\n          resolves to the private IP address from within the DB cluster's virtual private cloud\n          (VPC). It resolves to the public IP address from outside of the DB cluster's VPC. Access\n          to the DB cluster is ultimately controlled by the security group it uses. That public\n          access isn't permitted if the security group assigned to the DB cluster doesn't permit\n          it.</p>\n         <p>When the DB instance isn't publicly accessible, it is an internal DB instance with a DNS name that resolves to a private IP address.</p>\n         <p>For more information, see <a>CreateDBInstance</a>.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    CreateDBInstanceReadReplicaMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>A DB subnet group for the DB instance. The new DB instance is created in the VPC associated with the DB subnet group. If no DB subnet group is specified, then the new DB instance isn't created in a VPC.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the name of an existing DB subnet group.</p>\n            </li>\n            <li>\n               <p>The specified DB subnet group must be in the same Amazon Web Services Region in which the operation is running.</p>\n            </li>\n            <li>\n               <p>All read replicas in one Amazon Web Services Region that are created from the same source DB\n                    instance must either:</p>\n               <ul>\n                  <li>\n                     <p>Specify DB subnet groups from the same VPC. All these read replicas are created in the same\n                            VPC.</p>\n                  </li>\n                  <li>\n                     <p>Not specify a DB subnet group. All these read replicas are created outside of any\n                            VPC.</p>\n                  </li>\n               </ul>\n            </li>\n         </ul>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of Amazon EC2 VPC security groups to associate with the read replica.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Default: The default EC2 VPC security group for the DB subnet group's VPC.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type to associate with the read replica.</p>\n         <p>If you specify <code>io1</code>, <code>io2</code>, or <code>gp3</code>, you must also include a value for the\n            <code>Iops</code> parameter.</p>\n         <p>Valid Values: <code>gp2 | gp3 | io1 | io2 | standard</code>\n         </p>\n         <p>Default: <code>io1</code> if the <code>Iops</code> parameter is specified. Otherwise,\n                <code>gp3</code>.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the read replica to snapshots of\n            the read replica. By default, tags aren't copied.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are\n            collected for the read replica. To disable collection of Enhanced Monitoring metrics,\n            specify <code>0</code>. The default is <code>0</code>.</p>\n         <p>If <code>MonitoringRoleArn</code> is specified, then you must set <code>MonitoringInterval</code>\n      to a value other than <code>0</code>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Valid Values: <code>0, 1, 5, 10, 15, 30, 60</code>\n         </p>\n         <p>Default: <code>0</code>\n         </p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN for the IAM role that permits RDS to send enhanced monitoring metrics to Amazon CloudWatch Logs. For\n      example, <code>arn:aws:iam:123456789012:role/emaccess</code>. For information on creating a monitoring role,\n      go to <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Monitoring.html#USER_Monitoring.OS.IAMRole\">To \n          create an IAM role for Amazon RDS Enhanced Monitoring</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>If <code>MonitoringInterval</code> is set to a value other than 0, then you must \n          supply a <code>MonitoringRoleArn</code> value.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for an encrypted read replica.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>If you create an encrypted read replica in the same Amazon Web Services Region as the source DB\n            instance or Multi-AZ DB cluster, don't specify a value for this parameter. A read\n            replica in the same Amazon Web Services Region is always encrypted with the same KMS key as the source\n            DB instance or cluster.</p>\n         <p>If you create an encrypted read replica in a different Amazon Web Services Region, then you must\n            specify a KMS key identifier for the destination Amazon Web Services Region. KMS keys are specific to\n            the Amazon Web Services Region that they are created in, and you can't use KMS keys from one\n            Amazon Web Services Region in another Amazon Web Services Region.</p>\n         <p>You can't create an encrypted read replica from an unencrypted DB instance or\n            Multi-AZ DB cluster.</p>\n         <p>This setting doesn't apply to RDS Custom, which uses the same KMS key as the primary \n            replica.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:pre_signed_url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreSignedUrl', traits: {"smithy.api#documentation" => "<p>When you are creating a read replica from one Amazon Web Services GovCloud (US) Region to another or\n            from one China Amazon Web Services Region to another, the URL that contains a Signature Version 4\n            signed request for the <code>CreateDBInstanceReadReplica</code> API operation in the\n            source Amazon Web Services Region that contains the source DB instance.</p>\n         <p>This setting applies only to Amazon Web Services GovCloud (US) Regions and \n            China Amazon Web Services Regions. It's ignored in other Amazon Web Services Regions.</p>\n         <p>This setting applies only when replicating from a source DB\n                <i>instance</i>. Source DB clusters aren't supported in Amazon Web Services GovCloud (US) Regions and China Amazon Web Services Regions.</p>\n         <p>You must specify this parameter when you create an encrypted read replica from\n            another Amazon Web Services Region by using the Amazon RDS API. Don't specify\n                <code>PreSignedUrl</code> when you are creating an encrypted read replica in the\n            same Amazon Web Services Region.</p>\n         <p>The presigned URL must be a valid request for the\n                <code>CreateDBInstanceReadReplica</code> API operation that can run in the\n            source Amazon Web Services Region that contains the encrypted source DB instance. The presigned URL\n            request must contain the following parameter values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DestinationRegion</code> - The Amazon Web Services Region that the encrypted read\n                    replica is created in. This Amazon Web Services Region is the same one where the\n                        <code>CreateDBInstanceReadReplica</code> operation is called that contains\n                    this presigned URL.</p>\n               <p>For example, if you create an encrypted DB instance in the us-west-1\n                    Amazon Web Services Region, from a source DB instance in the us-east-2 Amazon Web Services Region, then you\n                    call the <code>CreateDBInstanceReadReplica</code> operation in the us-east-1\n                    Amazon Web Services Region and provide a presigned URL that contains a call to the\n                        <code>CreateDBInstanceReadReplica</code> operation in the us-west-2\n                    Amazon Web Services Region. For this example, the <code>DestinationRegion</code> in the\n                    presigned URL must be set to the us-east-1 Amazon Web Services Region.</p>\n            </li>\n            <li>\n               <p>\n                  <code>KmsKeyId</code> - The KMS key identifier for the key to use to\n                    encrypt the read replica in the destination Amazon Web Services Region. This is the same\n                    identifier for both the <code>CreateDBInstanceReadReplica</code> operation that\n                    is called in the destination Amazon Web Services Region, and the operation contained in the\n                    presigned URL.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SourceDBInstanceIdentifier</code> - The DB instance identifier for the\n                    encrypted DB instance to be replicated. This identifier must be in the Amazon\n                    Resource Name (ARN) format for the source Amazon Web Services Region. For example, if you are\n                    creating an encrypted read replica from a DB instance in the us-west-2\n                    Amazon Web Services Region, then your <code>SourceDBInstanceIdentifier</code> looks like the\n                    following example:\n                        <code>arn:aws:rds:us-west-2:123456789012:instance:mysql-instance1-20161115</code>.</p>\n            </li>\n         </ul>\n         <p>To learn how to generate a Signature Version 4 signed request, see \n            <a href=\"https://docs.aws.amazon.com/AmazonS3/latest/API/sigv4-query-string-auth.html\">Authenticating Requests: Using Query Parameters (Amazon Web Services Signature Version 4)</a> and\n            <a href=\"https://docs.aws.amazon.com/general/latest/gr/signature-version-4.html\">Signature Version 4 Signing Process</a>.</p>\n         <note>\n            <p>If you are using an Amazon Web Services SDK tool or the CLI, you can specify\n                    <code>SourceRegion</code> (or <code>--source-region</code> for the CLI)\n                instead of specifying <code>PreSignedUrl</code> manually. Specifying\n                    <code>SourceRegion</code> autogenerates a presigned URL that is a valid request\n                for the operation that can run in the source Amazon Web Services Region.</p>\n         </note>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access Management\n            (IAM) accounts to database accounts. By default, mapping isn't enabled.</p>\n         <p>For more information about IAM database authentication, see \n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\">\n              IAM Database Authentication for MySQL and PostgreSQL</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:database_insights_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseInsightsMode, location_name: 'DatabaseInsightsMode', traits: {"smithy.api#documentation" => "<p>The mode of Database Insights to enable for the read replica.</p>\n         <note>\n            <p>This setting isn't supported.</p>\n         </note>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:enable_performance_insights, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnablePerformanceInsights', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable Performance Insights for the read replica.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PerfInsights.html\">Using\n            Amazon Performance Insights</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>If you do not specify a value for <code>PerformanceInsightsKMSKeyId</code>, then Amazon RDS \n            uses your default KMS key. There is a default KMS key for your Amazon Web Services account. \n            Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:performance_insights_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PerformanceInsightsRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain Performance Insights data.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>7</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <i>month</i> * 31, where <i>month</i> is a number of months from 1-23. \n                Examples: <code>93</code> (3 months * 31), <code>341</code> (11 months * 31), <code>589</code> (19 months * 31)</p>\n            </li>\n            <li>\n               <p>\n                  <code>731</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: <code>7</code> days</p>\n         <p>If you specify a retention period that isn't valid, such as <code>94</code>,  Amazon RDS returns an error.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>The list of logs that the new DB instance is to export to CloudWatch Logs. The values\n            in the list depend on the DB engine being used. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing\n                Database Logs to Amazon CloudWatch Logs </a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessorFeatureList, location_name: 'ProcessorFeatures', traits: {"smithy.api#documentation" => "<p>The number of CPU cores and the number of threads per core for the DB instance class of the DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:use_default_processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseDefaultProcessorFeatures', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance class of the DB instance uses its default\n            processor features.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable deletion protection for the DB instance. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_DeleteInstance.html\">\n                Deleting a DB Instance</a>.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The Active Directory directory ID to create the DB instance in. Currently, only MySQL, Microsoft SQL \n            Server, Oracle, and PostgreSQL DB instances can be created in an Active Directory Domain.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/kerberos-authentication.html\">\n            Kerberos Authentication</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM role to use when making API calls to the Directory\n            Service.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:domain_fqdn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainFqdn', traits: {"smithy.api#documentation" => "<p>The fully qualified domain name (FQDN) of an Active Directory domain.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mymanagedADtest.mymanagedAD.mydomain</code>\n         </p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:domain_ou, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainOu', traits: {"smithy.api#documentation" => "<p>The Active Directory organizational unit for your DB instance to join.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the distinguished name format.</p>\n            </li>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>OU=mymanagedADtestOU,DC=mymanagedADtest,DC=mymanagedAD,DC=mydomain</code>\n         </p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:domain_auth_secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainAuthSecretArn', traits: {"smithy.api#documentation" => "<p>The ARN for the Secrets Manager secret with the credentials for the user joining the domain.</p>\n         <p>Example: <code>arn:aws:secretsmanager:region:account-number:secret:myselfmanagedADtestsecret-123456</code>\n         </p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:domain_dns_ips, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'DomainDnsIps', traits: {"smithy.api#documentation" => "<p>The IPv4 DNS IP addresses of your primary and secondary Active Directory domain controllers.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Two IP addresses must be provided.  If there isn't a secondary domain controller, use the IP address of the primary domain controller for both entries in the list.</p>\n            </li>\n         </ul>\n         <p>Example: <code>123.124.125.126,234.235.236.237</code>\n         </p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:replica_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ReplicaMode, location_name: 'ReplicaMode', traits: {"smithy.api#documentation" => "<p>The open mode of the replica database.</p>\n         <note>\n            <p>This parameter is only supported for Db2 DB instances and Oracle DB\n                instances.</p>\n         </note>\n         <dl>\n            <dt>Db2</dt>\n            <dd>\n               <p>Standby DB replicas are included in Db2 Advanced Edition (AE) and Db2\n                        Standard Edition (SE). The main use case for standby replicas is\n                        cross-Region disaster recovery. Because it doesn't accept user\n                        connections, a standby replica can't serve a read-only workload.</p>\n               <p>You can create a combination of standby and read-only DB replicas for the\n                        same primary DB instance. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/db2-replication.html\">Working with read\n                            replicas for Amazon RDS for Db2</a> in the <i>Amazon RDS User\n                            Guide</i>.</p>\n               <p>To create standby DB replicas for RDS for Db2, set this parameter to\n                            <code>mounted</code>.</p>\n            </dd>\n            <dt>Oracle</dt>\n            <dd>\n               <p>Mounted DB replicas are included in Oracle Database Enterprise Edition. The main use case for\n                    mounted replicas is cross-Region disaster recovery. The primary database doesn't use Active\n                    Data Guard to transmit information to the mounted replica. Because it doesn't accept\n                    user connections, a mounted replica can't serve a read-only workload.</p>\n               <p>You can create a combination of mounted and read-only DB replicas for the same primary DB instance.\n                    For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/oracle-read-replicas.html\">Working with read replicas for Amazon RDS for Oracle</a> \n                    in the <i>Amazon RDS User Guide</i>.</p>\n               <p>For RDS Custom, you must specify this parameter and set it to\n                        <code>mounted</code>. The value won't be set by default. After replica\n                        creation, you can manage the open mode manually.</p>\n            </dd>\n         </dl>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:max_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxAllocatedStorage', traits: {"smithy.api#documentation" => "<p>The upper limit in gibibytes (GiB) to which Amazon RDS can automatically scale the storage of the DB instance.</p>\n         <p>For more information about this setting, including limitations that apply to it, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PIOPS.StorageTypes.html#USER_PIOPS.Autoscaling\">\n                Managing capacity automatically with Amazon RDS storage autoscaling</a> \n            in the <i>Amazon RDS User Guide</i>.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:custom_iam_instance_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CustomIamInstanceProfile', traits: {"smithy.api#documentation" => "<p>The instance profile associated with the underlying Amazon EC2 instance of an \n            RDS Custom DB instance. The instance profile must meet the following requirements:</p>\n         <ul>\n            <li>\n               <p>The profile must exist in your account.</p>\n            </li>\n            <li>\n               <p>The profile must have an IAM role that Amazon EC2 has permissions to assume.</p>\n            </li>\n            <li>\n               <p>The instance profile name and the associated IAM role name must start with the prefix <code>AWSRDSCustom</code>.</p>\n            </li>\n         </ul>\n         <p>For the list of permissions required for the IAM role, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-setup-orcl.html#custom-setup-orcl.iam-vpc\">\n                Configure IAM and your VPC</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting is required for RDS Custom DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB instance.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>IPV4</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>DUAL</code>\n               </p>\n            </li>\n         </ul>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for read replica. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon RDS User Guide.</i>\n         </p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'StorageThroughput', traits: {"smithy.api#documentation" => "<p>Specifies the storage throughput value for the read replica.</p>\n         <p>This setting doesn't apply to RDS Custom or Amazon Aurora DB instances.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:enable_customer_owned_ip, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableCustomerOwnedIp', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable a customer-owned IP address (CoIP) for an RDS\n            on Outposts read replica.</p>\n         <p>A <i>CoIP</i> provides local or external connectivity to resources in\n            your Outpost subnets through your on-premises network. For some use cases, a CoIP can\n            provide lower latency for connections to the read replica from outside of its virtual\n            private cloud (VPC) on your local network.</p>\n         <p>For more information about RDS on Outposts, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-on-outposts.html\">Working with Amazon RDS on Amazon Web Services Outposts</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about CoIPs, see <a href=\"https://docs.aws.amazon.com/outposts/latest/userguide/routing.html#ip-addressing\">Customer-owned IP addresses</a> \n            in the <i>Amazon Web Services Outposts User Guide</i>.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:backup_target, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BackupTarget', traits: {"smithy.api#documentation" => "<p>The location where RDS stores automated backups and manual snapshots.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>local</code> for Dedicated Local Zones</p>\n            </li>\n            <li>\n               <p>\n                  <code>region</code> for Amazon Web Services Region</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The amount of storage (in gibibytes) to allocate initially for the read replica.\n            Follow the allocation rules specified in <code>CreateDBInstance</code>.</p>\n         <p>This setting isn't valid for RDS for SQL Server.</p>\n         <note>\n            <p>Be sure to allocate enough storage for your read replica so that the create operation can succeed.\n                You can also allocate additional storage for future growth.</p>\n         </note>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:source_db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of the Multi-AZ DB cluster that will act as the source for the read\n            replica. Each DB cluster can have up to 15 read replicas.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be the identifier of an existing Multi-AZ DB cluster.</p>\n            </li>\n            <li>\n               <p>Can't be specified if the <code>SourceDBInstanceIdentifier</code> parameter is\n                    also specified.</p>\n            </li>\n            <li>\n               <p>The specified DB cluster must have automatic backups enabled, that is, its\n                    backup retention period must be greater than 0.</p>\n            </li>\n            <li>\n               <p>The source DB cluster must be in the same Amazon Web Services Region as the read replica.\n                    Cross-Region replication isn't supported.</p>\n            </li>\n         </ul>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:dedicated_log_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DedicatedLogVolume', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB instance has a dedicated log volume (DLV) enabled.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:upgrade_storage_config, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UpgradeStorageConfig', traits: {"smithy.api#documentation" => "<p>Whether to upgrade the storage file system configuration on the read replica. This option\n            migrates the read replica from the old storage file system layout to the preferred layout.</p>"}))
    CreateDBInstanceReadReplicaMessage.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>The CA certificate identifier to use for the read replica's server certificate.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n                instance</a> in the <i>Amazon RDS User Guide</i> and \n                <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL.html\">\n                    Using SSL/TLS to encrypt a connection to a DB cluster</a> in the <i>Amazon Aurora \n                        User Guide</i>.</p>"}))
    CreateDBInstanceReadReplicaMessage.type = Types::CreateDBInstanceReadReplicaMessage
    CreateDBInstanceReadReplicaResult.add_member(:db_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: DBInstance, location_name: 'DBInstance'))
