    CreateDBProxyEndpointRequest.add_member(:db_proxy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DBProxyName, location_name: 'DBProxyName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB proxy associated with the DB proxy endpoint that you create.</p>", "smithy.api#required" => {}}))
    CreateDBProxyEndpointRequest.add_member(:db_proxy_endpoint_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DBProxyEndpointName, location_name: 'DBProxyEndpointName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB proxy endpoint to create.</p>", "smithy.api#required" => {}}))
    CreateDBProxyEndpointRequest.add_member(:vpc_subnet_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'VpcSubnetIds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The VPC subnet IDs for the DB proxy endpoint that you create. You can specify a\n        different set of subnet IDs than for the original DB proxy.</p>", "smithy.api#required" => {}}))
    CreateDBProxyEndpointRequest.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>The VPC security group IDs for the DB proxy endpoint that you create. You can\n        specify a different set of security group IDs than for the original DB proxy.\n        The default is the default security group for the VPC.</p>"}))
    CreateDBProxyEndpointRequest.add_member(:target_role, Smithy::Schema::Shapes::ShapeRef.new(shape: DBProxyEndpointTargetRole, location_name: 'TargetRole', traits: {"smithy.api#documentation" => "<p>The role of the DB proxy endpoint. The role determines whether the endpoint can be used for read/write\n        or only read operations. The default is <code>READ_WRITE</code>. The only role that proxies for RDS for Microsoft SQL Server \n        support is <code>READ_WRITE</code>.</p>"}))
    CreateDBProxyEndpointRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    CreateDBProxyEndpointRequest.type = Types::CreateDBProxyEndpointRequest
    CreateDBProxyEndpointResponse.add_member(:db_proxy_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: DBProxyEndpoint, location_name: 'DBProxyEndpoint', traits: {"smithy.api#documentation" => "<p>The <code>DBProxyEndpoint</code> object that is created by the API operation.\n        The DB proxy endpoint that you create might provide capabilities such as read/write\n        or read-only operations, or using a different VPC than the proxy's default VPC.</p>"}))
    CreateDBProxyEndpointResponse.type = Types::CreateDBProxyEndpointResponse
    CreateDBProxyRequest.add_member(:db_proxy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBProxyName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the proxy. This name must be unique for all proxies owned by your Amazon Web Services account in the specified Amazon Web Services Region. An identifier must begin with a letter and must contain only ASCII letters, digits, and hyphens; it can't end with a hyphen or contain two consecutive hyphens.</p>", "smithy.api#required" => {}}))
    CreateDBProxyRequest.add_member(:engine_family, Smithy::Schema::Shapes::ShapeRef.new(shape: EngineFamily, location_name: 'EngineFamily', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The kinds of databases that the proxy can connect to. \n          This value determines which database network protocol the proxy recognizes when it interprets\n        network traffic to and from the database. For Aurora MySQL, RDS for MariaDB, and RDS for MySQL databases, specify <code>MYSQL</code>. \n        For Aurora PostgreSQL and RDS for PostgreSQL databases, specify <code>POSTGRESQL</code>. For RDS for Microsoft SQL Server, specify \n        <code>SQLSERVER</code>.</p>", "smithy.api#required" => {}}))
    CreateDBProxyRequest.add_member(:auth, Smithy::Schema::Shapes::ShapeRef.new(shape: UserAuthConfigList, location_name: 'Auth', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The authorization mechanism that the proxy uses.</p>", "smithy.api#required" => {}}))
    CreateDBProxyRequest.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'RoleArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM role that the proxy uses to access secrets in Amazon Web Services Secrets Manager.</p>", "smithy.api#required" => {}}))
    CreateDBProxyRequest.add_member(:vpc_subnet_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'VpcSubnetIds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>One or more VPC subnet IDs to associate with the new proxy.</p>", "smithy.api#required" => {}}))
    CreateDBProxyRequest.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>One or more VPC security group IDs to associate with the new proxy.</p>"}))
    CreateDBProxyRequest.add_member(:require_tls, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'RequireTLS', traits: {"smithy.api#documentation" => "<p>Specifies whether Transport Layer Security (TLS) encryption is required for connections to the proxy.\n        By enabling this setting, you can enforce encrypted TLS connections to the proxy.</p>"}))
    CreateDBProxyRequest.add_member(:idle_client_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'IdleClientTimeout', traits: {"smithy.api#documentation" => "<p>The number of seconds that a connection to the proxy can be inactive before the proxy disconnects it. You can set this\n        value higher or lower than the connection timeout limit for the associated database.</p>"}))
    CreateDBProxyRequest.add_member(:debug_logging, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DebugLogging', traits: {"smithy.api#documentation" => "<p>Specifies whether the proxy includes detailed information about SQL statements in its logs.\n        This information helps you to debug issues involving SQL behavior or the performance\n        and scalability of the proxy connections. The debug information includes the text of\n        SQL statements that you submit through the proxy. Thus, only enable this setting\n        when needed for debugging, and only when you have security measures in place to\n        safeguard any sensitive information that appears in the logs.</p>"}))
    CreateDBProxyRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>An optional set of key-value pairs to associate arbitrary data of your choosing with the proxy.</p>"}))
    CreateDBProxyRequest.type = Types::CreateDBProxyRequest
    CreateDBProxyResponse.add_member(:db_proxy, Smithy::Schema::Shapes::ShapeRef.new(shape: DBProxy, location_name: 'DBProxy', traits: {"smithy.api#documentation" => "<p>The <code>DBProxy</code> structure corresponding to the new proxy.</p>"}))
    CreateDBProxyResponse.type = Types::CreateDBProxyResponse
    CreateDBSecurityGroupMessage.add_member(:db_security_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSecurityGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name for the DB security group. This value is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 255 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n            <li>\n               <p>Must not be \"Default\"</p>\n            </li>\n         </ul>\n         <p>Example: <code>mysecuritygroup</code>\n         </p>", "smithy.api#required" => {}}))
    CreateDBSecurityGroupMessage.add_member(:db_security_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSecurityGroupDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The description for the DB security group.</p>", "smithy.api#required" => {}}))
    CreateDBSecurityGroupMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Tags to assign to the DB security group.</p>"}))
    CreateDBSecurityGroupMessage.type = Types::CreateDBSecurityGroupMessage
    CreateDBSecurityGroupResult.add_member(:db_security_group, Smithy::Schema::Shapes::ShapeRef.new(shape: DBSecurityGroup, location_name: 'DBSecurityGroup'))
