    CreateDBShardGroupMessage.add_member(:db_shard_group_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBShardGroupIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB shard group.</p>", "smithy.api#required" => {}}))
    CreateDBShardGroupMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the primary DB cluster for the DB shard group.</p>", "smithy.api#required" => {}}))
    CreateDBShardGroupMessage.add_member(:compute_redundancy, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ComputeRedundancy', traits: {"smithy.api#documentation" => "<p>Specifies whether to create standby standby DB data access shard for the DB shard group. \n            Valid values are the following:</p>\n         <ul>\n            <li>\n               <p>0 - Creates a DB shard group without a standby DB data access shard. This is the default value.</p>\n            </li>\n            <li>\n               <p>1 - Creates a DB shard group with a standby DB data access shard in a different Availability Zone (AZ).</p>\n            </li>\n            <li>\n               <p>2 - Creates a DB shard group with two standby DB data access shard in two different AZs.</p>\n            </li>\n         </ul>"}))
    CreateDBShardGroupMessage.add_member(:max_acu, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MaxACU', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum capacity of the DB shard group in Aurora capacity units (ACUs).</p>", "smithy.api#required" => {}}))
    CreateDBShardGroupMessage.add_member(:min_acu, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MinACU', traits: {"smithy.api#documentation" => "<p>The minimum capacity of the DB shard group in Aurora capacity units (ACUs).</p>"}))
    CreateDBShardGroupMessage.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB shard group is publicly accessible.</p>\n         <p>When the DB shard group is publicly accessible, its Domain Name System (DNS) endpoint resolves to the private IP address from \n            within the DB shard group's virtual private cloud (VPC). It resolves to the public IP address from outside of the DB shard group's VPC. \n            Access to the DB shard group is ultimately controlled by the security group it uses. \n            That public access is not permitted if the security group assigned to the DB shard group doesn't permit it.</p>\n         <p>When the DB shard group isn't publicly accessible, it is an internal DB shard group with a DNS name that resolves to a private IP address.</p>\n         <p>Default: The default behavior varies depending on whether <code>DBSubnetGroupName</code> is specified.</p>\n         <p>If <code>DBSubnetGroupName</code> isn't specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the default VPC in the target Region doesn’t have an internet gateway attached to it, the DB shard group is private.</p>\n            </li>\n            <li>\n               <p>If the default VPC in the target Region has an internet gateway attached to it, the DB shard group is public.</p>\n            </li>\n         </ul>\n         <p>If <code>DBSubnetGroupName</code> is specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the subnets are part of a VPC that doesn’t have an internet gateway attached to it, the DB shard group is private.</p>\n            </li>\n            <li>\n               <p>If the subnets are part of a VPC that has an internet gateway attached to it, the DB shard group is public.</p>\n            </li>\n         </ul>"}))
    CreateDBShardGroupMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    CreateDBShardGroupMessage.type = Types::CreateDBShardGroupMessage
    CreateDBShardGroupOutput.add_member(:db_shard_group_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBShardGroupResourceId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Region-unique, immutable identifier for the DB shard group.</p>"}))
    CreateDBShardGroupOutput.add_member(:db_shard_group_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: DBShardGroupIdentifier, location_name: 'DBShardGroupIdentifier', traits: {"smithy.api#documentation" => "<p>The name of the DB shard group.</p>"}))
    CreateDBShardGroupOutput.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The name of the primary DB cluster for the DB shard group.</p>"}))
    CreateDBShardGroupOutput.add_member(:max_acu, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MaxACU', traits: {"smithy.api#documentation" => "<p>The maximum capacity of the DB shard group in Aurora capacity units (ACUs).</p>"}))
    CreateDBShardGroupOutput.add_member(:min_acu, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MinACU', traits: {"smithy.api#documentation" => "<p>The minimum capacity of the DB shard group in Aurora capacity units (ACUs).</p>"}))
    CreateDBShardGroupOutput.add_member(:compute_redundancy, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ComputeRedundancy', traits: {"smithy.api#documentation" => "<p>Specifies whether to create standby DB shard groups for the DB shard group. Valid values are the following:</p>\n         <ul>\n            <li>\n               <p>0 - Creates a DB shard group without a standby DB shard group. This is the default value.</p>\n            </li>\n            <li>\n               <p>1 - Creates a DB shard group with a standby DB shard group in a different Availability Zone (AZ).</p>\n            </li>\n            <li>\n               <p>2 - Creates a DB shard group with two standby DB shard groups in two different AZs.</p>\n            </li>\n         </ul>"}))
    CreateDBShardGroupOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the DB shard group.</p>"}))
    CreateDBShardGroupOutput.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB shard group is publicly accessible.</p>\n         <p>When the DB shard group is publicly accessible, its Domain Name System (DNS) endpoint\n            resolves to the private IP address from within the DB shard group's virtual private cloud\n            (VPC). It resolves to the public IP address from outside of the DB shard group's VPC. Access\n            to the DB shard group is ultimately controlled by the security group it uses. That public\n            access isn't permitted if the security group assigned to the DB shard group doesn't permit\n            it.</p>\n         <p>When the DB shard group isn't publicly accessible, it is an internal DB shard group with a DNS name that resolves to a private IP address.</p>\n         <p>For more information, see <a>CreateDBShardGroup</a>.</p>\n         <p>This setting is only for Aurora Limitless Database.</p>"}))
    CreateDBShardGroupOutput.add_member(:endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Endpoint', traits: {"smithy.api#documentation" => "<p>The connection endpoint for the DB shard group.</p>"}))
    CreateDBShardGroupOutput.add_member(:db_shard_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBShardGroupArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the DB shard group.</p>"}))
    CreateDBShardGroupOutput.add_member(:tag_list, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'TagList'))
    CreateDBShardGroupOutput.type = Types::CreateDBShardGroupOutput
    CreateDBSnapshotMessage.add_member(:db_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSnapshotIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the DB snapshot.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be null, empty, or blank</p>\n            </li>\n            <li>\n               <p>Must contain from 1 to 255 letters, numbers, or hyphens</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-snapshot-id</code>\n         </p>", "smithy.api#required" => {}}))
    CreateDBSnapshotMessage.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier of the DB instance that you want to create the snapshot of.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing DBInstance.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateDBSnapshotMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    CreateDBSnapshotMessage.type = Types::CreateDBSnapshotMessage
