    CreateDBSubnetGroupMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name for the DB subnet group. This value is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain no more than 255 letters, numbers, periods, underscores, spaces, or hyphens.</p>\n            </li>\n            <li>\n               <p>Must not be default.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>", "smithy.api#required" => {}}))
    CreateDBSubnetGroupMessage.add_member(:db_subnet_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The description for the DB subnet group.</p>", "smithy.api#required" => {}}))
    CreateDBSubnetGroupMessage.add_member(:subnet_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetIdentifierList, location_name: 'SubnetIds', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The EC2 Subnet IDs for the DB subnet group.</p>", "smithy.api#required" => {}}))
