    CreateGlobalClusterMessage.add_member(:global_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'GlobalClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The cluster identifier for this global database cluster. This parameter is stored as a lowercase string.</p>"}))
    CreateGlobalClusterMessage.add_member(:source_db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) to use as the primary cluster of the global database.</p>\n         <p>If you provide a value for this parameter, don't specify values for the following settings because Amazon Aurora uses the values from the specified source DB cluster:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DatabaseName</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Engine</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>EngineVersion</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>StorageEncrypted</code>\n               </p>\n            </li>\n         </ul>"}))
    CreateGlobalClusterMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The database engine to use for this global database cluster.</p>\n         <p>Valid Values: <code>aurora-mysql | aurora-postgresql</code>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be specified if <code>SourceDBClusterIdentifier</code> is specified. In this case, Amazon Aurora uses the engine of the source DB cluster.</p>\n            </li>\n         </ul>"}))
    CreateGlobalClusterMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The engine version to use for this global database cluster.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be specified if <code>SourceDBClusterIdentifier</code> is specified. In this case, Amazon Aurora uses the engine version of the source DB cluster.</p>\n            </li>\n         </ul>"}))
    CreateGlobalClusterMessage.add_member(:engine_lifecycle_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineLifecycleSupport', traits: {"smithy.api#documentation" => "<p>The life cycle type for this global database cluster.</p>\n         <note>\n            <p>By default, this value is set to <code>open-source-rds-extended-support</code>, which enrolls your global cluster into Amazon RDS Extended Support. \n              At the end of standard support, you can avoid charges for Extended Support by setting the value to <code>open-source-rds-extended-support-disabled</code>. In this case, \n              creating the global cluster will fail if the DB major version is past its end of standard support date.</p>\n         </note>\n         <p>This setting only applies to Aurora PostgreSQL-based global databases.</p>\n         <p>You can use this setting to enroll your global cluster into Amazon RDS Extended Support. With RDS Extended Support, \n        you can run the selected major engine version on your global cluster past the end of standard support for that engine version. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon Aurora</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid Values: <code>open-source-rds-extended-support | open-source-rds-extended-support-disabled</code>\n         </p>\n         <p>Default: <code>open-source-rds-extended-support</code>\n         </p>"}))
    CreateGlobalClusterMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable deletion protection for the new global database cluster.\n        The global database can't be deleted when deletion protection is enabled.</p>"}))
    CreateGlobalClusterMessage.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The name for your database of up to 64 alphanumeric characters. If you don't specify\n            a name, Amazon Aurora doesn't create a database in the global database cluster.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be specified if <code>SourceDBClusterIdentifier</code> is specified. In this case, Amazon Aurora uses the database name from the source DB cluster.</p>\n            </li>\n         </ul>"}))
    CreateGlobalClusterMessage.add_member(:storage_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'StorageEncrypted', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable storage encryption for the new global database cluster.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be specified if <code>SourceDBClusterIdentifier</code> is specified. In this case, Amazon Aurora uses the setting from the source DB cluster.</p>\n            </li>\n         </ul>"}))
    CreateGlobalClusterMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Tags to assign to the global cluster.</p>"}))
