    CreateIntegrationOutput.add_member(:additional_encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionContextMap, location_name: 'AdditionalEncryptionContext', traits: {"smithy.api#documentation" => "<p>The encryption context for the integration. For more information, see <a href=\"https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#encrypt_context\">Encryption context</a> in the <i>Amazon Web Services Key Management Service Developer\n                Guide</i>.</p>"}))
