    CreateIntegrationOutput.add_member(:errors, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegrationErrorList, location_name: 'Errors', traits: {"smithy.api#documentation" => "<p>Any errors associated with the integration.</p>"}))
    CreateIntegrationOutput.add_member(:data_filter, Smithy::Schema::Shapes::ShapeRef.new(shape: DataFilter, location_name: 'DataFilter', traits: {"smithy.api#documentation" => "<p>Data filters for the integration. These filters determine which tables\n            from the source database are sent to the target Amazon Redshift data warehouse. \n        </p>"}))
