    CreateOptionGroupMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the name of the option group to be created.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 255 letters, numbers, or hyphens</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>\n         <p>Example: <code>myoptiongroup</code>\n         </p>", "smithy.api#required" => {}}))
    CreateOptionGroupMessage.add_member(:engine_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the engine to associate this option group with.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db2-ae</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>db2-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mariadb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>postgres</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ex</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-web</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateOptionGroupMessage.add_member(:major_engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MajorEngineVersion', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the major version of the engine that this option group should be associated with.</p>", "smithy.api#required" => {}}))
    CreateOptionGroupMessage.add_member(:option_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The description of the option group.</p>", "smithy.api#required" => {}}))
