    CreateTenantDatabaseMessage.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The user-supplied DB instance identifier. RDS creates your tenant database in this DB\n            instance. This parameter isn't case-sensitive.</p>", "smithy.api#required" => {}}))
    CreateTenantDatabaseMessage.add_member(:tenant_db_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TenantDBName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The user-supplied name of the tenant database that you want to create in your DB\n            instance. This parameter has the same constraints as <code>DBName</code> in\n                <code>CreateDBInstance</code>.</p>", "smithy.api#required" => {}}))
    CreateTenantDatabaseMessage.add_member(:master_username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUsername', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name for the master user account in your tenant database. RDS creates this user\n            account in the tenant database and grants privileges to the master user. This parameter\n            is case-sensitive.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 16 letters, numbers, or underscores.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't be a reserved word for the chosen database engine.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CreateTenantDatabaseMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: SensitiveString, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>The password for the master user in your tenant database.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 8 to 30 characters.</p>\n            </li>\n            <li>\n               <p>Can include any printable ASCII character except forward slash\n                    (<code>/</code>), double quote (<code>\"</code>), at symbol (<code>@</code>),\n                    ampersand (<code>&</code>), or single quote (<code>'</code>).</p>\n            </li>\n            <li>\n               <p>Can't be specified when <code>ManageMasterUserPassword</code> is\n                    enabled.</p>\n            </li>\n         </ul>"}))
    CreateTenantDatabaseMessage.add_member(:character_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CharacterSetName', traits: {"smithy.api#documentation" => "<p>The character set for your tenant database. If you don't specify a value, the\n            character set name defaults to <code>AL32UTF8</code>.</p>"}))
    CreateTenantDatabaseMessage.add_member(:nchar_character_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NcharCharacterSetName', traits: {"smithy.api#documentation" => "<p>The <code>NCHAR</code> value for the tenant database.</p>"}))
    CreateTenantDatabaseMessage.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't manage the master user password with Amazon Web Services Secrets Manager if <code>MasterUserPassword</code> \n                    is specified.</p>\n            </li>\n         </ul>"}))
    CreateTenantDatabaseMessage.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and \n            managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets \n            Manager for the DB instance.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>If you don't specify <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> \n            KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't \n            use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer \n            managed KMS key.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>"}))
    CreateTenantDatabaseMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    CreateTenantDatabaseMessage.type = Types::CreateTenantDatabaseMessage
