    CustomEngineVersionStatus.add_member(:inactive_except_restore, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'inactive_except_restore', traits: {"smithy.api#enumValue" => "inactive-except-restore"}))
    DBCluster.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>\n            <code>AllocatedStorage</code> specifies the allocated storage size in gibibytes (GiB). \n          For Aurora, <code>AllocatedStorage</code> can vary because Aurora DB cluster storage size adjusts as needed.</p>"}))
    DBCluster.add_member(:availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZones, location_name: 'AvailabilityZones', traits: {"smithy.api#documentation" => "<p>The list of Availability Zones (AZs) where instances in the DB cluster can be created.</p>"}))
    DBCluster.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days for which automatic DB snapshots are retained.</p>"}))
    DBCluster.add_member(:character_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CharacterSetName', traits: {"smithy.api#documentation" => "<p>If present, specifies the name of the character set that this cluster is associated with.</p>"}))
    DBCluster.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The name of the initial database that was specified for the DB cluster when it was created, if one was provided. This same name is returned for the life of the DB cluster.</p>"}))
    DBCluster.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The user-supplied identifier for the DB cluster. This identifier is the unique key that identifies a DB cluster.</p>"}))
    DBCluster.add_member(:db_cluster_parameter_group, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroup', traits: {"smithy.api#documentation" => "<p>The name of the DB cluster parameter group for the DB cluster.</p>"}))
    DBCluster.add_member(:db_subnet_group, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroup', traits: {"smithy.api#documentation" => "<p>Information about the subnet group associated with the DB cluster, including the name, description, and subnets in the subnet group.</p>"}))
    DBCluster.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The current state of this DB cluster.</p>"}))
    DBCluster.add_member(:automatic_restart_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'AutomaticRestartTime', traits: {"smithy.api#documentation" => "<p>The time when a stopped DB cluster is restarted automatically.</p>"}))
    DBCluster.add_member(:percent_progress, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PercentProgress', traits: {"smithy.api#documentation" => "<p>The progress of the operation as a percentage.</p>"}))
    DBCluster.add_member(:earliest_restorable_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'EarliestRestorableTime', traits: {"smithy.api#documentation" => "<p>The earliest time to which a database can be restored with point-in-time\n            restore.</p>"}))
    DBCluster.add_member(:endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Endpoint', traits: {"smithy.api#documentation" => "<p>The connection endpoint for the primary instance of the DB cluster.</p>"}))
    DBCluster.add_member(:reader_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReaderEndpoint', traits: {"smithy.api#documentation" => "<p>The reader endpoint for the DB cluster. The reader endpoint for a DB cluster load-balances \n            connections across the Aurora Replicas that are available in a DB cluster. As clients request new connections \n            to the reader endpoint, Aurora distributes the connection requests among the Aurora Replicas in the DB cluster. \n            This functionality can help balance your read workload across multiple Aurora Replicas in your DB cluster.</p>\n         <p>If a failover occurs, and the Aurora Replica that you are connected to is promoted \n            to be the primary instance, your connection is dropped. To \n            continue sending your read workload to other Aurora Replicas in the cluster,\n            you can then reconnect to the reader endpoint.</p>"}))
    DBCluster.add_member(:custom_endpoints, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'CustomEndpoints', traits: {"smithy.api#documentation" => "<p>The custom endpoints associated with the DB cluster.</p>"}))
    DBCluster.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB cluster has instances in multiple Availability Zones.</p>"}))
    DBCluster.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The database engine used for this DB cluster.</p>"}))
    DBCluster.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version of the database engine.</p>"}))
    DBCluster.add_member(:latest_restorable_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'LatestRestorableTime', traits: {"smithy.api#documentation" => "<p>The latest time to which a database can be restored with point-in-time restore.</p>"}))
    DBCluster.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port that the database engine is listening on.</p>"}))
    DBCluster.add_member(:master_username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUsername', traits: {"smithy.api#documentation" => "<p>The master username for the DB cluster.</p>"}))
    DBCluster.add_member(:db_cluster_option_group_memberships, Smithy::Schema::Shapes::ShapeRef.new(shape: DBClusterOptionGroupMemberships, location_name: 'DBClusterOptionGroupMemberships', traits: {"smithy.api#documentation" => "<p>The list of option group memberships for this DB cluster.</p>"}))
    DBCluster.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are\n            created if automated backups are enabled, as determined\n            by the <code>BackupRetentionPeriod</code>.</p>"}))
    DBCluster.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur, in Universal Coordinated Time (UTC).</p>"}))
    DBCluster.add_member(:replication_source_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReplicationSourceIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of the source DB cluster if this DB cluster is a read\n            replica.</p>"}))
    DBCluster.add_member(:read_replica_identifiers, Smithy::Schema::Shapes::ShapeRef.new(shape: ReadReplicaIdentifierList, location_name: 'ReadReplicaIdentifiers', traits: {"smithy.api#documentation" => "<p>Contains one or more identifiers of the read replicas associated with this DB\n            cluster.</p>"}))
    DBCluster.add_member(:status_infos, Smithy::Schema::Shapes::ShapeRef.new(shape: DBClusterStatusInfoList, location_name: 'StatusInfos', traits: {"smithy.api#documentation" => "<p>Reserved for future use.</p>"}))
    DBCluster.add_member(:db_cluster_members, Smithy::Schema::Shapes::ShapeRef.new(shape: DBClusterMemberList, location_name: 'DBClusterMembers', traits: {"smithy.api#documentation" => "<p>The list of DB instances that make up the DB cluster.</p>"}))
    DBCluster.add_member(:vpc_security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupMembershipList, location_name: 'VpcSecurityGroups', traits: {"smithy.api#documentation" => "<p>The list of VPC security groups that the DB cluster belongs to.</p>"}))
    DBCluster.add_member(:hosted_zone_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'HostedZoneId', traits: {"smithy.api#documentation" => "<p>The ID that Amazon Route 53 assigns when you create a hosted zone.</p>"}))
    DBCluster.add_member(:storage_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'StorageEncrypted', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB cluster is encrypted.</p>"}))
    DBCluster.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>If <code>StorageEncrypted</code> is enabled, the Amazon Web Services KMS key identifier for the encrypted DB cluster.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>"}))
    DBCluster.add_member(:db_cluster_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DbClusterResourceId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Region-unique, immutable identifier for the DB cluster. This identifier is found in Amazon Web Services CloudTrail log entries whenever \n          the KMS key for the DB cluster is accessed.</p>"}))
    DBCluster.add_member(:db_cluster_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the DB cluster.</p>"}))
    DBCluster.add_member(:associated_roles, Smithy::Schema::Shapes::ShapeRef.new(shape: DBClusterRoles, location_name: 'AssociatedRoles', traits: {"smithy.api#documentation" => "<p>A list of the Amazon Web Services Identity and Access Management (IAM) roles that are associated with the DB cluster. \n          IAM roles that are associated with a DB cluster grant permission for the DB cluster to access other Amazon Web Services\n          on your behalf.</p>"}))
    DBCluster.add_member(:iam_database_authentication_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'IAMDatabaseAuthenticationEnabled', traits: {"smithy.api#documentation" => "<p>Indicates whether the mapping of Amazon Web Services Identity and Access Management (IAM) accounts to database accounts is enabled.</p>"}))
    DBCluster.add_member(:clone_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CloneGroupId', traits: {"smithy.api#documentation" => "<p>The ID of the clone group with which the DB cluster is associated. For newly created\n            clusters, the ID is typically null. </p>\n         <p>If you clone a DB cluster when the ID is null, the operation populates the ID value\n            for the source cluster and the clone because both clusters become part of the same clone\n            group. Even if you delete the clone cluster, the clone group ID remains for the lifetime\n            of the source cluster to show that it was used in a cloning operation.</p>\n         <p>For PITR, the clone group ID is inherited from the source cluster. For snapshot\n            restore operations, the clone group ID isn't inherited from the source cluster.</p>"}))
    DBCluster.add_member(:cluster_create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'ClusterCreateTime', traits: {"smithy.api#documentation" => "<p>The time when the DB cluster was created, in Universal Coordinated Time (UTC).</p>"}))
    DBCluster.add_member(:earliest_backtrack_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'EarliestBacktrackTime', traits: {"smithy.api#documentation" => "<p>The earliest time to which a DB cluster can be backtracked.</p>"}))
    DBCluster.add_member(:backtrack_window, Smithy::Schema::Shapes::ShapeRef.new(shape: LongOptional, location_name: 'BacktrackWindow', traits: {"smithy.api#documentation" => "<p>The target backtrack window, in seconds. If this value is set to <code>0</code>, backtracking is\n            disabled for the DB cluster. Otherwise, backtracking is enabled.</p>"}))
    DBCluster.add_member(:backtrack_consumed_change_records, Smithy::Schema::Shapes::ShapeRef.new(shape: LongOptional, location_name: 'BacktrackConsumedChangeRecords', traits: {"smithy.api#documentation" => "<p>The number of change records stored for Backtrack.</p>"}))
    DBCluster.add_member(:enabled_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnabledCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>A list of log types that this DB cluster is configured to export to CloudWatch Logs.</p>\n         <p>Log types vary by DB engine. For information about the log types for each DB engine, see\n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_LogAccess.html\">Amazon RDS Database Log Files</a> in the <i>Amazon Aurora User Guide.</i>\n         </p>"}))
    DBCluster.add_member(:capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Capacity', traits: {"smithy.api#documentation" => "<p>The current capacity of an Aurora Serverless v1 DB cluster. The capacity is <code>0</code> (zero) \n          when the cluster is paused.</p>\n         <p>For more information about Aurora Serverless v1, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-serverless.html\">Using Amazon Aurora Serverless v1</a> in the \n          <i>Amazon Aurora User Guide</i>.</p>"}))
    DBCluster.add_member(:engine_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineMode', traits: {"smithy.api#documentation" => "<p>The DB engine mode of the DB cluster, either <code>provisioned</code> or <code>serverless</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_CreateDBCluster.html\">\n            CreateDBCluster</a>.</p>"}))
    DBCluster.add_member(:scaling_configuration_info, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingConfigurationInfo, location_name: 'ScalingConfigurationInfo'))
    DBCluster.add_member(:rds_custom_cluster_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RdsCustomClusterConfiguration, location_name: 'RdsCustomClusterConfiguration', traits: {"smithy.api#documentation" => "<p>Reserved for future use.</p>"}))
    DBCluster.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB cluster has deletion protection enabled.\n            The database can't be deleted when deletion protection is enabled.</p>"}))
    DBCluster.add_member(:http_endpoint_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'HttpEndpointEnabled', traits: {"smithy.api#documentation" => "<p>Indicates whether the HTTP endpoint is enabled for an Aurora DB cluster.</p>\n         <p>When enabled, the HTTP endpoint provides a connectionless web service API (RDS Data API) for running\n          SQL queries on the DB cluster. You can also query your database\n          from inside the RDS console with the RDS query editor.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/data-api.html\">Using RDS Data API</a> in the \n          <i>Amazon Aurora User Guide</i>.</p>"}))
    DBCluster.add_member(:activity_stream_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ActivityStreamMode, location_name: 'ActivityStreamMode', traits: {"smithy.api#documentation" => "<p>The mode of the database activity stream.\n           Database events such as a change or access generate an activity stream event.\n           The database session can handle these events either synchronously or asynchronously.</p>"}))
    DBCluster.add_member(:activity_stream_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ActivityStreamStatus, location_name: 'ActivityStreamStatus', traits: {"smithy.api#documentation" => "<p>The status of the database activity stream.</p>"}))
    DBCluster.add_member(:activity_stream_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ActivityStreamKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier used for encrypting messages in the database activity stream.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>"}))
    DBCluster.add_member(:activity_stream_kinesis_stream_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ActivityStreamKinesisStreamName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon Kinesis data stream used for the database activity stream.</p>"}))
    DBCluster.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Indicates whether tags are copied from the DB cluster to snapshots of the DB cluster.</p>"}))
    DBCluster.add_member(:cross_account_clone, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CrossAccountClone', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB cluster is a clone of a DB cluster owned by a different Amazon Web Services account.</p>"}))
    DBCluster.add_member(:domain_memberships, Smithy::Schema::Shapes::ShapeRef.new(shape: DomainMembershipList, location_name: 'DomainMemberships', traits: {"smithy.api#documentation" => "<p>The Active Directory Domain membership records associated with the DB cluster.</p>"}))
    DBCluster.add_member(:tag_list, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'TagList'))
    DBCluster.add_member(:global_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: GlobalClusterIdentifier, location_name: 'GlobalClusterIdentifier', traits: {"smithy.api#documentation" => "<p>Contains a user-supplied global database cluster identifier. This identifier is the unique key that\n        identifies a global database cluster.</p>"}))
    DBCluster.add_member(:global_write_forwarding_status, Smithy::Schema::Shapes::ShapeRef.new(shape: WriteForwardingStatus, location_name: 'GlobalWriteForwardingStatus', traits: {"smithy.api#documentation" => "<p>The status of write forwarding for a secondary cluster in an Aurora global database.</p>"}))
    DBCluster.add_member(:global_write_forwarding_requested, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'GlobalWriteForwardingRequested', traits: {"smithy.api#documentation" => "<p>Indicates whether write forwarding is enabled for a secondary cluster\n      in an Aurora global database. Because write forwarding takes time to enable, check the\n      value of <code>GlobalWriteForwardingStatus</code> to confirm that the request has completed\n      before using the write forwarding feature for this cluster.</p>"}))
    DBCluster.add_member(:pending_modified_values, Smithy::Schema::Shapes::ShapeRef.new(shape: ClusterPendingModifiedValues, location_name: 'PendingModifiedValues', traits: {"smithy.api#documentation" => "<p>Information about pending changes to the DB cluster. This information is returned only when there are pending changes. Specific changes are identified by subelements.</p>"}))
    DBCluster.add_member(:db_cluster_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterInstanceClass', traits: {"smithy.api#documentation" => "<p>The name of the compute and memory capacity class of the DB instance.</p>\n         <p>This setting is only for non-Aurora Multi-AZ DB clusters.</p>"}))
    DBCluster.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type associated with the DB cluster.</p>"}))
    DBCluster.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The Provisioned IOPS (I/O operations per second) value.</p>\n         <p>This setting is only for non-Aurora Multi-AZ DB clusters.</p>"}))
    DBCluster.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB cluster is publicly accessible.</p>\n         <p>When the DB cluster is publicly accessible and you connect from outside of the DB cluster's virtual private cloud (VPC), \n              its Domain Name System (DNS) endpoint resolves to the public IP address. When you connect from within the same VPC as the DB cluster, \n              the endpoint resolves to the private IP address. Access to the DB cluster is ultimately controlled by the security group it uses. That public\n              access isn't permitted if the security group assigned to the DB cluster doesn't permit it.</p>\n         <p>When the DB cluster isn't publicly accessible, it is an internal DB cluster with a DNS name that resolves to a private IP address.</p>\n         <p>For more information, see <a>CreateDBCluster</a>.</p>\n         <p>This setting is only for non-Aurora Multi-AZ DB clusters.</p>"}))
    DBCluster.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Indicates whether minor version patches are applied automatically.</p>\n         <p>This setting is for Aurora DB clusters and Multi-AZ DB clusters.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    DBCluster.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are collected for the DB cluster.</p>\n         <p>This setting is only for -Aurora DB clusters and Multi-AZ DB clusters.</p>"}))
    DBCluster.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN for the IAM role that permits RDS to send Enhanced Monitoring metrics to Amazon CloudWatch Logs.</p>\n         <p>This setting is only for Aurora DB clusters and Multi-AZ DB clusters.</p>"}))
    DBCluster.add_member(:database_insights_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseInsightsMode, location_name: 'DatabaseInsightsMode', traits: {"smithy.api#documentation" => "<p>The mode of Database Insights that is enabled for the DB cluster.</p>"}))
    DBCluster.add_member(:performance_insights_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PerformanceInsightsEnabled', traits: {"smithy.api#documentation" => "<p>Indicates whether Performance Insights is enabled for the DB cluster.</p>\n         <p>This setting is only for Aurora DB clusters and Multi-AZ DB clusters.</p>"}))
    DBCluster.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>This setting is only for Aurora DB clusters and Multi-AZ DB clusters.</p>"}))
