    DBEngineVersion.add_member(:supports_local_write_forwarding, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'SupportsLocalWriteForwarding', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports forwarding write operations from reader DB instances \n            to the writer DB instance in the DB cluster. By default, write operations aren't allowed on reader DB instances.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    DBEngineVersion.add_member(:supports_integrations, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsIntegrations', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports zero-ETL integrations with\n            Amazon Redshift.</p>"}))
    DBEngineVersion.add_member(:serverless_v2_features_support, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2FeaturesSupport, location_name: 'ServerlessV2FeaturesSupport', traits: {"smithy.api#documentation" => "<p>Specifies any Aurora Serverless v2 properties or limits that differ between Aurora engine versions.\n        You can test the values of this attribute when deciding which Aurora version to use in a new or upgraded\n        DB cluster. You can also retrieve the version of an existing DB cluster and check whether that version\n        supports certain Aurora Serverless v2 features before you attempt to use those features.\n      </p>"}))
    DBEngineVersion.type = Types::DBEngineVersion
    DBEngineVersionList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: DBEngineVersion, traits: {"smithy.api#xmlName" => "DBEngineVersion"})
    DBEngineVersionMessage.add_member(:marker, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Marker', traits: {"smithy.api#documentation" => "<p>An optional pagination token provided by a previous request.\n            If this parameter is specified, the response includes\n            only records beyond the marker,\n            up to the value specified by <code>MaxRecords</code>.</p>"}))
    DBEngineVersionMessage.add_member(:db_engine_versions, Smithy::Schema::Shapes::ShapeRef.new(shape: DBEngineVersionList, location_name: 'DBEngineVersions', traits: {"smithy.api#documentation" => "<p>A list of <code>DBEngineVersion</code> elements.</p>"}))
    DBEngineVersionMessage.type = Types::DBEngineVersionMessage
    DBInstance.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#documentation" => "<p>The user-supplied database identifier. This identifier is the unique key that identifies a DB instance.</p>"}))
    DBInstance.add_member(:db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceClass', traits: {"smithy.api#documentation" => "<p>The name of the compute and memory capacity class of the DB instance.</p>"}))
    DBInstance.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The database engine used for this DB instance.</p>"}))
    DBInstance.add_member(:db_instance_status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceStatus', traits: {"smithy.api#documentation" => "<p>The current state of this database.</p>\n         <p>For information about DB instance statuses, see\n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/accessing-monitoring.html#Overview.DBInstance.Status\">Viewing DB instance status</a> \n          in the <i>Amazon RDS User Guide.</i>\n         </p>"}))
    DBInstance.add_member(:automatic_restart_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'AutomaticRestartTime', traits: {"smithy.api#documentation" => "<p>The time when a stopped DB instance is restarted automatically.</p>"}))
    DBInstance.add_member(:master_username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUsername', traits: {"smithy.api#documentation" => "<p>The master username for the DB instance.</p>"}))
    DBInstance.add_member(:db_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBName', traits: {"smithy.api#documentation" => "<p>The initial database name that you provided (if required) when you created\n            the DB instance. This name is returned for the life of your DB instance. For an RDS for\n            Oracle CDB instance, the name identifies the PDB rather than the CDB.</p>"}))
    DBInstance.add_member(:endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: Endpoint, location_name: 'Endpoint', traits: {"smithy.api#documentation" => "<p>The connection endpoint for the DB instance.</p>\n         <note>\n            <p>The endpoint might not be shown for instances with the status of <code>creating</code>.</p>\n         </note>"}))
    DBInstance.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The amount of storage in gibibytes (GiB) allocated for the DB instance.</p>"}))
    DBInstance.add_member(:instance_create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'InstanceCreateTime', traits: {"smithy.api#documentation" => "<p>The date and time when the DB instance was created.</p>"}))
    DBInstance.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are\n        created if automated backups are enabled, as determined\n        by the <code>BackupRetentionPeriod</code>.</p>"}))
    DBInstance.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days for which automatic DB snapshots are retained.</p>"}))
    DBInstance.add_member(:db_security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: DBSecurityGroupMembershipList, location_name: 'DBSecurityGroups', traits: {"smithy.api#documentation" => "<p>A list of DB security group elements containing \n        <code>DBSecurityGroup.Name</code> and <code>DBSecurityGroup.Status</code> subelements.</p>"}))
    DBInstance.add_member(:vpc_security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupMembershipList, location_name: 'VpcSecurityGroups', traits: {"smithy.api#documentation" => "<p>The list of Amazon EC2 VPC security groups that the DB instance belongs to.</p>"}))
    DBInstance.add_member(:db_parameter_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: DBParameterGroupStatusList, location_name: 'DBParameterGroups', traits: {"smithy.api#documentation" => "<p>The list of DB parameter groups applied to this DB instance.</p>"}))
    DBInstance.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZone', traits: {"smithy.api#documentation" => "<p>The name of the Availability Zone where the DB instance is located.</p>"}))
    DBInstance.add_member(:db_subnet_group, Smithy::Schema::Shapes::ShapeRef.new(shape: DBSubnetGroup, location_name: 'DBSubnetGroup', traits: {"smithy.api#documentation" => "<p>Information about the subnet group associated with the DB instance, including the name, description, and subnets in the subnet group.</p>"}))
    DBInstance.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur, in Universal Coordinated Time (UTC).</p>"}))
    DBInstance.add_member(:pending_modified_values, Smithy::Schema::Shapes::ShapeRef.new(shape: PendingModifiedValues, location_name: 'PendingModifiedValues', traits: {"smithy.api#documentation" => "<p>Information about pending changes to the DB instance. This information is returned only when there are pending changes. Specific changes are identified by subelements.</p>"}))
    DBInstance.add_member(:latest_restorable_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'LatestRestorableTime', traits: {"smithy.api#documentation" => "<p>The latest time to which a database in this DB instance can be restored with point-in-time restore.</p>"}))
    DBInstance.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB instance is a Multi-AZ deployment. This setting doesn't apply to RDS Custom DB instances.</p>"}))
    DBInstance.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version of the database engine.</p>"}))
    DBInstance.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Indicates whether minor version patches are applied automatically.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    DBInstance.add_member(:read_replica_source_db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ReadReplicaSourceDBInstanceIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of the source DB instance if this DB instance is a read\n            replica.</p>"}))
    DBInstance.add_member(:read_replica_db_instance_identifiers, Smithy::Schema::Shapes::ShapeRef.new(shape: ReadReplicaDBInstanceIdentifierList, location_name: 'ReadReplicaDBInstanceIdentifiers', traits: {"smithy.api#documentation" => "<p>The identifiers of the read replicas associated with this DB\n            instance.</p>"}))
    DBInstance.add_member(:read_replica_db_cluster_identifiers, Smithy::Schema::Shapes::ShapeRef.new(shape: ReadReplicaDBClusterIdentifierList, location_name: 'ReadReplicaDBClusterIdentifiers', traits: {"smithy.api#documentation" => "<p>The identifiers of Aurora DB clusters to which the RDS DB instance\n            is replicated as a read replica. For example, when you create an Aurora read replica of\n            an RDS for MySQL DB instance, the Aurora MySQL DB cluster for the Aurora read replica is\n            shown. This output doesn't contain information about cross-Region Aurora read\n            replicas.</p>\n         <note>\n            <p>Currently, each RDS DB instance can have only one Aurora read replica.</p>\n         </note>"}))
    DBInstance.add_member(:replica_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ReplicaMode, location_name: 'ReplicaMode', traits: {"smithy.api#documentation" => "<p>The open mode of a Db2 or an Oracle read replica. The default is\n                <code>open-read-only</code>. For more information, see  <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/db2-replication.html\">Working with read replicas for\n                Amazon RDS for Db2</a>  and <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/oracle-read-replicas.html\">Working with read replicas\n                for Amazon RDS for Oracle</a> in the <i>Amazon RDS User Guide</i>. </p>\n         <note>\n            <p>This attribute is only supported in RDS for Db2, RDS for Oracle, and RDS Custom\n                for Oracle.</p>\n         </note>"}))
    DBInstance.add_member(:license_model, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LicenseModel', traits: {"smithy.api#documentation" => "<p>The license model information for this DB instance. This setting doesn't apply to\n            Amazon Aurora or RDS Custom DB instances.</p>"}))
    DBInstance.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The Provisioned IOPS (I/O operations per second) value for the DB instance.</p>"}))
    DBInstance.add_member(:option_group_memberships, Smithy::Schema::Shapes::ShapeRef.new(shape: OptionGroupMembershipList, location_name: 'OptionGroupMemberships', traits: {"smithy.api#documentation" => "<p>The list of option group memberships for this DB instance.</p>"}))
    DBInstance.add_member(:character_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CharacterSetName', traits: {"smithy.api#documentation" => "<p>If present, specifies the name of the character set that this instance is associated with.</p>"}))
    DBInstance.add_member(:nchar_character_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NcharCharacterSetName', traits: {"smithy.api#documentation" => "<p>The name of the NCHAR character set for the Oracle DB instance. This character set specifies the\n            Unicode encoding for data stored in table columns of type NCHAR, NCLOB, or NVARCHAR2.</p>"}))
    DBInstance.add_member(:secondary_availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SecondaryAvailabilityZone', traits: {"smithy.api#documentation" => "<p>If present, specifies the name of the secondary Availability Zone for a DB instance with multi-AZ support.</p>"}))
    DBInstance.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB instance is publicly accessible.</p>\n         <p>When the DB instance is publicly accessible and you connect from outside of the DB instance's virtual private cloud (VPC), \n              its Domain Name System (DNS) endpoint resolves to the public IP address. When you connect from within the same VPC as the DB instance, \n              the endpoint resolves to the private IP address. Access to the DB cluster is ultimately controlled by the security group it uses. That public\n              access isn't permitted if the security group assigned to the DB cluster doesn't permit it.</p>\n         <p>When the DB instance isn't publicly accessible, it is an internal DB instance with a DNS name that resolves to a private IP address.</p>\n         <p>For more information, see <a>CreateDBInstance</a>.</p>"}))
    DBInstance.add_member(:status_infos, Smithy::Schema::Shapes::ShapeRef.new(shape: DBInstanceStatusInfoList, location_name: 'StatusInfos', traits: {"smithy.api#documentation" => "<p>The status of a read replica. If the DB instance isn't a read replica, the value is\n            blank.</p>"}))
    DBInstance.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type associated with the DB instance.</p>"}))
    DBInstance.add_member(:tde_credential_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialArn', traits: {"smithy.api#documentation" => "<p>The ARN from the key store with which the instance is associated for TDE encryption.</p>"}))
    DBInstance.add_member(:db_instance_port, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'DbInstancePort', traits: {"smithy.api#documentation" => "<p>The port that the DB instance listens on. If the DB instance is part of a DB cluster, this can be a different port than the DB cluster port.</p>"}))
    DBInstance.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>If the DB instance is a member of a DB cluster, indicates the name of the DB cluster that the DB instance is a member of.</p>"}))
    DBInstance.add_member(:storage_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'StorageEncrypted', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB instance is encrypted.</p>"}))
    DBInstance.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>If <code>StorageEncrypted</code> is enabled, the Amazon Web Services KMS key identifier \n            for the encrypted DB instance.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>"}))
    DBInstance.add_member(:dbi_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DbiResourceId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Region-unique, immutable identifier for the DB instance. This identifier is found in Amazon Web Services CloudTrail log \n          entries whenever the Amazon Web Services KMS key for the DB instance is accessed.</p>"}))
    DBInstance.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of the CA certificate for this DB instance.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n            instance</a> in the <i>Amazon RDS User Guide</i> and \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL.html\">\n            Using SSL/TLS to encrypt a connection to a DB cluster</a> in the <i>Amazon Aurora \n            User Guide</i>.</p>"}))
    DBInstance.add_member(:domain_memberships, Smithy::Schema::Shapes::ShapeRef.new(shape: DomainMembershipList, location_name: 'DomainMemberships', traits: {"smithy.api#documentation" => "<p>The Active Directory Domain membership records associated with the DB instance.</p>"}))
    DBInstance.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Indicates whether tags are copied from the DB instance to snapshots of the DB instance.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. Copying tags to snapshots is managed by the DB cluster. Setting this\n            value for an Aurora DB instance has no effect on the DB cluster setting. For more\n            information, see <code>DBCluster</code>.</p>"}))
    DBInstance.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are collected for the DB instance.</p>"}))
    DBInstance.add_member(:enhanced_monitoring_resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EnhancedMonitoringResourceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon CloudWatch Logs log stream that receives the Enhanced Monitoring metrics data for the DB instance.</p>"}))
    DBInstance.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN for the IAM role that permits RDS to send Enhanced Monitoring metrics to Amazon CloudWatch Logs.</p>"}))
    DBInstance.add_member(:promotion_tier, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PromotionTier', traits: {"smithy.api#documentation" => "<p>The order of priority in which an Aurora Replica is promoted to the primary instance \n          after a failure of the existing primary instance. For more information, \n      see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Concepts.AuroraHighAvailability.html#Aurora.Managing.FaultTolerance\">\n          Fault Tolerance for an Aurora DB Cluster</a> in the <i>Amazon Aurora User Guide</i>.</p>"}))
    DBInstance.add_member(:db_instance_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the DB instance.</p>"}))
    DBInstance.add_member(:timezone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Timezone', traits: {"smithy.api#documentation" => "<p>The time zone of the DB instance.\n            In most cases, the <code>Timezone</code> element is empty.\n            <code>Timezone</code> content appears only for\n            RDS for Db2 and RDS for SQL Server DB instances \n            that were created with a time zone specified.</p>"}))
    DBInstance.add_member(:iam_database_authentication_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IAMDatabaseAuthenticationEnabled', traits: {"smithy.api#documentation" => "<p>Indicates whether mapping of Amazon Web Services Identity and Access Management (IAM) accounts to database accounts is enabled for the DB instance.</p>\n         <p>For a list of engine versions that support IAM database authentication, see \n              <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.RDS_Fea_Regions_DB-eng.Feature.IamDatabaseAuthentication.html\">IAM database authentication</a>\n              in the <i>Amazon RDS User Guide</i> and <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Concepts.Aurora_Fea_Regions_DB-eng.Feature.IAMdbauth.html\">IAM \n              database authentication in Aurora</a> in the <i>Amazon Aurora User Guide</i>.</p>"}))
    DBInstance.add_member(:database_insights_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseInsightsMode, location_name: 'DatabaseInsightsMode', traits: {"smithy.api#documentation" => "<p>The mode of Database Insights that is enabled for the instance.</p>"}))
    DBInstance.add_member(:performance_insights_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PerformanceInsightsEnabled', traits: {"smithy.api#documentation" => "<p>Indicates whether Performance Insights is enabled for the DB instance.</p>"}))
    DBInstance.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>"}))
    DBInstance.add_member(:performance_insights_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PerformanceInsightsRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain Performance Insights data.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>7</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <i>month</i> * 31, where <i>month</i> is a number of months from 1-23. \n                Examples: <code>93</code> (3 months * 31), <code>341</code> (11 months * 31), <code>589</code> (19 months * 31)</p>\n            </li>\n            <li>\n               <p>\n                  <code>731</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: <code>7</code> days</p>"}))
    DBInstance.add_member(:enabled_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnabledCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>A list of log types that this DB instance is configured to export to CloudWatch Logs.</p>\n         <p>Log types vary by DB engine. For information about the log types for each DB engine, see\n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html\">Monitoring Amazon RDS log files</a> in the <i>Amazon RDS User Guide.</i>\n         </p>"}))
    DBInstance.add_member(:processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessorFeatureList, location_name: 'ProcessorFeatures', traits: {"smithy.api#documentation" => "<p>The number of CPU cores and the number of threads per core for the DB instance class of the DB instance.</p>"}))
    DBInstance.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB instance has deletion protection enabled.\n            The database can't be deleted when deletion protection is enabled.\n            For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_DeleteInstance.html\">\n                Deleting a DB Instance</a>.</p>"}))
    DBInstance.add_member(:associated_roles, Smithy::Schema::Shapes::ShapeRef.new(shape: DBInstanceRoles, location_name: 'AssociatedRoles', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Identity and Access Management (IAM) roles associated with the DB instance.</p>"}))
    DBInstance.add_member(:listener_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: Endpoint, location_name: 'ListenerEndpoint', traits: {"smithy.api#documentation" => "<p>The listener connection endpoint for SQL Server Always On.</p>"}))
    DBInstance.add_member(:max_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxAllocatedStorage', traits: {"smithy.api#documentation" => "<p>The upper limit in gibibytes (GiB) to which Amazon RDS can automatically scale the storage of the DB instance.</p>"}))
    DBInstance.add_member(:tag_list, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'TagList'))
    DBInstance.add_member(:db_instance_automated_backups_replications, Smithy::Schema::Shapes::ShapeRef.new(shape: DBInstanceAutomatedBackupsReplicationList, location_name: 'DBInstanceAutomatedBackupsReplications', traits: {"smithy.api#documentation" => "<p>The list of replicated automated backups associated with the DB instance.</p>"}))
    DBInstance.add_member(:customer_owned_ip_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CustomerOwnedIpEnabled', traits: {"smithy.api#documentation" => "<p>Indicates whether a customer-owned IP address (CoIP) is enabled for an RDS on Outposts DB instance.</p>\n         <p>A <i>CoIP </i>provides local or external connectivity to resources in\n            your Outpost subnets through your on-premises network. For some use cases, a CoIP can\n            provide lower latency for connections to the DB instance from outside of its virtual\n            private cloud (VPC) on your local network.</p>\n         <p>For more information about RDS on Outposts, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-on-outposts.html\">Working with Amazon RDS on Amazon Web Services Outposts</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about CoIPs, see <a href=\"https://docs.aws.amazon.com/outposts/latest/userguide/routing.html#ip-addressing\">Customer-owned IP addresses</a> \n            in the <i>Amazon Web Services Outposts User Guide</i>.</p>"}))
    DBInstance.add_member(:aws_backup_recovery_point_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AwsBackupRecoveryPointArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the recovery point in Amazon Web Services Backup.</p>"}))
    DBInstance.add_member(:activity_stream_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ActivityStreamStatus, location_name: 'ActivityStreamStatus', traits: {"smithy.api#documentation" => "<p>The status of the database activity stream.</p>"}))
    DBInstance.add_member(:activity_stream_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ActivityStreamKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier used for encrypting messages in the database activity stream. \n            The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>"}))
    DBInstance.add_member(:activity_stream_kinesis_stream_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ActivityStreamKinesisStreamName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon Kinesis data stream used for the database activity stream.</p>"}))
    DBInstance.add_member(:activity_stream_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ActivityStreamMode, location_name: 'ActivityStreamMode', traits: {"smithy.api#documentation" => "<p>The mode of the database activity stream. Database events such as a change or access generate \n            an activity stream event. RDS for Oracle always handles these events asynchronously.</p>"}))
