    DBShardGroup.add_member(:compute_redundancy, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ComputeRedundancy', traits: {"smithy.api#documentation" => "<p>Specifies whether to create standby DB shard groups for the DB shard group. Valid values are the following:</p>\n         <ul>\n            <li>\n               <p>0 - Creates a DB shard group without a standby DB shard group. This is the default value.</p>\n            </li>\n            <li>\n               <p>1 - Creates a DB shard group with a standby DB shard group in a different Availability Zone (AZ).</p>\n            </li>\n            <li>\n               <p>2 - Creates a DB shard group with two standby DB shard groups in two different AZs.</p>\n            </li>\n         </ul>"}))
