    DeleteCustomDBEngineVersionOutput.add_member(:supports_certificate_rotation_without_restart, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'SupportsCertificateRotationWithoutRestart', traits: {"smithy.api#documentation" => "<p>Indicates whether the engine version supports rotating the server certificate without \n              rebooting the DB instance.</p>"}))
