    DeleteCustomDBEngineVersionOutput.add_member(:supports_local_write_forwarding, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'SupportsLocalWriteForwarding', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports forwarding write operations from reader DB instances \n            to the writer DB instance in the DB cluster. By default, write operations aren't allowed on reader DB instances.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    DeleteCustomDBEngineVersionOutput.add_member(:supports_integrations, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsIntegrations', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports zero-ETL integrations with\n            Amazon Redshift.</p>"}))
