    DeleteDBClusterMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The DB cluster identifier for the DB cluster to be deleted. This parameter isn't case-sensitive.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match an existing DBClusterIdentifier.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    DeleteDBClusterMessage.add_member(:skip_final_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SkipFinalSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to skip the creation of a final DB cluster snapshot before RDS\n            deletes the DB cluster. If you set this value to <code>true</code>, RDS doesn't create a\n            final DB cluster snapshot. If you set this value to <code>false</code> or don't specify\n            it, RDS creates a DB cluster snapshot before it deletes the DB cluster. By default, this\n            parameter is disabled, so RDS creates a final DB cluster snapshot.</p>\n         <note>\n            <p>If <code>SkipFinalSnapshot</code> is disabled, you must specify a value for the\n                    <code>FinalDBSnapshotIdentifier</code> parameter.</p>\n         </note>"}))
