    DescribeDBClusterAutomatedBackupsMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>(Optional) The user-supplied DB cluster identifier. If this parameter is specified, it must\n            match the identifier of an existing DB cluster. It returns information from the\n            specific DB cluster's automated backup. This parameter isn't case-sensitive.</p>"}))
    DescribeDBClusterAutomatedBackupsMessage.add_member(:filters, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Filters', traits: {"smithy.api#documentation" => "<p>A filter that specifies which resources to return based on status.</p>\n         <p>Supported filters are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>status</code>\n               </p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>retained</code> - Automated backups for deleted clusters and after backup replication is stopped.</p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>\n                  <code>db-cluster-id</code> - Accepts DB cluster identifiers and Amazon Resource Names (ARNs). \n                    The results list includes only information about the DB cluster automated backups identified by these ARNs.</p>\n            </li>\n            <li>\n               <p>\n                  <code>db-cluster-resource-id</code> - Accepts DB resource identifiers and Amazon Resource Names (ARNs). \n                    The results list includes only information about the DB cluster resources identified by these ARNs.</p>\n            </li>\n         </ul>\n         <p>Returns all resources by default. The status for each resource is specified in the response.</p>"}))
    DescribeDBClusterAutomatedBackupsMessage.add_member(:max_records, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxRecords', traits: {"smithy.api#documentation" => "<p>The maximum number of records to include in the response. If more records exist than the specified <code>MaxRecords</code> \n            value, a pagination token called a marker is included in the response so that you can retrieve the remaining results.</p>"}))
