    DescribeDBClusterAutomatedBackupsMessage.type = Types::DescribeDBClusterAutomatedBackupsMessage
    DescribeDBClusterBacktracksMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The DB cluster identifier of the DB cluster to be described. This parameter is\n            stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 alphanumeric characters or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster1</code>\n         </p>", "smithy.api#required" => {}}))
    DescribeDBClusterBacktracksMessage.add_member(:backtrack_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BacktrackIdentifier', traits: {"smithy.api#documentation" => "<p>If specified, this value is the backtrack identifier of the backtrack to be\n            described.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain a valid universally unique identifier (UUID). For more information about UUIDs, see \n                    <a href=\"https://en.wikipedia.org/wiki/Universally_unique_identifier\">Universally unique \n                        identifier</a>.</p>\n            </li>\n         </ul>\n         <p>Example: <code>123e4567-e89b-12d3-a456-426655440000</code>\n         </p>"}))
    DescribeDBClusterBacktracksMessage.add_member(:filters, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Filters', traits: {"smithy.api#documentation" => "<p>A filter that specifies one or more DB clusters to describe. Supported filters\n            include the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db-cluster-backtrack-id</code> - Accepts backtrack identifiers. The\n                    results list includes information about only the backtracks identified by these\n                    identifiers.</p>\n            </li>\n            <li>\n               <p>\n                  <code>db-cluster-backtrack-status</code> - Accepts any of the following backtrack status values:</p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>applying</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>completed</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>failed</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>pending</code>\n                     </p>\n                  </li>\n               </ul>\n               <p>The results list includes information about only the backtracks identified\n                    by these values.</p>\n            </li>\n         </ul>"}))
    DescribeDBClusterBacktracksMessage.add_member(:max_records, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxRecords', traits: {"smithy.api#documentation" => "<p>The maximum number of records to include in the response.\n            If more records exist than the specified <code>MaxRecords</code> value,\n            a pagination token called a marker is included in the response so you can retrieve the remaining results.</p>\n         <p>Default: 100</p>\n         <p>Constraints: Minimum 20, maximum 100.</p>"}))
