    DescribeDBClusterSnapshotsMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The ID of the DB cluster to retrieve the list of DB cluster snapshots for. \n            This parameter can't be used in conjunction with the\n            <code>DBClusterSnapshotIdentifier</code> parameter.\n            This parameter isn't case-sensitive.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the identifier of an existing DBCluster.</p>\n            </li>\n         </ul>"}))
    DescribeDBClusterSnapshotsMessage.add_member(:db_cluster_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterSnapshotIdentifier', traits: {"smithy.api#documentation" => "<p>A specific DB cluster snapshot identifier to describe. \n            This parameter can't be used in conjunction with the\n            <code>DBClusterIdentifier</code> parameter.            \n            This value is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the identifier of an existing DBClusterSnapshot.</p>\n            </li>\n            <li>\n               <p>If this identifier is for an automated snapshot, the <code>SnapshotType</code> parameter must also be specified.</p>\n            </li>\n         </ul>"}))
    DescribeDBClusterSnapshotsMessage.add_member(:snapshot_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotType', traits: {"smithy.api#documentation" => "<p>The type of DB cluster snapshots to be returned. You can specify one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>automated</code> - Return all DB cluster snapshots that have been automatically taken by \n              Amazon RDS for my Amazon Web Services account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>manual</code> - Return all DB cluster snapshots that have been taken by my Amazon Web Services account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>shared</code> - Return all manual DB cluster snapshots that have been shared to my Amazon Web Services account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>public</code> - Return all DB cluster snapshots that have been marked as public.</p>\n            </li>\n         </ul>\n         <p>If you don't specify a <code>SnapshotType</code> value, then both automated and manual DB cluster snapshots are\n          returned. You can include shared DB cluster snapshots with these results by enabling the <code>IncludeShared</code>\n          parameter. You can include public DB cluster snapshots with these results by enabling the \n          <code>IncludePublic</code> parameter.</p>\n         <p>The <code>IncludeShared</code> and <code>IncludePublic</code> parameters don't apply for <code>SnapshotType</code> values\n          of <code>manual</code> or <code>automated</code>. The <code>IncludePublic</code> parameter doesn't apply when <code>SnapshotType</code> is\n          set to <code>shared</code>. The <code>IncludeShared</code> parameter doesn't apply when <code>SnapshotType</code> is set to\n          <code>public</code>.</p>"}))
    DescribeDBClusterSnapshotsMessage.add_member(:filters, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Filters', traits: {"smithy.api#documentation" => "<p>A filter that specifies one or more DB cluster snapshots to describe.</p>\n         <p>Supported filters:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db-cluster-id</code> - Accepts DB cluster identifiers and DB \n              cluster Amazon Resource Names (ARNs).</p>\n            </li>\n            <li>\n               <p>\n                  <code>db-cluster-snapshot-id</code> - Accepts DB cluster snapshot identifiers.</p>\n            </li>\n            <li>\n               <p>\n                  <code>snapshot-type</code> - Accepts types of DB cluster snapshots.</p>\n            </li>\n            <li>\n               <p>\n                  <code>engine</code> - Accepts names of database engines.</p>\n            </li>\n         </ul>"}))
    DescribeDBClusterSnapshotsMessage.add_member(:max_records, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxRecords', traits: {"smithy.api#documentation" => "<p>The maximum number of records to include in the response.\n            If more records exist than the specified <code>MaxRecords</code> value,\n          a pagination token called a marker is included in the response so you can retrieve the remaining results.</p>\n         <p>Default: 100</p>\n         <p>Constraints: Minimum 20, maximum 100.</p>"}))
    DescribeDBClusterSnapshotsMessage.add_member(:marker, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Marker', traits: {"smithy.api#documentation" => "<p>An optional pagination token provided by a previous\n            <code>DescribeDBClusterSnapshots</code> request.\n            If this parameter is specified, the response includes\n            only records beyond the marker,\n            up to the value specified by <code>MaxRecords</code>.</p>"}))
    DescribeDBClusterSnapshotsMessage.add_member(:include_shared, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IncludeShared', traits: {"smithy.api#documentation" => "<p>Specifies whether to include shared manual DB cluster snapshots \n            from other Amazon Web Services accounts that this Amazon Web Services account has been given \n            permission to copy or restore. By default, these snapshots are not included.</p>\n         <p>You can give an Amazon Web Services account permission to restore a manual DB cluster snapshot from\n            another Amazon Web Services account by the <code>ModifyDBClusterSnapshotAttribute</code> API action.</p>"}))
    DescribeDBClusterSnapshotsMessage.add_member(:include_public, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IncludePublic', traits: {"smithy.api#documentation" => "<p>Specifies whether to include manual DB cluster snapshots that are public and can be copied \n            or restored by any Amazon Web Services account. By default, the public snapshots are not included.</p>\n         <p>You can share a manual DB cluster snapshot  as public by using the <a>ModifyDBClusterSnapshotAttribute</a> API action.</p>"}))
    DescribeDBClusterSnapshotsMessage.add_member(:db_cluster_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DbClusterResourceId', traits: {"smithy.api#documentation" => "<p>A specific DB cluster resource ID to describe.</p>"}))
