    DescribeDBEngineVersionsMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The database engine to return version details for.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>aurora-mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>aurora-postgresql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-ee-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-se2</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-se2-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>db2-ae</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>db2-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mariadb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>postgres</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ex</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-web</code>\n               </p>\n            </li>\n         </ul>"}))
    DescribeDBEngineVersionsMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>A specific database engine version to return details for.</p>\n         <p>Example: <code>5.1.49</code>\n         </p>"}))
    DescribeDBEngineVersionsMessage.add_member(:db_parameter_group_family, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupFamily', traits: {"smithy.api#documentation" => "<p>The name of a specific DB parameter group family to return details for.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match an existing DB parameter group family.</p>\n            </li>\n         </ul>"}))
    DescribeDBEngineVersionsMessage.add_member(:filters, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Filters', traits: {"smithy.api#documentation" => "<p>A filter that specifies one or more DB engine versions to describe.</p>\n         <p>Supported filters:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db-parameter-group-family</code> - Accepts parameter groups family names. \n                  The results list only includes information about\n                  the DB engine versions for these parameter group families.</p>\n            </li>\n            <li>\n               <p>\n                  <code>engine</code> - Accepts engine names. \n                  The results list only includes information about\n                  the DB engine versions for these engines.</p>\n            </li>\n            <li>\n               <p>\n                  <code>engine-mode</code> - Accepts DB engine modes. \n                  The results list only includes information about\n                  the DB engine versions for these engine modes. Valid \n                  DB engine modes are the following:</p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>global</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>multimaster</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>parallelquery</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>provisioned</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>serverless</code>\n                     </p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>\n                  <code>engine-version</code> - Accepts engine versions. \n                  The results list only includes information about\n                  the DB engine versions for these engine versions.</p>\n            </li>\n            <li>\n               <p>\n                  <code>status</code> - Accepts engine version statuses. \n                  The results list only includes information about\n                  the DB engine versions for these statuses. Valid statuses \n                  are the following:</p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>available</code>\n                     </p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>deprecated</code>\n                     </p>\n                  </li>\n               </ul>\n            </li>\n         </ul>"}))
    DescribeDBEngineVersionsMessage.add_member(:max_records, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxRecords', traits: {"smithy.api#documentation" => "<p>The maximum number of records to include in the response.\n    If more than the <code>MaxRecords</code> value is available, a pagination token called a marker is\n    included in the response so you can retrieve the remaining results.</p>\n         <p>Default: 100</p>\n         <p>Constraints: Minimum 20, maximum 100.</p>"}))
    DescribeDBEngineVersionsMessage.add_member(:marker, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Marker', traits: {"smithy.api#documentation" => "<p>An optional pagination token provided by a previous request.\n        If this parameter is specified, the response includes\n        only records beyond the marker,\n        up to the value specified by <code>MaxRecords</code>.</p>"}))
