    DescribeDBInstanceAutomatedBackupsMessage.add_member(:filters, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Filters', traits: {"smithy.api#documentation" => "<p>A filter that specifies which resources to return based on status.</p>\n         <p>Supported filters are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>status</code>\n               </p>\n               <ul>\n                  <li>\n                     <p>\n                        <code>active</code> - Automated backups for current instances.</p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>creating</code> - Automated backups that are waiting for the first automated snapshot to be available.</p>\n                  </li>\n                  <li>\n                     <p>\n                        <code>retained</code> - Automated backups for deleted instances and after backup replication is stopped.</p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>\n                  <code>db-instance-id</code> - Accepts DB instance identifiers and Amazon Resource Names (ARNs). \n                The results list includes only information about the DB instance automated backups identified by these ARNs.</p>\n            </li>\n            <li>\n               <p>\n                  <code>dbi-resource-id</code> - Accepts DB resource identifiers and Amazon Resource Names (ARNs). \n                The results list includes only information about the DB instance resources identified by these ARNs.</p>\n            </li>\n         </ul>\n         <p>Returns all resources by default. The status for each resource is specified in the response.</p>"}))
    DescribeDBInstanceAutomatedBackupsMessage.add_member(:max_records, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxRecords', traits: {"smithy.api#documentation" => "<p>The maximum number of records to include in the response. If more records exist than the specified \n            <code>MaxRecords</code> value, a pagination token called a marker is included in the response so that \n            you can retrieve the remaining results.</p>"}))
    DescribeDBInstanceAutomatedBackupsMessage.add_member(:marker, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Marker', traits: {"smithy.api#documentation" => "<p>The pagination token provided in the previous request. If this parameter is specified the response \n            includes only records beyond the marker, up to <code>MaxRecords</code>.</p>"}))
    DescribeDBInstanceAutomatedBackupsMessage.add_member(:db_instance_automated_backups_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceAutomatedBackupsArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the replicated automated backups, for example,\n            <code>arn:aws:rds:us-east-1:123456789012:auto-backup:ab-L2IJCEXJP7XQ7HOJ4SIEXAMPLE</code>.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
