    DescribeDBSnapshotTenantDatabasesMessage.add_member(:db_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSnapshotIdentifier', traits: {"smithy.api#documentation" => "<p>The ID of a DB snapshot that contains the tenant databases to describe. This value is\n            stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If you specify this parameter, the value must match the ID of an existing DB snapshot.</p>\n            </li>\n            <li>\n               <p>If you specify an automatic snapshot, you must also specify\n                <code>SnapshotType</code>.</p>\n            </li>\n         </ul>"}))
    DescribeDBSnapshotTenantDatabasesMessage.add_member(:snapshot_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotType', traits: {"smithy.api#documentation" => "<p>The type of DB snapshots to be returned. You can specify one of the following\n            values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>automated</code> – All DB snapshots that have been automatically taken\n                    by Amazon RDS for my Amazon Web Services account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>manual</code> – All DB snapshots that have been taken by my Amazon Web\n                    Services account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>shared</code> – All manual DB snapshots that have been shared to my\n                    Amazon Web Services account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>public</code> – All DB snapshots that have been marked as public.</p>\n            </li>\n            <li>\n               <p>\n                  <code>awsbackup</code> – All DB snapshots managed by the Amazon Web Services Backup\n                    service.</p>\n            </li>\n         </ul>"}))
    DescribeDBSnapshotTenantDatabasesMessage.add_member(:filters, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Filters', traits: {"smithy.api#documentation" => "<p>A filter that specifies one or more tenant databases to describe.</p>\n         <p>Supported filters:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>tenant-db-name</code> - Tenant database names. The results list only\n                    includes information about the tenant databases that match these tenant DB\n                    names.</p>\n            </li>\n            <li>\n               <p>\n                  <code>tenant-database-resource-id</code> - Tenant database resource\n                    identifiers. The results list only includes information about the tenant\n                    databases contained within the DB snapshots.</p>\n            </li>\n            <li>\n               <p>\n                  <code>dbi-resource-id</code> - DB instance resource identifiers. The results\n                    list only includes information about snapshots containing tenant databases\n                    contained within the DB instances identified by these resource\n                    identifiers.</p>\n            </li>\n            <li>\n               <p>\n                  <code>db-instance-id</code> - Accepts DB instance identifiers and DB instance\n                    Amazon Resource Names (ARNs).</p>\n            </li>\n            <li>\n               <p>\n                  <code>db-snapshot-id</code> - Accepts DB snapshot identifiers.</p>\n            </li>\n            <li>\n               <p>\n                  <code>snapshot-type</code> - Accepts types of DB snapshots.</p>\n            </li>\n         </ul>"}))
    DescribeDBSnapshotTenantDatabasesMessage.add_member(:max_records, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxRecords', traits: {"smithy.api#documentation" => "<p>The maximum number of records to include in the response. If more records exist than\n            the specified <code>MaxRecords</code> value, a pagination token called a marker is\n            included in the response so that you can retrieve the remaining results.</p>"}))
    DescribeDBSnapshotTenantDatabasesMessage.add_member(:marker, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Marker', traits: {"smithy.api#documentation" => "<p>An optional pagination token provided by a previous\n                <code>DescribeDBSnapshotTenantDatabases</code> request. If this parameter is\n            specified, the response includes only records beyond the marker, up to the value\n            specified by <code>MaxRecords</code>.</p>"}))
    DescribeDBSnapshotTenantDatabasesMessage.add_member(:dbi_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DbiResourceId', traits: {"smithy.api#documentation" => "<p>A specific DB resource identifier to describe.</p>"}))
    DescribeDBSnapshotTenantDatabasesMessage.type = Types::DescribeDBSnapshotTenantDatabasesMessage
    DescribeDBSnapshotsMessage.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#documentation" => "<p>The ID of the DB instance to retrieve the list of DB snapshots for. \n        This parameter isn't case-sensitive.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the identifier of an existing DBInstance.</p>\n            </li>\n         </ul>"}))
    DescribeDBSnapshotsMessage.add_member(:db_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSnapshotIdentifier', traits: {"smithy.api#documentation" => "<p>A specific DB snapshot identifier to describe.\n            This value is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the identifier of an existing DBSnapshot.</p>\n            </li>\n            <li>\n               <p>If this identifier is for an automated snapshot, the <code>SnapshotType</code> parameter must also be specified.</p>\n            </li>\n         </ul>"}))
    DescribeDBSnapshotsMessage.add_member(:snapshot_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotType', traits: {"smithy.api#documentation" => "<p>The type of snapshots to be returned. You can specify one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>automated</code> - Return all DB snapshots that have been automatically taken by \n      Amazon RDS for my Amazon Web Services account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>manual</code> - Return all DB snapshots that have been taken by my Amazon Web Services account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>shared</code> - Return all manual DB snapshots that have been shared to my Amazon Web Services account.</p>\n            </li>\n            <li>\n               <p>\n                  <code>public</code> - Return all DB snapshots that have been marked as public.</p>\n            </li>\n            <li>\n               <p>\n                  <code>awsbackup</code> - Return the DB snapshots managed by the Amazon Web Services Backup service.</p>\n               <p>For information about Amazon Web Services Backup, see the \n                  <a href=\"https://docs.aws.amazon.com/aws-backup/latest/devguide/whatisbackup.html\">\n                     <i>Amazon Web Services Backup Developer Guide.</i>\n                  </a>\n               </p>\n               <p>The <code>awsbackup</code> type does not apply to Aurora.</p>\n            </li>\n         </ul>\n         <p>If you don't specify a <code>SnapshotType</code> value, then both automated and manual snapshots are\n      returned. Shared and public DB snapshots are not included in the returned results by default.\n      You can include shared snapshots with these results by enabling the <code>IncludeShared</code>\n      parameter. You can include public snapshots with these results by enabling the \n      <code>IncludePublic</code> parameter.</p>\n         <p>The <code>IncludeShared</code> and <code>IncludePublic</code> parameters don't apply for <code>SnapshotType</code> values\n      of <code>manual</code> or <code>automated</code>. The <code>IncludePublic</code> parameter doesn't apply when <code>SnapshotType</code> is\n      set to <code>shared</code>. The <code>IncludeShared</code> parameter doesn't apply when <code>SnapshotType</code> is set to\n      <code>public</code>.</p>"}))
    DescribeDBSnapshotsMessage.add_member(:filters, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterList, location_name: 'Filters', traits: {"smithy.api#documentation" => "<p>A filter that specifies one or more DB snapshots to describe.</p>\n         <p>Supported filters:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db-instance-id</code> - Accepts DB instance identifiers and DB \n              instance Amazon Resource Names (ARNs).</p>\n            </li>\n            <li>\n               <p>\n                  <code>db-snapshot-id</code> - Accepts DB snapshot identifiers.</p>\n            </li>\n            <li>\n               <p>\n                  <code>dbi-resource-id</code> - Accepts identifiers of source DB instances.</p>\n            </li>\n            <li>\n               <p>\n                  <code>snapshot-type</code> - Accepts types of DB snapshots.</p>\n            </li>\n            <li>\n               <p>\n                  <code>engine</code> - Accepts names of database engines.</p>\n            </li>\n         </ul>"}))
    DescribeDBSnapshotsMessage.add_member(:max_records, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxRecords', traits: {"smithy.api#documentation" => "<p>The maximum number of records to include in the response.\n        If more records exist than the specified <code>MaxRecords</code> value,\n        a pagination token called a marker is included in the response so that\n        you can retrieve the remaining results.</p>\n         <p>Default: 100</p>\n         <p>Constraints: Minimum 20, maximum 100.</p>"}))
    DescribeDBSnapshotsMessage.add_member(:marker, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Marker', traits: {"smithy.api#documentation" => "<p>An optional pagination token provided by a previous\n        <code>DescribeDBSnapshots</code> request.\n            If this parameter is specified, the response includes\n        only records beyond the marker,\n        up to the value specified by <code>MaxRecords</code>.</p>"}))
    DescribeDBSnapshotsMessage.add_member(:include_shared, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IncludeShared', traits: {"smithy.api#documentation" => "<p>Specifies whether to include shared manual DB cluster snapshots \n          from other Amazon Web Services accounts that this Amazon Web Services account has been given \n          permission to copy or restore. By default, these snapshots are not included.</p>\n         <p>You can give an Amazon Web Services account permission to restore a manual DB snapshot from\n    another Amazon Web Services account by using the <code>ModifyDBSnapshotAttribute</code> API action.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    DescribeDBSnapshotsMessage.add_member(:include_public, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IncludePublic', traits: {"smithy.api#documentation" => "<p>Specifies whether to include manual DB cluster snapshots that are public and can be copied \n          or restored by any Amazon Web Services account. By default, the public snapshots are not included.</p>\n         <p>You can share a manual DB snapshot as public by using the <a>ModifyDBSnapshotAttribute</a> API.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    DescribeDBSnapshotsMessage.add_member(:dbi_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DbiResourceId', traits: {"smithy.api#documentation" => "<p>A specific DB resource ID to describe.</p>"}))
    DescribeDBSnapshotsMessage.type = Types::DescribeDBSnapshotsMessage
