    DescribeEventsMessage.add_member(:source_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of the event source for which events are returned. If not specified, then all sources are included in the response.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If <code>SourceIdentifier</code> is supplied, <code>SourceType</code> must also be provided.</p>\n            </li>\n            <li>\n               <p>If the source type is a DB instance, a <code>DBInstanceIdentifier</code> value must be supplied.</p>\n            </li>\n            <li>\n               <p>If the source type is a DB cluster, a <code>DBClusterIdentifier</code> value must be supplied.</p>\n            </li>\n            <li>\n               <p>If the source type is a DB parameter group, a <code>DBParameterGroupName</code> value must be supplied.</p>\n            </li>\n            <li>\n               <p>If the source type is a DB security group, a <code>DBSecurityGroupName</code> value must be supplied.</p>\n            </li>\n            <li>\n               <p>If the source type is a DB snapshot, a <code>DBSnapshotIdentifier</code> value must be supplied.</p>\n            </li>\n            <li>\n               <p>If the source type is a DB cluster snapshot, a <code>DBClusterSnapshotIdentifier</code> value must be supplied.</p>\n            </li>\n            <li>\n               <p>If the source type is an RDS Proxy, a <code>DBProxyName</code> value must be supplied.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>"}))
    DescribeEventsMessage.add_member(:source_type, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceType, location_name: 'SourceType', traits: {"smithy.api#documentation" => "<p>The event source to retrieve events for. If no value is specified, all events are returned.</p>"}))
    DescribeEventsMessage.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The beginning of the time interval to retrieve events for,\n        specified in ISO 8601 format. For more information about ISO 8601, \n        go to the <a href=\"http://en.wikipedia.org/wiki/ISO_8601\">ISO8601 Wikipedia page.</a>\n         </p>\n         <p>Example: 2009-07-08T18:00Z</p>"}))
    DescribeEventsMessage.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'EndTime', traits: {"smithy.api#documentation" => "<p>The end of the time interval for which to retrieve events,\n        specified in ISO 8601 format. For more information about ISO 8601, \n        go to the <a href=\"http://en.wikipedia.org/wiki/ISO_8601\">ISO8601 Wikipedia page.</a>\n         </p>\n         <p>Example: 2009-07-08T18:00Z</p>"}))
    DescribeEventsMessage.add_member(:duration, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Duration', traits: {"smithy.api#documentation" => "<p>The number of minutes to retrieve events for.</p>\n         <p>Default: 60</p>"}))
