    ModifyCurrentDBClusterCapacityMessage.add_member(:capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Capacity', traits: {"smithy.api#documentation" => "<p>The DB cluster capacity.</p>\n         <p>When you change the capacity of a paused Aurora Serverless v1 DB cluster, it automatically resumes.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>For Aurora MySQL, valid capacity values are <code>1</code>, <code>2</code>, <code>4</code>, <code>8</code>, <code>16</code>, <code>32</code>, <code>64</code>, <code>128</code>, and <code>256</code>.</p>\n            </li>\n            <li>\n               <p>For Aurora PostgreSQL, valid capacity values are <code>2</code>, <code>4</code>, <code>8</code>, <code>16</code>, <code>32</code>, <code>64</code>, <code>192</code>, and <code>384</code>.</p>\n            </li>\n         </ul>"}))
    ModifyCurrentDBClusterCapacityMessage.add_member(:seconds_before_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SecondsBeforeTimeout', traits: {"smithy.api#documentation" => "<p>The amount of time, in seconds, that Aurora Serverless v1 tries to find a scaling point\n            to perform seamless scaling before enforcing the timeout action. The default is\n            300.</p>\n         <p>Specify a value between 10 and 600 seconds.</p>"}))
    ModifyCurrentDBClusterCapacityMessage.add_member(:timeout_action, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TimeoutAction', traits: {"smithy.api#documentation" => "<p>The action to take when the timeout is reached, either <code>ForceApplyCapacityChange</code> or <code>RollbackCapacityChange</code>.</p>\n         <p>\n            <code>ForceApplyCapacityChange</code>, the default, sets the capacity to the specified value as soon as possible.</p>\n         <p>\n            <code>RollbackCapacityChange</code> ignores the capacity change if a scaling point isn't found in the timeout period.</p>"}))
    ModifyCurrentDBClusterCapacityMessage.type = Types::ModifyCurrentDBClusterCapacityMessage
    ModifyCurrentDBClusterCapacityOutput.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>A user-supplied DB cluster identifier. This identifier is the unique key that\n            identifies a DB cluster.</p>"}))
    ModifyCurrentDBClusterCapacityOutput.add_member(:pending_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PendingCapacity', traits: {"smithy.api#documentation" => "<p>A value that specifies the capacity that the DB cluster scales to next.</p>"}))
    ModifyCurrentDBClusterCapacityOutput.add_member(:current_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'CurrentCapacity', traits: {"smithy.api#documentation" => "<p>The current capacity of the DB cluster.</p>"}))
    ModifyCurrentDBClusterCapacityOutput.add_member(:seconds_before_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SecondsBeforeTimeout', traits: {"smithy.api#documentation" => "<p>The number of seconds before a call to <code>ModifyCurrentDBClusterCapacity</code> times out.</p>"}))
    ModifyCurrentDBClusterCapacityOutput.add_member(:timeout_action, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TimeoutAction', traits: {"smithy.api#documentation" => "<p>The timeout action of a call to <code>ModifyCurrentDBClusterCapacity</code>, either \n            <code>ForceApplyCapacityChange</code> or <code>RollbackCapacityChange</code>.</p>"}))
    ModifyCurrentDBClusterCapacityOutput.type = Types::ModifyCurrentDBClusterCapacityOutput
    ModifyCustomDBEngineVersionMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomEngineName, location_name: 'Engine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The database engine. RDS Custom for Oracle supports the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>custom-oracle-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-ee-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-se2</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>custom-oracle-se2-cdb</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ModifyCustomDBEngineVersionMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomEngineVersion, location_name: 'EngineVersion', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The custom engine version (CEV) that you want to modify. This option is required for \n            RDS Custom for Oracle, but optional for Amazon RDS. The combination of <code>Engine</code> and \n            <code>EngineVersion</code> is unique per customer per Amazon Web Services Region.</p>", "smithy.api#required" => {}}))
    ModifyCustomDBEngineVersionMessage.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>An optional description of your CEV.</p>"}))
    ModifyCustomDBEngineVersionMessage.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomEngineVersionStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The availability status to be assigned to the CEV. Valid values are as follows:</p>\n         <dl>\n            <dt>available</dt>\n            <dd>\n               <p>You can use this CEV to create a new RDS Custom DB instance.</p>\n            </dd>\n            <dt>inactive</dt>\n            <dd>\n               <p>You can create a new RDS Custom instance by restoring a DB snapshot with this CEV. \n                    You can't patch or create new instances with this CEV.</p>\n            </dd>\n         </dl>\n         <p>You can change any status to any status. A typical reason to change status is to prevent the accidental \n            use of a CEV, or to make a deprecated CEV eligible for use again. For example, you might change the status \n            of your CEV from <code>available</code> to <code>inactive</code>, and from <code>inactive</code> back to \n            <code>available</code>. To change the availability status of the CEV, it must not currently be in use by an \n            RDS Custom instance, snapshot, or automated backup.</p>"}))
    ModifyCustomDBEngineVersionMessage.type = Types::ModifyCustomDBEngineVersionMessage
    ModifyCustomDBEngineVersionOutput.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The name of the database engine.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:db_parameter_group_family, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupFamily', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group family for the database engine.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:db_engine_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBEngineDescription', traits: {"smithy.api#documentation" => "<p>The description of the database engine.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:db_engine_version_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBEngineVersionDescription', traits: {"smithy.api#documentation" => "<p>The description of the database engine version.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:default_character_set, Smithy::Schema::Shapes::ShapeRef.new(shape: CharacterSet, location_name: 'DefaultCharacterSet', traits: {"smithy.api#documentation" => "<p>The default character set for new instances of this engine version,\n            if the <code>CharacterSetName</code> parameter of the CreateDBInstance API\n            isn't specified.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:image, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomDBEngineVersionAMI, location_name: 'Image', traits: {"smithy.api#documentation" => "<p>The EC2 image</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:db_engine_media_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBEngineMediaType', traits: {"smithy.api#documentation" => "<p>A value that indicates the source media provider of the AMI based on the usage operation.  Applicable for RDS Custom for SQL Server.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supported_character_sets, Smithy::Schema::Shapes::ShapeRef.new(shape: SupportedCharacterSetsList, location_name: 'SupportedCharacterSets', traits: {"smithy.api#documentation" => "<p>A list of the character sets supported by this engine for the <code>CharacterSetName</code> parameter of the <code>CreateDBInstance</code> operation.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supported_nchar_character_sets, Smithy::Schema::Shapes::ShapeRef.new(shape: SupportedCharacterSetsList, location_name: 'SupportedNcharCharacterSets', traits: {"smithy.api#documentation" => "<p>A list of the character sets supported by the Oracle DB engine for the <code>NcharCharacterSetName</code> parameter of the <code>CreateDBInstance</code> operation.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:valid_upgrade_target, Smithy::Schema::Shapes::ShapeRef.new(shape: ValidUpgradeTargetList, location_name: 'ValidUpgradeTarget', traits: {"smithy.api#documentation" => "<p>A list of engine versions that this database engine version can be upgraded to.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supported_timezones, Smithy::Schema::Shapes::ShapeRef.new(shape: SupportedTimezonesList, location_name: 'SupportedTimezones', traits: {"smithy.api#documentation" => "<p>A list of the time zones supported by this engine for the\n            <code>Timezone</code> parameter of the <code>CreateDBInstance</code> action.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:exportable_log_types, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'ExportableLogTypes', traits: {"smithy.api#documentation" => "<p>The types of logs that the database engine has available for export to CloudWatch Logs.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supports_log_exports_to_cloudwatch_logs, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsLogExportsToCloudwatchLogs', traits: {"smithy.api#documentation" => "<p>Indicates whether the engine version supports exporting the log types specified by ExportableLogTypes to CloudWatch Logs.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supports_read_replica, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsReadReplica', traits: {"smithy.api#documentation" => "<p>Indicates whether the database engine version supports read replicas.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supported_engine_modes, Smithy::Schema::Shapes::ShapeRef.new(shape: EngineModeList, location_name: 'SupportedEngineModes', traits: {"smithy.api#documentation" => "<p>A list of the supported DB engine modes.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supported_feature_names, Smithy::Schema::Shapes::ShapeRef.new(shape: FeatureNameList, location_name: 'SupportedFeatureNames', traits: {"smithy.api#documentation" => "<p>A list of features supported by the DB engine.</p>\n         <p>The supported features vary by DB engine and DB engine version.</p>\n         <p>To determine the supported features for a specific DB engine and DB engine version using the CLI, \n        use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine <engine_name> --engine-version <engine_version></code>\n         </p>\n         <p>For example, to determine the supported features for RDS for PostgreSQL version 13.3 using the CLI, \n        use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine postgres --engine-version 13.3</code>\n         </p>\n         <p>The supported features are listed under <code>SupportedFeatureNames</code> in the output.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the DB engine version, either <code>available</code> or <code>deprecated</code>.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supports_parallel_query, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsParallelQuery', traits: {"smithy.api#documentation" => "<p>Indicates whether you can use Aurora parallel query with a specific DB engine version.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supports_global_databases, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsGlobalDatabases', traits: {"smithy.api#documentation" => "<p>Indicates whether you can use Aurora global databases with a specific DB engine version.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:major_engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MajorEngineVersion', traits: {"smithy.api#documentation" => "<p>The major engine version of the CEV.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:database_installation_files_s3_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseInstallationFilesS3BucketName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon S3 bucket that contains your database installation files.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:database_installation_files_s3_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseInstallationFilesS3Prefix', traits: {"smithy.api#documentation" => "<p>The Amazon S3 directory that contains the database installation files. \n            If not specified, then no prefix is assumed.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:db_engine_version_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBEngineVersionArn', traits: {"smithy.api#documentation" => "<p>The ARN of the custom engine version.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for an encrypted CEV. This parameter is required for \n            RDS Custom, but optional for Amazon RDS.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:create_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'CreateTime', traits: {"smithy.api#documentation" => "<p>The creation time of the DB engine version.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:tag_list, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'TagList'))
    ModifyCustomDBEngineVersionOutput.add_member(:supports_babelfish, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsBabelfish', traits: {"smithy.api#documentation" => "<p>Indicates whether the engine version supports Babelfish for Aurora PostgreSQL.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:custom_db_engine_version_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomDBEngineVersionManifest, location_name: 'CustomDBEngineVersionManifest', traits: {"smithy.api#documentation" => "<p>JSON string that lists the installation files and parameters that RDS Custom uses to create a custom engine version (CEV). \n          RDS Custom applies the patches in the order in which they're listed in the manifest. You can set the Oracle home, Oracle base, \n          and UNIX/Linux user and group using the installation parameters. For more information, \n          see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-cev.preparing.html#custom-cev.preparing.manifest.fields\">JSON fields in the CEV manifest</a> in the <i>Amazon RDS User Guide</i>.\n      </p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supports_limitless_database, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsLimitlessDatabase', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports Aurora Limitless Database.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supports_certificate_rotation_without_restart, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'SupportsCertificateRotationWithoutRestart', traits: {"smithy.api#documentation" => "<p>Indicates whether the engine version supports rotating the server certificate without \n              rebooting the DB instance.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supported_ca_certificate_identifiers, Smithy::Schema::Shapes::ShapeRef.new(shape: CACertificateIdentifiersList, location_name: 'SupportedCACertificateIdentifiers', traits: {"smithy.api#documentation" => "<p>A list of the supported CA certificate identifiers.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n            instance</a> in the <i>Amazon RDS User Guide</i> and \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL.html\">\n            Using SSL/TLS to encrypt a connection to a DB cluster</a> in the <i>Amazon Aurora \n            User Guide</i>.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supports_local_write_forwarding, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'SupportsLocalWriteForwarding', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports forwarding write operations from reader DB instances \n            to the writer DB instance in the DB cluster. By default, write operations aren't allowed on reader DB instances.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:supports_integrations, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SupportsIntegrations', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB engine version supports zero-ETL integrations with\n            Amazon Redshift.</p>"}))
    ModifyCustomDBEngineVersionOutput.add_member(:serverless_v2_features_support, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2FeaturesSupport, location_name: 'ServerlessV2FeaturesSupport', traits: {"smithy.api#documentation" => "<p>Specifies any Aurora Serverless v2 properties or limits that differ between Aurora engine versions.\n        You can test the values of this attribute when deciding which Aurora version to use in a new or upgraded\n        DB cluster. You can also retrieve the version of an existing DB cluster and check whether that version\n        supports certain Aurora Serverless v2 features before you attempt to use those features.\n      </p>"}))
    ModifyCustomDBEngineVersionOutput.type = Types::ModifyCustomDBEngineVersionOutput
    ModifyDBClusterEndpointMessage.add_member(:db_cluster_endpoint_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterEndpointIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier of the endpoint to modify. This parameter is stored as a lowercase string.</p>", "smithy.api#required" => {}}))
    ModifyDBClusterEndpointMessage.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EndpointType', traits: {"smithy.api#documentation" => "<p>The type of the endpoint. One of: <code>READER</code>, <code>WRITER</code>, <code>ANY</code>.</p>"}))
    ModifyDBClusterEndpointMessage.add_member(:static_members, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'StaticMembers', traits: {"smithy.api#documentation" => "<p>List of DB instance identifiers that are part of the custom endpoint group.</p>"}))
    ModifyDBClusterEndpointMessage.add_member(:excluded_members, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'ExcludedMembers', traits: {"smithy.api#documentation" => "<p>List of DB instance identifiers that aren't part of the custom endpoint group.\n       All other eligible instances are reachable through the custom endpoint.\n       Only relevant if the list of static members is empty.</p>"}))
    ModifyDBClusterEndpointMessage.type = Types::ModifyDBClusterEndpointMessage
    ModifyDBClusterEndpointOutput.add_member(:db_cluster_endpoint_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterEndpointIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier associated with the endpoint. This parameter is stored as a lowercase string.</p>"}))
    ModifyDBClusterEndpointOutput.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The DB cluster identifier of the DB cluster associated with the endpoint. This parameter is\n            stored as a lowercase string.</p>"}))
    ModifyDBClusterEndpointOutput.add_member(:db_cluster_endpoint_resource_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterEndpointResourceIdentifier', traits: {"smithy.api#documentation" => "<p>A unique system-generated identifier for an endpoint. It remains the same for the whole life of the endpoint.</p>"}))
    ModifyDBClusterEndpointOutput.add_member(:endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Endpoint', traits: {"smithy.api#documentation" => "<p>The DNS address of the endpoint.</p>"}))
    ModifyDBClusterEndpointOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The current status of the endpoint. One of: <code>creating</code>, <code>available</code>, <code>deleting</code>, <code>inactive</code>, <code>modifying</code>. The <code>inactive</code> state applies to an endpoint that can't be used for a certain kind of cluster,\n     such as a <code>writer</code> endpoint for a read-only secondary cluster in a global database.</p>"}))
    ModifyDBClusterEndpointOutput.add_member(:endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EndpointType', traits: {"smithy.api#documentation" => "<p>The type of the endpoint. One of: <code>READER</code>, <code>WRITER</code>, <code>CUSTOM</code>.</p>"}))
    ModifyDBClusterEndpointOutput.add_member(:custom_endpoint_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CustomEndpointType', traits: {"smithy.api#documentation" => "<p>The type associated with a custom endpoint. One of: <code>READER</code>,\n       <code>WRITER</code>, <code>ANY</code>.</p>"}))
    ModifyDBClusterEndpointOutput.add_member(:static_members, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'StaticMembers', traits: {"smithy.api#documentation" => "<p>List of DB instance identifiers that are part of the custom endpoint group.</p>"}))
    ModifyDBClusterEndpointOutput.add_member(:excluded_members, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'ExcludedMembers', traits: {"smithy.api#documentation" => "<p>List of DB instance identifiers that aren't part of the custom endpoint group.\n       All other eligible instances are reachable through the custom endpoint.\n       Only relevant if the list of static members is empty.</p>"}))
    ModifyDBClusterEndpointOutput.add_member(:db_cluster_endpoint_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterEndpointArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the endpoint.</p>"}))
    ModifyDBClusterEndpointOutput.type = Types::ModifyDBClusterEndpointOutput
    ModifyDBClusterMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The DB cluster identifier for the cluster being modified. This parameter isn't case-sensitive.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing DB cluster.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ModifyDBClusterMessage.add_member(:new_db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NewDBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The new DB cluster identifier for the DB cluster when renaming a DB cluster. This value is stored as a lowercase string.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster2</code>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:apply_immediately, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ApplyImmediately', traits: {"smithy.api#documentation" => "<p>Specifies whether the modifications in this request are asynchronously applied as soon as possible, regardless of the \n            <code>PreferredMaintenanceWindow</code> setting for the DB cluster. If this parameter is disabled, changes to the DB cluster \n            are applied during the next maintenance window.</p>\n         <p>Most modifications can be applied immediately or during the next scheduled maintenance window. Some modifications, such as \n            turning on deletion protection and changing the master password, are applied immediately—regardless of when you choose to apply them.</p>\n         <p>By default, this parameter is disabled.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days for which automated backups are retained. Specify a minimum value of <code>1</code>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Default: <code>1</code>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a value from 1 to 35.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB cluster parameter group to use for the DB cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of EC2 VPC security groups to associate with this DB cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the DB cluster accepts connections.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>\n         <p>Valid Values: <code>1150-65535</code>\n         </p>\n         <p>Default: The same port as the original DB cluster.</p>"}))
    ModifyDBClusterMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>The new password for the master database user.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 8 to 41 characters.</p>\n            </li>\n            <li>\n               <p>Can contain any printable ASCII character except \"/\", \"\"\", or \"@\".</p>\n            </li>\n            <li>\n               <p>Can't be specified if <code>ManageMasterUserPassword</code> is turned on.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The option group to associate the DB cluster with.</p>\n         <p>DB clusters are associated with a default option group that can't be modified.</p>"}))
    ModifyDBClusterMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created\n            if automated backups are enabled,\n            using the <code>BackupRetentionPeriod</code> parameter.</p>\n         <p>The default is a 30-minute window selected at random from an\n            8-hour block of time for each Amazon Web Services Region. \n            To view the time blocks available, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Aurora.Managing.Backups.html#Aurora.Managing.Backups.BackupWindow\">\n                Backup window</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur, in Universal Coordinated Time (UTC).</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>The default is a 30-minute window selected at random from an\n            8-hour block of time for each Amazon Web Services Region, occurring on a random day of the\n            week. To see the time blocks available, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_UpgradeDBInstance.Maintenance.html#AdjustingTheMaintenanceWindow.Aurora\">\n                Adjusting the Preferred DB Cluster Maintenance Window</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>ddd:hh24:mi-ddd:hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Days must be one of <code>Mon | Tue | Wed | Thu | Fri | Sat | Sun</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access\n            Management (IAM) accounts to database accounts. By default, mapping isn't\n            enabled.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.IAMDBAuth.html\"> IAM Database\n                Authentication</a> in the <i>Amazon Aurora User Guide</i> or\n                <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\">IAM database\n                authentication for MariaDB, MySQL, and PostgreSQL</a> in the <i>Amazon\n                RDS User Guide</i>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:backtrack_window, Smithy::Schema::Shapes::ShapeRef.new(shape: LongOptional, location_name: 'BacktrackWindow', traits: {"smithy.api#documentation" => "<p>The target backtrack window, in seconds. To disable backtracking, set this value to\n            <code>0</code>.</p>\n         <p>Valid for Cluster Type: Aurora MySQL DB clusters only</p>\n         <p>Default: <code>0</code>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If specified, this value must be set to a number from 0 to 259,200 (72 hours).</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:cloudwatch_logs_export_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CloudwatchLogsExportConfiguration, location_name: 'CloudwatchLogsExportConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration setting for the log types to be enabled for export to CloudWatch Logs for a specific DB cluster.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>The following values are valid for each DB engine:</p>\n         <ul>\n            <li>\n               <p>Aurora MySQL - <code>audit | error | general | instance | slowquery | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>Aurora PostgreSQL - <code>instance | postgresql | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>error | general | slowquery | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql | upgrade | iam-db-auth-error</code>\n               </p>\n            </li>\n         </ul>\n         <p>For more information about exporting CloudWatch Logs for Amazon RDS, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">\n                Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about exporting CloudWatch Logs for Amazon Aurora, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon Aurora User Guide</i>.</p>"}))
    ModifyDBClusterMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to which you want to upgrade. Changing this\n            parameter results in an outage. The change is applied during the next maintenance window\n            unless <code>ApplyImmediately</code> is enabled.</p>\n         <p>If the cluster that you're modifying has one or more read replicas, all replicas must\n            be running an engine version that's the same or later than the version you\n            specify.</p>\n         <p>To list all of the available engine versions for Aurora MySQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine aurora-mysql --query\n                \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>To list all of the available engine versions for Aurora PostgreSQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine aurora-postgresql --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>To list all of the available engine versions for RDS for MySQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine mysql --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>To list all of the available engine versions for RDS for PostgreSQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine postgres --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:allow_major_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AllowMajorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether major version upgrades are allowed.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>You must allow major version upgrades when specifying a value for the\n                <code>EngineVersion</code> parameter that is a different major version than the DB\n            cluster's current version.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:db_instance_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to apply to all instances of the DB cluster.</p>\n         <note>\n            <p>When you apply a parameter group using the <code>DBInstanceParameterGroupName</code> parameter, the DB\n          cluster isn't rebooted automatically. Also, parameter changes are applied immediately rather than \n             during the next maintenance window.</p>\n         </note>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>\n         <p>Default: The existing name setting</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>The DB parameter group must be in the same DB parameter group family as this DB cluster.</p>\n            </li>\n            <li>\n               <p>The <code>DBInstanceParameterGroupName</code> parameter is valid in combination with the\n              <code>AllowMajorVersionUpgrade</code> parameter for a major version upgrade only.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The Active Directory directory ID to move the DB cluster to.  \n          Specify <code>none</code> to remove the cluster from its current domain.\n          The domain must be created prior to this operation.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/kerberos-authentication.html\">Kerberos Authentication</a>\n            in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM role to use when making API calls to the Directory Service.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingConfiguration, location_name: 'ScalingConfiguration', traits: {"smithy.api#documentation" => "<p>The scaling properties of the DB cluster. You can only modify scaling properties for DB clusters in <code>serverless</code> DB engine mode.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB cluster has deletion protection enabled. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:enable_http_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableHttpEndpoint', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable the HTTP endpoint for an Aurora Serverless v1 DB cluster. By default, the HTTP endpoint \n            isn't enabled.</p>\n         <p>When enabled, the HTTP endpoint provides a connectionless web service API (RDS Data API) for running\n            SQL queries on the Aurora Serverless v1 DB cluster. You can also query your database\n            from inside the RDS console with the RDS query editor.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/data-api.html\">Using RDS Data API</a> in the \n            <i>Amazon Aurora User Guide</i>.</p>\n         <note>\n            <p>This parameter applies only to Aurora Serverless v1 DB clusters. To enable or disable the HTTP endpoint for an Aurora\n        Serverless v2 or provisioned DB cluster, use the <code>EnableHttpEndpoint</code> and <code>DisableHttpEndpoint</code> operations.</p>\n         </note>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the DB cluster to snapshots of the DB cluster. \n            The default is not to copy them.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:enable_global_write_forwarding, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableGlobalWriteForwarding', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable this DB cluster to forward write operations to the primary cluster of a global cluster\n      (Aurora global database). By default, write operations are not allowed on Aurora DB clusters that\n      are secondary clusters in an Aurora global database.</p>\n         <p>You can set this value only on Aurora DB clusters that are members of an Aurora global database. With this parameter\n      enabled, a secondary cluster can forward writes to the current primary cluster, and the resulting changes are replicated back to\n      this cluster. For the primary DB cluster of an Aurora global database, this value is used immediately if the\n        primary is demoted by a global cluster API operation, but it does nothing until then.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:db_cluster_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterInstanceClass', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of each DB instance in the Multi-AZ DB cluster, for example <code>db.m6gd.xlarge</code>.\n            Not all DB instance classes are available in all Amazon Web Services Regions, or for all database engines.</p>\n         <p>For the full list of DB instance classes and availability for your engine, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">\n        DB Instance Class</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The amount of storage in gibibytes (GiB) to allocate to each DB instance in the Multi-AZ DB cluster.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type to associate with the DB cluster.</p>\n         <p>For information on storage types for Aurora DB clusters, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Aurora.Overview.StorageReliability.html#aurora-storage-type\">Storage configurations for Amazon Aurora DB clusters</a>. For information on storage types for Multi-AZ DB\n            clusters, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/create-multi-az-db-cluster.html#create-multi-az-db-cluster-settings\">Settings for creating Multi-AZ DB clusters</a>.</p>\n         <p>When specified for a Multi-AZ DB cluster, a value for the <code>Iops</code> parameter is required.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>Aurora DB clusters - <code>aurora | aurora-iopt1</code>\n               </p>\n            </li>\n            <li>\n               <p>Multi-AZ DB clusters - <code>io1 | io2 | gp3</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default:</p>\n         <ul>\n            <li>\n               <p>Aurora DB clusters - <code>aurora</code>\n               </p>\n            </li>\n            <li>\n               <p>Multi-AZ DB clusters - <code>io1</code>\n               </p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The amount of Provisioned IOPS (input/output operations per second) to be initially allocated \n            for each DB instance in the Multi-AZ DB cluster.</p>\n         <p>For information about valid IOPS values, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_Storage.html#USER_PIOPS\">Amazon RDS Provisioned IOPS storage</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters only</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a multiple between .5 and 50 of the storage amount for the DB cluster.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether minor engine upgrades are applied automatically to the DB cluster during the maintenance window. \n            By default, minor engine upgrades are applied automatically.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    ModifyDBClusterMessage.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are collected for the DB cluster. \n            To turn off collecting Enhanced Monitoring metrics, specify <code>0</code>.</p>\n         <p>If <code>MonitoringRoleArn</code> is specified, also set <code>MonitoringInterval</code>\n            to a value other than <code>0</code>.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters only</p>\n         <p>Valid Values: <code>0 | 1 | 5 | 10 | 15 | 30 | 60</code>\n         </p>\n         <p>Default: <code>0</code>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the IAM role that permits RDS to send Enhanced Monitoring metrics to Amazon CloudWatch Logs. An\n            example is <code>arn:aws:iam:123456789012:role/emaccess</code>. For information on creating a monitoring role,\n            see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Monitoring.html#USER_Monitoring.OS.IAMRole\">To \n                create an IAM role for Amazon RDS Enhanced Monitoring</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>If <code>MonitoringInterval</code> is set to a value other than <code>0</code>, supply a <code>MonitoringRoleArn</code> value.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:database_insights_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseInsightsMode, location_name: 'DatabaseInsightsMode', traits: {"smithy.api#documentation" => "<p>Specifies the mode of Database Insights to enable for the DB cluster.</p>\n         <p>If you change the value from <code>standard</code> to <code>advanced</code>, you must set the \n            <code>PerformanceInsightsEnabled</code> parameter to <code>true</code> and the \n            <code>PerformanceInsightsRetentionPeriod</code> parameter to 465.</p>\n         <p>If you change the value from <code>advanced</code> to <code>standard</code>, you must \n            set the <code>PerformanceInsightsEnabled</code> parameter to <code>false</code>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:enable_performance_insights, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnablePerformanceInsights', traits: {"smithy.api#documentation" => "<p>Specifies whether to turn on Performance Insights for the DB cluster.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PerfInsights.html\">\n            Using Amazon Performance Insights</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>If you don't specify a value for <code>PerformanceInsightsKMSKeyId</code>, then Amazon RDS \n            uses your default KMS key. There is a default KMS key for your Amazon Web Services account. \n            Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:performance_insights_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PerformanceInsightsRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain Performance Insights data.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>7</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <i>month</i> * 31, where <i>month</i> is a number of months from 1-23. \n                Examples: <code>93</code> (3 months * 31), <code>341</code> (11 months * 31), <code>589</code> (19 months * 31)</p>\n            </li>\n            <li>\n               <p>\n                  <code>731</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: <code>7</code> days</p>\n         <p>If you specify a retention period that isn't valid, such as <code>94</code>,  Amazon RDS issues an error.</p>"}))
    ModifyDBClusterMessage.add_member(:serverless_v2_scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2ScalingConfiguration, location_name: 'ServerlessV2ScalingConfiguration'))
    ModifyDBClusterMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB cluster.</p>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB cluster. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon Aurora User Guide.</i>\n         </p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>\n         <p>Valid Values: <code>IPV4 | DUAL</code>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager.</p>\n         <p>If the DB cluster doesn't manage the master user password with Amazon Web Services Secrets Manager, you can turn \n            on this management. In this case, you can't specify <code>MasterUserPassword</code>.</p>\n         <p>If the DB cluster already manages the master user password with Amazon Web Services Secrets Manager, and you specify that the \n            master user password is not managed with Amazon Web Services Secrets Manager, then you must specify <code>MasterUserPassword</code>. \n            In this case, RDS deletes the secret and uses the new password for the master user specified by \n            <code>MasterUserPassword</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide</i> and <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon Aurora User Guide.</i>\n         </p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:rotate_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'RotateMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to rotate the secret managed by Amazon Web Services Secrets Manager for the \n            master user password.</p>\n         <p>This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets \n            Manager for the DB cluster. The secret value contains the updated password.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide</i> and <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon Aurora User Guide.</i>\n         </p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>You must apply the change immediately when rotating the master user password.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and \n            managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if both of the following conditions are met:</p>\n         <ul>\n            <li>\n               <p>The DB cluster doesn't manage the master user password in Amazon Web Services Secrets Manager.</p>\n               <p>If the DB cluster already manages the master user password in Amazon Web Services Secrets\n                    Manager, you can't change the KMS key that is used to encrypt the secret.</p>\n            </li>\n            <li>\n               <p>You are turning on <code>ManageMasterUserPassword</code> to manage the master user password \n                    in Amazon Web Services Secrets Manager.</p>\n               <p>If you are turning on <code>ManageMasterUserPassword</code> and don't specify \n                    <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> \n                    KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't \n                    use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer \n                    managed KMS key.</p>\n            </li>\n         </ul>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.add_member(:engine_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineMode', traits: {"smithy.api#documentation" => "<p>The DB engine mode of the DB cluster, either <code>provisioned</code> or <code>serverless</code>.</p>\n         <note>\n            <p>The DB engine mode can be modified only from <code>serverless</code> to <code>provisioned</code>.</p>\n         </note>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_CreateDBCluster.html\">\n            CreateDBCluster</a>.</p>\n         <p>Valid for Cluster Type: Aurora DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:allow_engine_mode_change, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AllowEngineModeChange', traits: {"smithy.api#documentation" => "<p>Specifies whether engine mode changes from <code>serverless</code> to <code>provisioned</code> \n            are allowed.</p>\n         <p>Valid for Cluster Type: Aurora Serverless v1 DB clusters only</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>You must allow engine mode changes when specifying a different value for the <code>EngineMode</code> parameter\n            from the DB cluster's current engine mode.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:enable_local_write_forwarding, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableLocalWriteForwarding', traits: {"smithy.api#documentation" => "<p>Specifies whether read replicas can forward write operations to the writer DB instance in the DB cluster. By\n            default, write operations aren't allowed on reader DB instances.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    ModifyDBClusterMessage.add_member(:aws_backup_recovery_point_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: AwsBackupRecoveryPointArn, location_name: 'AwsBackupRecoveryPointArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the recovery point in Amazon Web Services Backup.</p>"}))
    ModifyDBClusterMessage.add_member(:enable_limitless_database, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableLimitlessDatabase', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable Aurora Limitless Database. You must enable Aurora Limitless Database to create a DB shard group.</p>\n         <p>Valid for: Aurora DB clusters only</p>\n         <note>\n            <p>This setting is no longer used. Instead use the <code>ClusterScalabilityType</code> setting when you create your Aurora Limitless Database DB cluster.</p>\n         </note>"}))
    ModifyDBClusterMessage.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>The CA certificate identifier to use for the DB cluster's server certificate.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n            instance</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Valid for Cluster Type: Multi-AZ DB clusters</p>"}))
    ModifyDBClusterMessage.type = Types::ModifyDBClusterMessage
    ModifyDBClusterParameterGroupMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB cluster parameter group to modify.</p>", "smithy.api#required" => {}}))
    ModifyDBClusterParameterGroupMessage.add_member(:parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: ParametersList, location_name: 'Parameters', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A list of parameters in the DB cluster parameter group to modify.</p>\n         <p>Valid Values (for the application method): <code>immediate | pending-reboot</code>\n         </p>\n         <note>\n            <p>You can use the <code>immediate</code> value with dynamic parameters only. You can use the \n              <code>pending-reboot</code> value for both dynamic and static parameters.</p>\n            <p>When the application method is <code>immediate</code>, changes to dynamic parameters are applied immediately \n          to the DB clusters associated with the parameter group. When the application method is <code>pending-reboot</code>, \n          changes to dynamic and static parameters are applied after a reboot without failover to the DB clusters associated with the \n          parameter group.</p>\n         </note>", "smithy.api#required" => {}}))
    ModifyDBClusterParameterGroupMessage.type = Types::ModifyDBClusterParameterGroupMessage
    ModifyDBClusterParameterGroupOutput.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB cluster parameter group.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 255 letters or numbers.</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>\n         <note>\n            <p>This value is stored as a lowercase string.</p>\n         </note>"}))
    ModifyDBClusterParameterGroupOutput.type = Types::ModifyDBClusterParameterGroupOutput
    ModifyDBClusterResult.add_member(:db_cluster, Smithy::Schema::Shapes::ShapeRef.new(shape: DBCluster, location_name: 'DBCluster'))
    ModifyDBClusterResult.type = Types::ModifyDBClusterResult
    ModifyDBClusterSnapshotAttributeMessage.add_member(:db_cluster_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterSnapshotIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the DB cluster snapshot to modify the attributes for.</p>", "smithy.api#required" => {}}))
    ModifyDBClusterSnapshotAttributeMessage.add_member(:attribute_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AttributeName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB cluster snapshot attribute to modify.</p>\n         <p>To manage authorization for other Amazon Web Services accounts to copy or restore a manual DB cluster snapshot, \n            set this value to <code>restore</code>.</p>\n         <note>\n            <p>To view the list of attributes available to modify, use the\n                <a>DescribeDBClusterSnapshotAttributes</a> API operation.</p>\n         </note>", "smithy.api#required" => {}}))
    ModifyDBClusterSnapshotAttributeMessage.add_member(:values_to_add, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValueList, location_name: 'ValuesToAdd', traits: {"smithy.api#documentation" => "<p>A list of DB cluster snapshot attributes to add to the attribute specified by <code>AttributeName</code>.</p>\n         <p>To authorize other Amazon Web Services accounts to copy or restore a manual DB cluster snapshot, set this list to include one or more Amazon Web Services account\n            IDs, or <code>all</code> to make the manual DB cluster snapshot restorable by \n            any Amazon Web Services account. Do not add the <code>all</code> value for any\n            manual DB cluster snapshots that contain private information that you don't want available\n            to all Amazon Web Services accounts.</p>"}))
    ModifyDBClusterSnapshotAttributeMessage.add_member(:values_to_remove, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValueList, location_name: 'ValuesToRemove', traits: {"smithy.api#documentation" => "<p>A list of DB cluster snapshot attributes to remove from the attribute specified by <code>AttributeName</code>.</p>\n         <p>To remove authorization for other Amazon Web Services accounts to copy or restore a manual DB cluster snapshot, set this list to include\n            one or more Amazon Web Services account\n            identifiers, or <code>all</code> to remove authorization for any Amazon Web Services account to copy or\n            restore the DB cluster snapshot. If you specify <code>all</code>, an Amazon Web Services account whose account ID is\n            explicitly added to the <code>restore</code> attribute\n            can still copy or restore a manual DB cluster snapshot.</p>"}))
    ModifyDBClusterSnapshotAttributeMessage.type = Types::ModifyDBClusterSnapshotAttributeMessage
    ModifyDBClusterSnapshotAttributeResult.add_member(:db_cluster_snapshot_attributes_result, Smithy::Schema::Shapes::ShapeRef.new(shape: DBClusterSnapshotAttributesResult, location_name: 'DBClusterSnapshotAttributesResult'))
    ModifyDBClusterSnapshotAttributeResult.type = Types::ModifyDBClusterSnapshotAttributeResult
    ModifyDBInstanceMessage.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier of DB instance to modify. This value is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing DB instance.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ModifyDBInstanceMessage.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The new amount of storage in gibibytes (GiB) to allocate for the DB instance.</p>\n         <p>For RDS for Db2, MariaDB, RDS for MySQL, RDS for Oracle, and RDS for PostgreSQL, \n          the value supplied must be at least 10% greater than the current value. \n          Values that are not at least 10% greater than the existing value are rounded up \n          so that they are 10% greater than the current value.</p>\n         <p>For the valid values for allocated storage for each engine,\n          see <code>CreateDBInstance</code>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>When you increase the allocated storage for a DB instance that uses\n                    Provisioned IOPS (<code>gp3</code>, <code>io1</code>, or <code>io2</code>\n                    storage type), you must also specify the <code>Iops</code> parameter. You can\n                    use the current value for <code>Iops</code>.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceClass', traits: {"smithy.api#documentation" => "<p>The new compute and memory capacity of the DB instance, for example <code>db.m4.large</code>. Not all DB instance classes are available in all\n            Amazon Web Services Regions, or for all database engines. For the full list of DB instance classes, and availability for your engine, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">DB Instance Class</a> in the \n                <i>Amazon RDS User Guide</i> or \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Concepts.DBInstanceClass.html\">Aurora\n                DB instance classes</a> in the <i>Amazon Aurora User Guide</i>. For RDS Custom, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-reqs-limits.html#custom-reqs-limits.instances\">DB instance class support for RDS Custom for Oracle</a> and <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-reqs-limits-MS.html#custom-reqs-limits.instancesMS\">\n                DB instance class support for RDS Custom for SQL Server</a>.</p>\n         <p>If you modify the DB instance class, an outage occurs during the change. The change is\n            applied during the next maintenance window, unless you specify\n                <code>ApplyImmediately</code> in your request. </p>\n         <p>Default: Uses existing setting</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If you are modifying the DB instance class and upgrading the engine version at the same time, the currently running engine version must be supported on the \n            specified DB instance class. Otherwise, the operation returns an error. In this case, first run the operation to upgrade the engine version, \n            and then run it again to modify the DB instance class.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>The new DB subnet group for the DB instance.\n          You can use this parameter to move your DB instance to a different VPC.\n      \n    \n          If your DB instance isn't in a VPC, you can also use this parameter to move your DB instance into a VPC.\n          For more information, see \n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html#USER_VPC.Non-VPC2VPC\">Working with a DB instance in a VPC</a> \n          in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Changing the subnet group causes an outage during the change. \n        The change is applied during the next maintenance window,\n        unless you enable <code>ApplyImmediately</code>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match existing DB subnet group.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:db_security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: DBSecurityGroupNameList, location_name: 'DBSecurityGroups', traits: {"smithy.api#documentation" => "<p>A list of DB security groups to authorize on this DB instance. Changing this setting doesn't \n          result in an outage and the change is asynchronously applied as soon as possible.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match existing DB security groups.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of Amazon EC2 VPC security groups to associate with this DB instance. This change is \n          asynchronously applied as soon as possible.</p>\n         <p>This setting doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora (The associated list of EC2 VPC security groups is managed by\n          the DB cluster. For more information, see <code>ModifyDBCluster</code>.)</p>\n            </li>\n            <li>\n               <p>RDS Custom</p>\n            </li>\n         </ul>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match existing VPC security group IDs.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:apply_immediately, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ApplyImmediately', traits: {"smithy.api#documentation" => "<p>Specifies whether the modifications in this request and any pending modifications are asynchronously applied as soon as possible, \n          regardless of the <code>PreferredMaintenanceWindow</code> setting for the DB instance. By default, this parameter is disabled.</p>\n         <p>If this parameter is disabled, changes to the DB instance are applied during the next maintenance window. Some parameter changes can cause an outage\n        and are applied on the next call to <a>RebootDBInstance</a>, or the next failure reboot. Review the table of parameters in \n        <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Overview.DBInstance.Modifying.html\">Modifying a DB Instance</a> in the \n        <i>Amazon RDS User Guide</i> to see the impact of enabling or disabling <code>ApplyImmediately</code> for each modified parameter and to \n        determine when the changes are applied.</p>"}))
    ModifyDBInstanceMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>The new password for the master user.</p>\n         <p>Changing this parameter doesn't result in an outage and the change is asynchronously applied as soon as possible. \n        Between the time of the request and the completion of the request,\n        the <code>MasterUserPassword</code> element exists in the\n          <code>PendingModifiedValues</code> element of the operation response.</p>\n         <note>\n            <p>Amazon RDS API operations never return the password, \n              so this operation provides a way to regain access to a primary instance user if the password is lost. \n              This includes restoring privileges that might have been accidentally revoked.</p>\n         </note>\n         <p>This setting doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora</p>\n               <p>The password for the master user is managed by the DB cluster. For more\n                    information, see <code>ModifyDBCluster</code>.</p>\n            </li>\n            <li>\n               <p>RDS Custom</p>\n            </li>\n            <li>\n               <p>RDS for Oracle CDBs in the multi-tenant configuration</p>\n               <p>Specify the master password in <code>ModifyTenantDatabase</code>\n                    instead.</p>\n            </li>\n         </ul>\n         <p>Default: Uses existing setting</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be specified if <code>ManageMasterUserPassword</code> is turned on.</p>\n            </li>\n            <li>\n               <p>Can include any printable ASCII character except \"/\", \"\"\", or \"@\". For RDS for Oracle, can't include the \"&\" (ampersand) or  the \"'\" (single quotes) character.</p>\n            </li>\n         </ul>\n         <p>Length Constraints:</p>\n         <ul>\n            <li>\n               <p>RDS for Db2 - Must contain from 8 to 255 characters.</p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - Must contain from 8 to 41 characters.</p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - Must contain from 8 to 128 characters.</p>\n            </li>\n            <li>\n               <p>RDS for MySQL - Must contain from 8 to 41 characters.</p>\n            </li>\n            <li>\n               <p>RDS for Oracle - Must contain from 8 to 30 characters.</p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - Must contain from 8 to 128 characters.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to apply to the DB instance.</p>\n         <p>Changing this setting doesn't result in an outage. The parameter group name itself is changed\n          immediately, but the actual parameter changes are not applied until you reboot the\n          instance without failover. In this case, the DB instance isn't rebooted automatically, and the\n          parameter changes aren't applied during the next maintenance window. However, if you modify \n          dynamic parameters in the newly associated DB parameter group, these changes are applied \n          immediately without a reboot.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Default: Uses existing setting</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the same DB parameter group family as the DB instance.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain automated backups. Setting this parameter to a positive number enables backups. Setting this parameter to 0 disables automated backups.</p>\n         <note>\n            <p>Enabling and disabling backups can result in a brief I/O suspension that lasts from a few seconds to a few minutes, depending on the size and class of your DB instance.</p>\n         </note>\n         <p>These changes are applied during the next maintenance window unless the <code>ApplyImmediately</code> parameter is enabled\n            for this request. If you change the parameter from one non-zero value to another non-zero value, the change is asynchronously\n            applied as soon as possible.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The retention period for automated backups is managed by the DB\n            cluster. For more information, see <code>ModifyDBCluster</code>.</p>\n         <p>Default: Uses existing setting</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a value from 0 to 35.</p>\n            </li>\n            <li>\n               <p>Can't be set to 0 if the DB instance is a source to \n              read replicas.</p>\n            </li>\n            <li>\n               <p>Can't be set to 0 for an RDS Custom for Oracle DB instance.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created\n        if automated backups are enabled,\n        as determined by the <code>BackupRetentionPeriod</code> parameter. \n        Changing this parameter doesn't result in an outage and the change is asynchronously applied as soon as possible.\n          The default is a 30-minute window selected at random from an\n          8-hour block of time for each Amazon Web Services Region. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_WorkingWithAutomatedBackups.html#USER_WorkingWithAutomatedBackups.BackupWindow\">Backup window</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. The daily time range for creating automated backups is managed by\n          the DB cluster. For more information, see <code>ModifyDBCluster</code>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur, which\n            might result in an outage. Changing this parameter doesn't result in an outage, except\n            in the following situation, and the change is asynchronously applied as soon as\n            possible. If there are pending actions that cause a reboot, and the maintenance window\n            is changed to include the current time, then changing this parameter causes a reboot\n            of the DB instance. If you change this window to the current time, there must be at least 30\n            minutes between the current time and end of the window to ensure pending changes are\n            applied.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Maintenance.html#Concepts.DBMaintenance\">Amazon RDS Maintenance Window</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Default: Uses existing setting</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>ddd:hh24:mi-ddd:hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>The day values must be <code>mon | tue | wed | thu | fri | sat | sun</code>. </p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred backup window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is a Multi-AZ deployment. Changing this parameter doesn't result \n          in an outage. The change is applied during the next maintenance window unless the <code>ApplyImmediately</code> \n          parameter is enabled for this request.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to upgrade to. \n    Changing this parameter results in an outage and the change \n    is applied during the next maintenance window\n    unless the <code>ApplyImmediately</code> parameter is enabled for this request.</p>\n         <p>For major version upgrades, if a nondefault DB parameter group is currently in use, a\n            new DB parameter group in the DB parameter group family for the new engine version must\n            be specified. The new DB parameter group can be the default for that DB parameter group\n            family.</p>\n         <p>If you specify only a major version, Amazon RDS updates the DB instance to the \n          default minor version if the current minor version is lower.\n          For information about valid engine versions, see <code>CreateDBInstance</code>, \n          or call <code>DescribeDBEngineVersions</code>.</p>\n         <p>If the instance that you're modifying is acting as a read replica, the engine version\n            that you specify must be the same or higher than the version that the source DB instance\n            or cluster is running.</p>\n         <p>In RDS Custom for Oracle, this parameter is supported for read replicas only if they are in the \n          <code>PATCH_DB_FAILURE</code> lifecycle.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If you are upgrading the engine version and modifying the DB instance class at the same time, the currently running engine version must be supported on the \n            specified DB instance class. Otherwise, the operation returns an error. In this case, first run the operation to upgrade the engine version, \n            and then run it again to modify the DB instance class.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:allow_major_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AllowMajorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether major version upgrades are allowed. Changing this parameter doesn't \n          result in an outage and the change is asynchronously applied as soon as possible.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Major version upgrades must be allowed when specifying a value \n          for the <code>EngineVersion</code> parameter that's a different major version than the DB instance's current version.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether minor version upgrades are applied automatically to the DB instance \n          during the maintenance window. An outage occurs when all the following conditions are met:</p>\n         <ul>\n            <li>\n               <p>The automatic upgrade is enabled for the maintenance window.</p>\n            </li>\n            <li>\n               <p>A newer minor version is available.</p>\n            </li>\n            <li>\n               <p>RDS has enabled automatic patching for the engine version.</p>\n            </li>\n         </ul>\n         <p>If any of the preceding conditions isn't met, Amazon RDS applies the change as soon as possible and\n      doesn't cause an outage.</p>\n         <p>For an RDS Custom DB instance, don't enable this setting. Otherwise, the operation returns an error.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    ModifyDBInstanceMessage.add_member(:license_model, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LicenseModel', traits: {"smithy.api#documentation" => "<p>The license model for the DB instance.</p>\n         <p>This setting doesn't apply to Amazon Aurora or RDS Custom DB instances.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>RDS for Db2 - <code>bring-your-own-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - <code>general-public-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - <code>license-included</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>general-public-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Oracle - <code>bring-your-own-license | license-included</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql-license</code>\n               </p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The new Provisioned IOPS (I/O operations per second) value for the RDS instance.</p>\n         <p>Changing this setting doesn't result in an outage and\n            the change is applied during the next maintenance window\n            unless the <code>ApplyImmediately</code> parameter is enabled for this request.\n          If you are migrating from Provisioned IOPS to standard storage, set this value to 0. \n          The DB instance will require a reboot for the change in storage type to take effect.</p>\n         <p>If you choose to migrate your DB instance from using standard storage to Provisioned\n            IOPS (io1), or from Provisioned IOPS to standard storage, the process can take time. The\n            duration of the migration depends on several factors such as database load, storage\n            size, storage type (standard or Provisioned IOPS), amount of IOPS provisioned (if any),\n            and the number of prior scale storage operations. Typical migration times are under 24\n            hours, but the process can take up to several days in some cases. During the migration,\n            the DB instance is available for use, but might experience performance degradation.\n            While the migration takes place, nightly backups for the instance are suspended. No\n            other Amazon RDS operations can take place for the instance, including modifying the\n            instance, rebooting the instance, deleting the instance, creating a read replica for the\n            instance, and creating a DB snapshot of the instance.</p>\n         <p></p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>For RDS for MariaDB, RDS for MySQL, RDS for Oracle, and RDS for PostgreSQL - The value supplied must be at least 10% greater than the current value. \n          Values that are not at least 10% greater than the existing value are rounded up so that they are 10% greater than the current value.</p>\n            </li>\n            <li>\n               <p>When you increase the Provisioned IOPS, you must also specify the\n                        <code>AllocatedStorage</code> parameter. You can use the current value for\n                        <code>AllocatedStorage</code>.</p>\n            </li>\n         </ul>\n         <p>Default: Uses existing setting</p>"}))
    ModifyDBInstanceMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The option group to associate the DB instance with.</p>\n         <p>Changing this parameter doesn't result in an outage, with one exception. If the parameter change results \n          in an option group that enables OEM, it can cause a brief period, lasting less than a second, during which \n          new connections are rejected but existing connections aren't interrupted.</p>\n         <p>The change is applied during the next maintenance window unless the <code>ApplyImmediately</code> parameter \n          is enabled for this request.</p>\n         <p>Permanent options, such as the TDE option for Oracle Advanced Security TDE, can't be removed \n          from an option group, and that option group can't be removed from a DB instance after \n          it is associated with a DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:new_db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NewDBInstanceIdentifier', traits: {"smithy.api#documentation" => "<p>The new identifier for the DB instance when renaming a DB instance. When you change the DB instance \n          identifier, an instance reboot occurs immediately if you enable <code>ApplyImmediately</code>, or will occur \n          during the next maintenance window if you disable <code>ApplyImmediately</code>. This value is stored as a lowercase string.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbinstance</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type to associate with the DB instance.</p>\n         <p>If you specify <code>io1</code>, <code>io2</code>, or <code>gp3</code> \n          you must also include a value for the <code>Iops</code> parameter.</p>\n         <p>If you choose to migrate your DB instance from using standard storage to gp2 (General\n            Purpose SSD), gp3, or Provisioned IOPS (io1), or from these storage types to standard\n            storage, the process can take time. The duration of the migration depends on several\n            factors such as database load, storage size, storage type (standard or Provisioned\n            IOPS), amount of IOPS provisioned (if any), and the number of prior scale storage\n            operations. Typical migration times are under 24 hours, but the process can take up to\n            several days in some cases. During the migration, the DB instance is available for use,\n            but might experience performance degradation. While the migration takes place, nightly\n            backups for the instance are suspended. No other Amazon RDS operations can take place\n            for the instance, including modifying the instance, rebooting the instance, deleting the\n            instance, creating a read replica for the instance, and creating a DB snapshot of the\n            instance.</p>\n         <p>Valid Values: <code>gp2 | gp3 | io1 | io2 | standard</code>\n         </p>\n         <p>Default: <code>io1</code>, if the <code>Iops</code> parameter\n          is specified. Otherwise, <code>gp2</code>.</p>"}))
    ModifyDBInstanceMessage.add_member(:tde_credential_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialArn', traits: {"smithy.api#documentation" => "<p>The ARN from the key store with which to associate the instance for TDE encryption.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:tde_credential_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialPassword', traits: {"smithy.api#documentation" => "<p>The password for the given ARN from the key store in order to access the device.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>The CA certificate identifier to use for the DB instance's server certificate.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n            instance</a> in the <i>Amazon RDS User Guide</i> and \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL.html\">\n            Using SSL/TLS to encrypt a connection to a DB cluster</a> in the <i>Amazon Aurora \n            User Guide</i>.</p>"}))
    ModifyDBInstanceMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The Active Directory directory ID to move the DB instance to.  \n          Specify <code>none</code> to remove the instance from its current domain.\n          You must create the domain before this operation. Currently, you can create only Db2, MySQL, Microsoft SQL \n          Server, Oracle, and PostgreSQL DB instances in an Active Directory Domain.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/kerberos-authentication.html\">\n          Kerberos Authentication</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:domain_fqdn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainFqdn', traits: {"smithy.api#documentation" => "<p>The fully qualified domain name (FQDN) of an Active Directory domain.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mymanagedADtest.mymanagedAD.mydomain</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:domain_ou, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainOu', traits: {"smithy.api#documentation" => "<p>The Active Directory organizational unit for your DB instance to join.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the distinguished name format.</p>\n            </li>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>OU=mymanagedADtestOU,DC=mymanagedADtest,DC=mymanagedAD,DC=mydomain</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:domain_auth_secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainAuthSecretArn', traits: {"smithy.api#documentation" => "<p>The ARN for the Secrets Manager secret with the credentials for the user joining the domain.</p>\n         <p>Example: <code>arn:aws:secretsmanager:region:account-number:secret:myselfmanagedADtestsecret-123456</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:domain_dns_ips, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'DomainDnsIps', traits: {"smithy.api#documentation" => "<p>The IPv4 DNS IP addresses of your primary and secondary Active Directory domain controllers.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Two IP addresses must be provided.  If there isn't a secondary domain controller, use the IP address of the primary domain controller for both entries in the list.</p>\n            </li>\n         </ul>\n         <p>Example: <code>123.124.125.126,234.235.236.237</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the DB instance to snapshots of the DB instance. By default, tags aren't copied.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. Copying tags to snapshots is managed by the DB cluster. Setting this\n          value for an Aurora DB instance has no effect on the DB cluster setting. For more\n          information, see <code>ModifyDBCluster</code>.</p>"}))
    ModifyDBInstanceMessage.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are collected for \n          the DB instance. To disable collection of Enhanced Monitoring metrics, specify <code>0</code>.</p>\n         <p>If <code>MonitoringRoleArn</code> is specified, set <code>MonitoringInterval</code>\n        to a value other than <code>0</code>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Valid Values: <code>0 | 1 | 5 | 10 | 15 | 30 | 60</code>\n         </p>\n         <p>Default: <code>0</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:db_port_number, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'DBPortNumber', traits: {"smithy.api#documentation" => "<p>The port number on which the database accepts connections.</p>\n         <p>The value of the <code>DBPortNumber</code> parameter must not match any of the port values \n          specified for options in the option group for the DB instance.</p>\n         <p>If you change the <code>DBPortNumber</code> value, your database restarts regardless of \n          the value of the <code>ApplyImmediately</code> parameter.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Valid Values: <code>1150-65535</code>\n         </p>\n         <p>Default:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora - <code>3306</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Db2 - <code>50000</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - <code>3306</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - <code>1433</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>3306</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Oracle - <code>1521</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>5432</code>\n               </p>\n            </li>\n         </ul>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>For RDS for Microsoft SQL Server, the value can't be <code>1234</code>, <code>1434</code>,\n                <code>3260</code>, <code>3343</code>, <code>3389</code>, <code>47001</code>, or\n                <code>49152-49156</code>.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is publicly accessible.</p>\n         <p>When the DB instance is publicly accessible and you connect from outside of the DB instance's virtual private cloud (VPC), \n              its Domain Name System (DNS) endpoint resolves to the public IP address. When you connect from within the same VPC as the DB instance, \n              the endpoint resolves to the private IP address. Access to the DB instance is ultimately controlled by the security group it uses. That public\n              access isn't permitted if the security group assigned to the DB instance doesn't permit it.</p>\n         <p>When the DB instance isn't publicly accessible, it is an internal DB instance with a DNS name that resolves to a private IP address.</p>\n         <p>\n            <code>PubliclyAccessible</code> only applies to DB instances in a VPC. The DB instance must be part of a \n          public subnet and <code>PubliclyAccessible</code> must be enabled for it to be publicly accessible.</p>\n         <p>Changes to the <code>PubliclyAccessible</code> parameter are applied immediately regardless\n      of the value of the <code>ApplyImmediately</code> parameter.</p>"}))
    ModifyDBInstanceMessage.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN for the IAM role that permits RDS to send enhanced monitoring metrics to Amazon CloudWatch Logs. For\n      example, <code>arn:aws:iam:123456789012:role/emaccess</code>. For information on creating a monitoring role,\n      see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Monitoring.html#USER_Monitoring.OS.IAMRole\">To \n          create an IAM role for Amazon RDS Enhanced Monitoring</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>If <code>MonitoringInterval</code> is set to a value other than <code>0</code>, supply a <code>MonitoringRoleArn</code> \n          value.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM role to use when making API calls to the Directory Service.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:disable_domain, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DisableDomain', traits: {"smithy.api#documentation" => "<p>Specifies whether to remove the DB instance from the Active Directory domain.</p>"}))
    ModifyDBInstanceMessage.add_member(:promotion_tier, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PromotionTier', traits: {"smithy.api#documentation" => "<p>The order of priority in which an Aurora Replica is promoted to the primary instance \n          after a failure of the existing primary instance. For more information, \n      see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Concepts.AuroraHighAvailability.html#Aurora.Managing.FaultTolerance\">\n          Fault Tolerance for an Aurora DB Cluster</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Default: <code>1</code>\n         </p>\n         <p>Valid Values: <code>0 - 15</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access Management\n            (IAM) accounts to database accounts. By default, mapping isn't enabled.</p>\n         <p>This setting doesn't apply to Amazon Aurora. Mapping Amazon Web Services IAM accounts to database accounts is managed by the DB\n          cluster.</p>\n         <p>For more information about IAM database authentication, see \n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\">\n              IAM Database Authentication for MySQL and PostgreSQL</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:database_insights_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseInsightsMode, location_name: 'DatabaseInsightsMode', traits: {"smithy.api#documentation" => "<p>Specifies the mode of Database Insights to enable for the DB instance.</p>\n         <note>\n            <p>Aurora DB instances inherit this value from the DB cluster, so you can't change this value.</p>\n         </note>"}))
    ModifyDBInstanceMessage.add_member(:enable_performance_insights, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnablePerformanceInsights', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable Performance Insights for the DB instance.</p>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PerfInsights.html\">Using Amazon Performance Insights</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>If you don't specify a value for <code>PerformanceInsightsKMSKeyId</code>, then Amazon RDS \n            uses your default KMS key. There is a default KMS key for your Amazon Web Services account. \n            Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:performance_insights_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PerformanceInsightsRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain Performance Insights data.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>7</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <i>month</i> * 31, where <i>month</i> is a number of months from 1-23. \n                Examples: <code>93</code> (3 months * 31), <code>341</code> (11 months * 31), <code>589</code> (19 months * 31)</p>\n            </li>\n            <li>\n               <p>\n                  <code>731</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: <code>7</code> days</p>\n         <p>If you specify a retention period that isn't valid, such as <code>94</code>,  Amazon RDS returns an error.</p>"}))
    ModifyDBInstanceMessage.add_member(:cloudwatch_logs_export_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CloudwatchLogsExportConfiguration, location_name: 'CloudwatchLogsExportConfiguration', traits: {"smithy.api#documentation" => "<p>The log types to be enabled for export to CloudWatch Logs for a \n            specific DB instance.</p>\n         <p>A change to the <code>CloudwatchLogsExportConfiguration</code> parameter is always applied to the DB instance \n            immediately. Therefore, the <code>ApplyImmediately</code> parameter has no effect.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>The following values are valid for each DB engine:</p>\n         <ul>\n            <li>\n               <p>Aurora MySQL - <code>audit | error | general | slowquery | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>Aurora PostgreSQL - <code>postgresql | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>error | general | slowquery | iam-db-auth-error</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql | upgrade | iam-db-auth-error</code>\n               </p>\n            </li>\n         </ul>\n         <p>For more information about exporting CloudWatch Logs for Amazon RDS, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">\n            Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about exporting CloudWatch Logs for Amazon Aurora, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon Aurora User Guide</i>.</p>"}))
    ModifyDBInstanceMessage.add_member(:processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessorFeatureList, location_name: 'ProcessorFeatures', traits: {"smithy.api#documentation" => "<p>The number of CPU cores and the number of threads per core for the DB instance class of the DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:use_default_processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseDefaultProcessorFeatures', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance class of the DB instance uses its default\n            processor features.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance has deletion protection enabled. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_DeleteInstance.html\">\n                Deleting a DB Instance</a>.</p>\n         <p>This setting doesn't apply to Amazon Aurora DB instances. You can enable or disable deletion protection for the DB cluster. \n        For more information, see <code>ModifyDBCluster</code>. DB instances in a DB cluster can be deleted even when deletion protection is enabled for the DB cluster.</p>"}))
    ModifyDBInstanceMessage.add_member(:max_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxAllocatedStorage', traits: {"smithy.api#documentation" => "<p>The upper limit in gibibytes (GiB) to which Amazon RDS can automatically scale the storage of the DB instance.</p>\n         <p>For more information about this setting, including limitations that apply to it, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PIOPS.StorageTypes.html#USER_PIOPS.Autoscaling\">\n                Managing capacity automatically with Amazon RDS storage autoscaling</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:certificate_rotation_restart, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CertificateRotationRestart', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is restarted when you rotate your \n            SSL/TLS certificate.</p>\n         <p>By default, the DB instance is restarted when you rotate your SSL/TLS certificate. The certificate \n            is not updated until the DB instance is restarted.</p>\n         <important>\n            <p>Set this parameter only if you are <i>not</i> using SSL/TLS to connect to the DB instance.</p>\n         </important>\n         <p>If you are using SSL/TLS to connect to the DB instance, follow the appropriate instructions for your \n            DB engine to rotate your SSL/TLS certificate:</p>\n         <ul>\n            <li>\n               <p>For more information about rotating your SSL/TLS certificate for RDS DB engines, see \n                    <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL-certificate-rotation.html\">\n                        Rotating Your SSL/TLS Certificate.</a> in the <i>Amazon RDS User Guide.</i>\n               </p>\n            </li>\n            <li>\n               <p>For more information about rotating your SSL/TLS certificate for Aurora DB engines, see \n                    <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL-certificate-rotation.html\">\n                        Rotating Your SSL/TLS Certificate</a> in the <i>Amazon Aurora User Guide</i>.</p>\n            </li>\n         </ul>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:replica_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ReplicaMode, location_name: 'ReplicaMode', traits: {"smithy.api#documentation" => "<p>The open mode of a replica database.</p>\n         <note>\n            <p>This parameter is only supported for Db2 DB instances and Oracle DB\n                instances.</p>\n         </note>\n         <dl>\n            <dt>Db2</dt>\n            <dd>\n               <p>Standby DB replicas are included in Db2 Advanced Edition (AE) and Db2\n                        Standard Edition (SE). The main use case for standby replicas is\n                        cross-Region disaster recovery. Because it doesn't accept user\n                        connections, a standby replica can't serve a read-only workload.</p>\n               <p>You can create a combination of standby and read-only DB replicas for the\n                        same primary DB instance. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/db2-replication.html\">Working with read\n                            replicas for Amazon RDS for Db2</a> in the <i>Amazon RDS User\n                                Guide</i>.</p>\n               <p>To create standby DB replicas for RDS for Db2, set this parameter to\n                        <code>mounted</code>.</p>\n            </dd>\n            <dt>Oracle</dt>\n            <dd>\n               <p>Mounted DB replicas are included in Oracle Database Enterprise Edition. The main use case for\n                        mounted replicas is cross-Region disaster recovery. The primary database doesn't use Active\n                        Data Guard to transmit information to the mounted replica. Because it doesn't accept\n                        user connections, a mounted replica can't serve a read-only workload.</p>\n               <p>You can create a combination of mounted and read-only DB replicas for the\n                        same primary DB instance. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/oracle-read-replicas.html\">Working with\n                            read replicas for Amazon RDS for Oracle</a> in the <i>Amazon\n                            RDS User Guide</i>.</p>\n               <p>For RDS Custom, you must specify this parameter and set it to\n                            <code>mounted</code>. The value won't be set by default. After replica\n                        creation, you can manage the open mode manually.</p>\n            </dd>\n         </dl>"}))
    ModifyDBInstanceMessage.add_member(:enable_customer_owned_ip, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableCustomerOwnedIp', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable a customer-owned IP address (CoIP) for an RDS on Outposts DB instance.</p>\n         <p>A <i>CoIP</i> provides local or external connectivity to resources in\n            your Outpost subnets through your on-premises network. For some use cases, a CoIP can\n            provide lower latency for connections to the DB instance from outside of its virtual\n            private cloud (VPC) on your local network.</p>\n         <p>For more information about RDS on Outposts, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-on-outposts.html\">Working with Amazon RDS on Amazon Web Services Outposts</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about CoIPs, see <a href=\"https://docs.aws.amazon.com/outposts/latest/userguide/routing.html#ip-addressing\">Customer-owned IP addresses</a> \n            in the <i>Amazon Web Services Outposts User Guide</i>.</p>"}))
    ModifyDBInstanceMessage.add_member(:aws_backup_recovery_point_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: AwsBackupRecoveryPointArn, location_name: 'AwsBackupRecoveryPointArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the recovery point in Amazon Web Services Backup.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:automation_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomationMode, location_name: 'AutomationMode', traits: {"smithy.api#documentation" => "<p>The automation mode of the RDS Custom DB instance. \n            If <code>full</code>, the DB instance automates monitoring and instance recovery. If \n            <code>all paused</code>, the instance pauses automation for the duration set by \n            <code>ResumeFullAutomationModeMinutes</code>.</p>"}))
    ModifyDBInstanceMessage.add_member(:resume_full_automation_mode_minutes, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ResumeFullAutomationModeMinutes', traits: {"smithy.api#documentation" => "<p>The number of minutes to pause the automation. When the time period ends, RDS Custom resumes \n            full automation.</p>\n         <p>Default: <code>60</code>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be at least 60.</p>\n            </li>\n            <li>\n               <p>Must be no more than 1,440.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB instance.</p>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB instance. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Valid Values: <code>IPV4 | DUAL</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'StorageThroughput', traits: {"smithy.api#documentation" => "<p>The storage throughput value for the DB instance.</p>\n         <p>This setting applies only to the <code>gp3</code> storage type.</p>\n         <p>This setting doesn't apply to Amazon Aurora or RDS Custom DB instances.</p>"}))
    ModifyDBInstanceMessage.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager.</p>\n         <p>If the DB instance doesn't manage the master user password with Amazon Web Services Secrets Manager, you can turn \n            on this management. In this case, you can't specify <code>MasterUserPassword</code>.</p>\n         <p>If the DB instance already manages the master user password with Amazon Web Services Secrets Manager, and you specify that the \n            master user password is not managed with Amazon Web Services Secrets Manager, then you must specify <code>MasterUserPassword</code>. \n            In this case, Amazon RDS deletes the secret and uses the new password for the master user specified by \n            <code>MasterUserPassword</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't manage the master user password with Amazon Web Services Secrets Manager if <code>MasterUserPassword</code> \n                    is specified.</p>\n            </li>\n            <li>\n               <p>Can't specify for RDS for Oracle CDB instances in the multi-tenant\n                    configuration. Use <code>ModifyTenantDatabase</code> instead.</p>\n            </li>\n            <li>\n               <p>Can't specify the parameters <code>ManageMasterUserPassword</code> and\n                        <code>MultiTenant</code> in the same operation.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:rotate_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'RotateMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to rotate the secret managed by Amazon Web Services Secrets Manager for the \n            master user password.</p>\n         <p>This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets \n            Manager for the DB instance. The secret value contains the updated password.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>You must apply the change immediately when rotating the master user password.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and \n            managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if both of the following conditions are met:</p>\n         <ul>\n            <li>\n               <p>The DB instance doesn't manage the master user password in Amazon Web Services Secrets Manager.</p>\n               <p>If the DB instance already manages the master user password in Amazon Web Services Secrets Manager, \n                    you can't change the KMS key used to encrypt the secret.</p>\n            </li>\n            <li>\n               <p>You are turning on <code>ManageMasterUserPassword</code> to manage the master user password \n                    in Amazon Web Services Secrets Manager.</p>\n               <p>If you are turning on <code>ManageMasterUserPassword</code> and don't specify \n                    <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> \n                    KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't \n                    use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer \n                    managed KMS key.</p>\n            </li>\n         </ul>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>"}))
    ModifyDBInstanceMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The target Oracle DB engine when you convert a non-CDB to a CDB. This intermediate step is necessary to upgrade an Oracle Database 19c non-CDB\n           to an Oracle Database 21c CDB.</p>\n         <p>Note the following requirements:</p>\n         <ul>\n            <li>\n               <p>Make sure that you specify <code>oracle-ee-cdb</code> or <code>oracle-se2-cdb</code>.</p>\n            </li>\n            <li>\n               <p>Make sure that your DB engine runs Oracle Database 19c with an April 2021 or later RU.</p>\n            </li>\n         </ul>\n         <p>Note the following limitations:</p>\n         <ul>\n            <li>\n               <p>You can't convert a CDB to a non-CDB.</p>\n            </li>\n            <li>\n               <p>You can't convert a replica database.</p>\n            </li>\n            <li>\n               <p>You can't convert a non-CDB to a CDB and upgrade the engine version in the\n                   same command.</p>\n            </li>\n            <li>\n               <p>You can't convert the existing custom parameter or option group when it has\n                   options or parameters that are permanent or persistent. In this situation, the\n                   DB instance reverts to the default option and parameter group. To avoid\n                   reverting to the default, specify a new parameter group with\n                       <code>--db-parameter-group-name</code> and a new option group with\n                       <code>--option-group-name</code>.</p>\n            </li>\n         </ul>"}))
    ModifyDBInstanceMessage.add_member(:dedicated_log_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DedicatedLogVolume', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB instance has a dedicated log volume (DLV) enabled.</p>"}))
    ModifyDBInstanceMessage.add_member(:multi_tenant, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiTenant', traits: {"smithy.api#documentation" => "<p>Specifies whether the to convert your DB instance from the single-tenant conﬁguration\n            to the multi-tenant conﬁguration. This parameter is supported only for RDS for Oracle\n            CDB instances.</p>\n         <p>During the conversion, RDS creates an initial tenant database and associates the DB\n            name, master user name, character set, and national character set metadata with this\n            database. The tags associated with the instance also propagate to the initial tenant\n            database. You can add more tenant databases to your DB instance by using the\n                <code>CreateTenantDatabase</code> operation.</p>\n         <important>\n            <p>The conversion to the multi-tenant configuration is permanent and irreversible, so\n                you can't later convert back to the single-tenant configuration. When you specify\n                this parameter, you must also specify <code>ApplyImmediately</code>.</p>\n         </important>"}))
    ModifyDBInstanceMessage.type = Types::ModifyDBInstanceMessage
    ModifyDBInstanceResult.add_member(:db_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: DBInstance, location_name: 'DBInstance'))
    ModifyDBInstanceResult.type = Types::ModifyDBInstanceResult
    ModifyDBParameterGroupMessage.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB parameter group.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the name of an existing <code>DBParameterGroup</code>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ModifyDBParameterGroupMessage.add_member(:parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: ParametersList, location_name: 'Parameters', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>An array of parameter names, values, and the application methods for the parameter update. At least one parameter name, value, and \n          application method must be supplied; later arguments are optional. A maximum of 20 parameters can be modified in a single request.</p>\n         <p>Valid Values (for the application method): <code>immediate | pending-reboot</code>\n         </p>\n         <p>You can use the <code>immediate</code> value with dynamic parameters only. You can use the <code>pending-reboot</code> value for both dynamic \n          and static parameters.</p>\n         <p>When the application method is <code>immediate</code>, changes to dynamic parameters are applied immediately to the DB instances associated with \n          the parameter group.</p>\n         <p>When the application method is <code>pending-reboot</code>, changes to dynamic and static parameters are applied after a reboot without failover \n          to the DB instances associated with the parameter group.</p>\n         <note>\n            <p>You can't use <code>pending-reboot</code> with dynamic parameters on RDS for SQL Server DB instances. Use <code>immediate</code>.</p>\n         </note>\n         <p>For more information on modifying DB parameters, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_WorkingWithParamGroups.html\">Working \n          with DB parameter groups</a> in the <i>Amazon RDS User Guide</i>.</p>", "smithy.api#required" => {}}))
    ModifyDBParameterGroupMessage.type = Types::ModifyDBParameterGroupMessage
    ModifyDBParameterGroupOutput.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group.</p>"}))
    ModifyDBParameterGroupOutput.type = Types::ModifyDBParameterGroupOutput
    ModifyDBProxyEndpointRequest.add_member(:db_proxy_endpoint_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DBProxyEndpointName, location_name: 'DBProxyEndpointName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB proxy sociated with the DB proxy endpoint that you want to modify.</p>", "smithy.api#required" => {}}))
    ModifyDBProxyEndpointRequest.add_member(:new_db_proxy_endpoint_name, Smithy::Schema::Shapes::ShapeRef.new(shape: DBProxyEndpointName, location_name: 'NewDBProxyEndpointName', traits: {"smithy.api#documentation" => "<p>The new identifier for the <code>DBProxyEndpoint</code>. An identifier must\n        begin with a letter and must contain only ASCII letters, digits, and hyphens; it\n        can't end with a hyphen or contain two consecutive hyphens.</p>"}))
    ModifyDBProxyEndpointRequest.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>The VPC security group IDs for the DB proxy endpoint. When the DB proxy endpoint\n        uses a different VPC than the original proxy, you also specify a different\n        set of security group IDs than for the original proxy.</p>"}))
    ModifyDBProxyEndpointRequest.type = Types::ModifyDBProxyEndpointRequest
    ModifyDBProxyEndpointResponse.add_member(:db_proxy_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: DBProxyEndpoint, location_name: 'DBProxyEndpoint', traits: {"smithy.api#documentation" => "<p>The <code>DBProxyEndpoint</code> object representing the new settings for the DB proxy endpoint.</p>"}))
    ModifyDBProxyEndpointResponse.type = Types::ModifyDBProxyEndpointResponse
    ModifyDBProxyRequest.add_member(:db_proxy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBProxyName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the <code>DBProxy</code> to modify.</p>", "smithy.api#required" => {}}))
    ModifyDBProxyRequest.add_member(:new_db_proxy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NewDBProxyName', traits: {"smithy.api#documentation" => "<p>The new identifier for the <code>DBProxy</code>. An identifier must begin with a letter and must contain only ASCII letters, digits, and hyphens; it can't end with a hyphen or contain two consecutive hyphens.</p>"}))
    ModifyDBProxyRequest.add_member(:auth, Smithy::Schema::Shapes::ShapeRef.new(shape: UserAuthConfigList, location_name: 'Auth', traits: {"smithy.api#documentation" => "<p>The new authentication settings for the <code>DBProxy</code>.</p>"}))
    ModifyDBProxyRequest.add_member(:require_tls, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'RequireTLS', traits: {"smithy.api#documentation" => "<p>Whether Transport Layer Security (TLS) encryption is required for connections to the proxy.\n        By enabling this setting, you can enforce encrypted TLS connections to the proxy, even if the associated database doesn't\n        use TLS.</p>"}))
    ModifyDBProxyRequest.add_member(:idle_client_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'IdleClientTimeout', traits: {"smithy.api#documentation" => "<p>The number of seconds that a connection to the proxy can be inactive before the proxy disconnects it. You can set this\n        value higher or lower than the connection timeout limit for the associated database.</p>"}))
    ModifyDBProxyRequest.add_member(:debug_logging, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DebugLogging', traits: {"smithy.api#documentation" => "<p>Whether the proxy includes detailed information about SQL statements in its logs.\n        This information helps you to debug issues involving SQL behavior or the performance\n        and scalability of the proxy connections. The debug information includes the text of\n        SQL statements that you submit through the proxy. Thus, only enable this setting\n        when needed for debugging, and only when you have security measures in place to\n        safeguard any sensitive information that appears in the logs.</p>"}))
    ModifyDBProxyRequest.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'RoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the IAM role that the proxy uses to access secrets in Amazon Web Services Secrets Manager.</p>"}))
    ModifyDBProxyRequest.add_member(:security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'SecurityGroups', traits: {"smithy.api#documentation" => "<p>The new list of security groups for the <code>DBProxy</code>.</p>"}))
