    ModifyDBShardGroupMessage.add_member(:max_acu, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MaxACU', traits: {"smithy.api#documentation" => "<p>The maximum capacity of the DB shard group in Aurora capacity units (ACUs).</p>"}))
    ModifyDBShardGroupMessage.add_member(:min_acu, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MinACU', traits: {"smithy.api#documentation" => "<p>The minimum capacity of the DB shard group in Aurora capacity units (ACUs).</p>"}))
    ModifyDBShardGroupMessage.add_member(:compute_redundancy, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ComputeRedundancy', traits: {"smithy.api#documentation" => "<p>Specifies whether to create standby DB shard groups for the DB shard group. Valid values are the following:</p>\n         <ul>\n            <li>\n               <p>0 - Creates a DB shard group without a standby DB shard group. This is the default value.</p>\n            </li>\n            <li>\n               <p>1 - Creates a DB shard group with a standby DB shard group in a different Availability Zone (AZ).</p>\n            </li>\n            <li>\n               <p>2 - Creates a DB shard group with two standby DB shard groups in two different AZs.</p>\n            </li>\n         </ul>"}))
    ModifyDBShardGroupMessage.type = Types::ModifyDBShardGroupMessage
    ModifyDBShardGroupOutput.add_member(:db_shard_group_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBShardGroupResourceId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services Region-unique, immutable identifier for the DB shard group.</p>"}))
    ModifyDBShardGroupOutput.add_member(:db_shard_group_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: DBShardGroupIdentifier, location_name: 'DBShardGroupIdentifier', traits: {"smithy.api#documentation" => "<p>The name of the DB shard group.</p>"}))
    ModifyDBShardGroupOutput.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The name of the primary DB cluster for the DB shard group.</p>"}))
    ModifyDBShardGroupOutput.add_member(:max_acu, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MaxACU', traits: {"smithy.api#documentation" => "<p>The maximum capacity of the DB shard group in Aurora capacity units (ACUs).</p>"}))
    ModifyDBShardGroupOutput.add_member(:min_acu, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MinACU', traits: {"smithy.api#documentation" => "<p>The minimum capacity of the DB shard group in Aurora capacity units (ACUs).</p>"}))
    ModifyDBShardGroupOutput.add_member(:compute_redundancy, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'ComputeRedundancy', traits: {"smithy.api#documentation" => "<p>Specifies whether to create standby DB shard groups for the DB shard group. Valid values are the following:</p>\n         <ul>\n            <li>\n               <p>0 - Creates a DB shard group without a standby DB shard group. This is the default value.</p>\n            </li>\n            <li>\n               <p>1 - Creates a DB shard group with a standby DB shard group in a different Availability Zone (AZ).</p>\n            </li>\n            <li>\n               <p>2 - Creates a DB shard group with two standby DB shard groups in two different AZs.</p>\n            </li>\n         </ul>"}))
    ModifyDBShardGroupOutput.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the DB shard group.</p>"}))
    ModifyDBShardGroupOutput.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Indicates whether the DB shard group is publicly accessible.</p>\n         <p>When the DB shard group is publicly accessible, its Domain Name System (DNS) endpoint\n            resolves to the private IP address from within the DB shard group's virtual private cloud\n            (VPC). It resolves to the public IP address from outside of the DB shard group's VPC. Access\n            to the DB shard group is ultimately controlled by the security group it uses. That public\n            access isn't permitted if the security group assigned to the DB shard group doesn't permit\n            it.</p>\n         <p>When the DB shard group isn't publicly accessible, it is an internal DB shard group with a DNS name that resolves to a private IP address.</p>\n         <p>For more information, see <a>CreateDBShardGroup</a>.</p>\n         <p>This setting is only for Aurora Limitless Database.</p>"}))
    ModifyDBShardGroupOutput.add_member(:endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Endpoint', traits: {"smithy.api#documentation" => "<p>The connection endpoint for the DB shard group.</p>"}))
    ModifyDBShardGroupOutput.add_member(:db_shard_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBShardGroupArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the DB shard group.</p>"}))
    ModifyDBShardGroupOutput.add_member(:tag_list, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'TagList'))
    ModifyDBShardGroupOutput.type = Types::ModifyDBShardGroupOutput
    ModifyDBSnapshotAttributeMessage.add_member(:db_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSnapshotIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the DB snapshot to modify the attributes for.</p>", "smithy.api#required" => {}}))
    ModifyDBSnapshotAttributeMessage.add_member(:attribute_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AttributeName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB snapshot attribute to modify.</p>\n         <p>To manage authorization for other Amazon Web Services accounts to copy or restore a manual DB snapshot, \n      set this value to <code>restore</code>.</p>\n         <note>\n            <p>To view the list of attributes available to modify, use the\n              <a>DescribeDBSnapshotAttributes</a> API operation.</p>\n         </note>", "smithy.api#required" => {}}))
    ModifyDBSnapshotAttributeMessage.add_member(:values_to_add, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValueList, location_name: 'ValuesToAdd', traits: {"smithy.api#documentation" => "<p>A list of DB snapshot attributes to add to the attribute specified by <code>AttributeName</code>.</p>\n         <p>To authorize other Amazon Web Services accounts to copy or restore a manual snapshot, set this list to include one or more Amazon Web Services account\n      IDs, or <code>all</code> to make the manual DB snapshot restorable by \n      any Amazon Web Services account. Do not add the <code>all</code> value for any\n      manual DB snapshots that contain private information that you don't want available\n      to all Amazon Web Services accounts.</p>"}))
    ModifyDBSnapshotAttributeMessage.add_member(:values_to_remove, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValueList, location_name: 'ValuesToRemove', traits: {"smithy.api#documentation" => "<p>A list of DB snapshot attributes to remove from the attribute specified by <code>AttributeName</code>.</p>\n         <p>To remove authorization for other Amazon Web Services accounts to copy or restore a manual snapshot, set this list to include \n      one or more Amazon Web Services account\n      identifiers, or <code>all</code> to remove authorization for any Amazon Web Services account to copy or\n      restore the DB snapshot. If you specify <code>all</code>, an Amazon Web Services account whose\n      account ID is explicitly added to the <code>restore</code> attribute\n      can still copy or restore the manual DB snapshot.</p>"}))
    ModifyDBSnapshotAttributeMessage.type = Types::ModifyDBSnapshotAttributeMessage
    ModifyDBSnapshotAttributeResult.add_member(:db_snapshot_attributes_result, Smithy::Schema::Shapes::ShapeRef.new(shape: DBSnapshotAttributesResult, location_name: 'DBSnapshotAttributesResult'))
