    ModifyEventSubscriptionMessage.add_member(:subscription_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SubscriptionName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the RDS event notification subscription.</p>", "smithy.api#required" => {}}))
    ModifyEventSubscriptionMessage.add_member(:sns_topic_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnsTopicArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the SNS topic created for event notification. The ARN is created by Amazon SNS when you create a topic and subscribe to it.</p>"}))
    ModifyEventSubscriptionMessage.add_member(:source_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceType', traits: {"smithy.api#documentation" => "<p>The type of source that is generating the events. For example, if you want to be notified of events generated by a DB instance, you would set this parameter to db-instance. For RDS Proxy events, specify <code>db-proxy</code>. If this value isn't specified, all events are returned.</p>\n         <p>Valid Values:<code> db-instance | db-cluster | db-parameter-group | db-security-group | db-snapshot | db-cluster-snapshot | db-proxy | zero-etl | custom-engine-version | blue-green-deployment </code>\n         </p>"}))
    ModifyEventSubscriptionMessage.add_member(:event_categories, Smithy::Schema::Shapes::ShapeRef.new(shape: EventCategoriesList, location_name: 'EventCategories', traits: {"smithy.api#documentation" => "<p>A list of event categories for a source type (<code>SourceType</code>) that you want to subscribe to. \n            You can see a list of the categories for a given source type \n            in <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Events.html\">Events</a> in the <i>Amazon RDS User Guide</i> \n            or by using the <code>DescribeEventCategories</code> operation.</p>"}))
