    ModifyGlobalClusterMessage.add_member(:global_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'GlobalClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The cluster identifier for the global cluster to modify. This parameter isn't case-sensitive.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing global database cluster.</p>\n            </li>\n         </ul>"}))
    ModifyGlobalClusterMessage.add_member(:new_global_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NewGlobalClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The new cluster identifier for the global database cluster.\n        This value is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster2</code>\n         </p>"}))
    ModifyGlobalClusterMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable deletion protection for the global database cluster. The global database cluster\n        can't be deleted when deletion protection is enabled.</p>"}))
    ModifyGlobalClusterMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to which you want to upgrade. \n          </p>\n         <p>To list all of the available engine versions for <code>aurora-mysql</code> (for MySQL-based Aurora global databases), use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine aurora-mysql --query '*[]|[?SupportsGlobalDatabases == `true`].[EngineVersion]'</code>\n         </p>\n         <p>To list all of the available engine versions for <code>aurora-postgresql</code> (for PostgreSQL-based Aurora global databases), use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine aurora-postgresql --query '*[]|[?SupportsGlobalDatabases == `true`].[EngineVersion]'</code>\n         </p>"}))
    ModifyGlobalClusterMessage.add_member(:allow_major_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AllowMajorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether to allow major version upgrades.</p>\n         <p>Constraints: Must be enabled if you specify a value for the\n                <code>EngineVersion</code> parameter that's a different major version than the global\n            cluster's current version.</p>\n         <p>If you upgrade the major version of a global database, the cluster and DB instance parameter\n        groups are set to the default parameter groups for the new version. Apply any custom parameter\n        groups after completing the upgrade.</p>"}))
    ModifyGlobalClusterMessage.type = Types::ModifyGlobalClusterMessage
