    PendingModifiedValues.add_member(:automation_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: AutomationMode, location_name: 'AutomationMode', traits: {"smithy.api#documentation" => "<p>The automation mode of the RDS Custom DB instance: <code>full</code> or <code>all-paused</code>. \n            If <code>full</code>, the DB instance automates monitoring and instance recovery. If \n            <code>all-paused</code>, the instance pauses automation for the duration set by \n            <code>--resume-full-automation-mode-minutes</code>.</p>"}))
