    RestoreDBClusterFromS3Message.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of EC2 VPC security groups to associate with the restored DB cluster.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>A DB subnet group to associate with the restored DB cluster.</p>\n         <p>Constraints: If supplied, must match the name of an existing DBSubnetGroup.</p>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>"}))
    RestoreDBClusterFromS3Message.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the database engine to be used for this DB cluster.</p>\n         <p>Valid Values: <code>aurora-mysql</code> (for Aurora MySQL)</p>", "smithy.api#required" => {}}))
    RestoreDBClusterFromS3Message.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to use.</p>\n         <p>To list all of the available engine versions for <code>aurora-mysql</code> (Aurora MySQL), use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine aurora-mysql --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>\n            <b>Aurora MySQL</b>\n         </p>\n         <p>Examples: <code>5.7.mysql_aurora.2.12.0</code>, <code>8.0.mysql_aurora.3.04.0</code>\n         </p>"}))
    RestoreDBClusterFromS3Message.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the instances in the restored DB cluster accept connections.</p>\n         <p>Default: <code>3306</code>\n         </p>"}))
    RestoreDBClusterFromS3Message.add_member(:master_username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUsername', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the master user for the restored DB cluster.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 16 letters or numbers.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't be a reserved word for the chosen database engine.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    RestoreDBClusterFromS3Message.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>The password for the master database user. This password can contain any printable ASCII character except \"/\", \"\"\", or \"@\".</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 8 to 41 characters.</p>\n            </li>\n            <li>\n               <p>Can't be specified if <code>ManageMasterUserPassword</code> is turned on.</p>\n            </li>\n         </ul>"}))
    RestoreDBClusterFromS3Message.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>A value that indicates that the restored DB cluster should be associated with the specified option group.</p>\n         <p>Permanent options can't be removed from an option group. An option group can't be removed from a \n            DB cluster once it is associated with a DB cluster.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created\n            if automated backups are enabled\n            using the <code>BackupRetentionPeriod</code> parameter.</p>\n         <p>The default is a 30-minute window selected at random from an\n            8-hour block of time for each Amazon Web Services Region. \n            To view the time blocks available, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Aurora.Managing.Backups.html#Aurora.Managing.Backups.BackupWindow\">\n                Backup window</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    RestoreDBClusterFromS3Message.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur, in Universal Coordinated Time (UTC).</p>\n         <p>Format: <code>ddd:hh24:mi-ddd:hh24:mi</code>\n         </p>\n         <p>The default is a 30-minute window selected at random from an\n            8-hour block of time for each Amazon Web Services Region, occurring on a random day of the\n            week. To see the time blocks available, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_UpgradeDBInstance.Maintenance.html#AdjustingTheMaintenanceWindow.Aurora\">\n                Adjusting the Preferred Maintenance Window</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid Days: Mon, Tue, Wed, Thu, Fri, Sat, Sun.</p>\n         <p>Constraints: Minimum 30-minute window.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    RestoreDBClusterFromS3Message.add_member(:storage_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'StorageEncrypted', traits: {"smithy.api#documentation" => "<p>Specifies whether the restored DB cluster is encrypted.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for an encrypted DB cluster.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>If the StorageEncrypted parameter is enabled, and you do\n            not specify a value for the <code>KmsKeyId</code> parameter, then\n            Amazon RDS will use your default KMS key. There is a  \n            default KMS key for your Amazon Web Services account. Your Amazon Web Services account has a different\n            default KMS key for each Amazon Web Services Region.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access\n            Management (IAM) accounts to database accounts. By default, mapping isn't\n            enabled.</p>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.IAMDBAuth.html\">\n                IAM Database Authentication</a> in the <i>Amazon Aurora User Guide</i>.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:source_engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceEngine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the database engine that was backed up to create the files stored in the\n            Amazon S3 bucket.</p>\n         <p>Valid Values: <code>mysql</code>\n         </p>", "smithy.api#required" => {}}))
    RestoreDBClusterFromS3Message.add_member(:source_engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceEngineVersion', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The version of the database that the backup files were created from.</p>\n         <p>MySQL versions 5.7 and 8.0 are supported.</p>\n         <p>Example: <code>5.7.40</code>, <code>8.0.28</code>\n         </p>", "smithy.api#required" => {}}))
    RestoreDBClusterFromS3Message.add_member(:s3_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3BucketName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Amazon S3 bucket that contains the data used to create the Amazon Aurora DB cluster.</p>", "smithy.api#required" => {}}))
    RestoreDBClusterFromS3Message.add_member(:s3_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3Prefix', traits: {"smithy.api#documentation" => "<p>The prefix for all of the file names that contain the data used to create the Amazon Aurora DB cluster.\n        If you do not specify a <b>SourceS3Prefix</b> value, then the Amazon Aurora DB cluster is\n        created by using all of the files in the Amazon S3 bucket.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:s3_ingestion_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3IngestionRoleArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon Web Services Identity and Access Management (IAM) role that authorizes\n        Amazon RDS to access the Amazon S3 bucket on your behalf.</p>", "smithy.api#required" => {}}))
    RestoreDBClusterFromS3Message.add_member(:backtrack_window, Smithy::Schema::Shapes::ShapeRef.new(shape: LongOptional, location_name: 'BacktrackWindow', traits: {"smithy.api#documentation" => "<p>The target backtrack window, in seconds. To disable backtracking, set this value to\n            0.</p>\n         <note>\n            <p>Currently, Backtrack is only supported for Aurora MySQL DB clusters.</p>\n         </note>\n         <p>Default: 0</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If specified, this value must be set to a number from 0 to 259,200 (72 hours).</p>\n            </li>\n         </ul>"}))
    RestoreDBClusterFromS3Message.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>The list of logs that the restored DB cluster is to export to CloudWatch Logs. The values\n            in the list depend on the DB engine being used.</p>\n         <p>\n            <b>Aurora MySQL</b>\n         </p>\n         <p>Possible values are <code>audit</code>, <code>error</code>, <code>general</code>, <code>instance</code>, <code>slowquery</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>\n            <b>Aurora PostgreSQL</b>\n         </p>\n         <p>Possible value are <code>instance</code>, <code>postgresql</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>For more information about exporting CloudWatch Logs for Amazon RDS, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about exporting CloudWatch Logs for Amazon Aurora, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon Aurora User Guide</i>.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable deletion protection for the DB cluster. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the restored DB cluster to snapshots of the restored DB cluster. The default is not to copy them.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>Specify the Active Directory directory ID to restore the DB cluster in.\n          The domain must be created prior to this operation.</p>\n         <p>For Amazon Aurora DB clusters, Amazon RDS can use Kerberos Authentication to authenticate users that connect to the DB cluster.\n        For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/kerberos-authentication.html\">Kerberos Authentication</a>\n        in the <i>Amazon Aurora User Guide</i>.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>Specify the name of the IAM role to be used when making API calls to the Directory Service.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:serverless_v2_scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2ScalingConfiguration, location_name: 'ServerlessV2ScalingConfiguration'))
    RestoreDBClusterFromS3Message.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB cluster.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>IPV4</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>DUAL</code>\n               </p>\n            </li>\n         </ul>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB cluster. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon Aurora User Guide.</i>\n         </p>"}))
    RestoreDBClusterFromS3Message.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide</i> and <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon Aurora User Guide.</i>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't manage the master user password with Amazon Web Services Secrets Manager if <code>MasterUserPassword</code> \n                    is specified.</p>\n            </li>\n         </ul>"}))
    RestoreDBClusterFromS3Message.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and \n            managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets \n            Manager for the DB cluster.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>If you don't specify <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> \n            KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't \n            use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer \n            managed KMS key.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>"}))
    RestoreDBClusterFromS3Message.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>Specifies the storage type to be associated with the DB cluster.</p>\n         <p>Valid Values: <code>aurora</code>, <code>aurora-iopt1</code>\n         </p>\n         <p>Default: <code>aurora</code>\n         </p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterFromS3Message.add_member(:engine_lifecycle_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineLifecycleSupport', traits: {"smithy.api#documentation" => "<p>The life cycle type for this DB cluster.</p>\n         <note>\n            <p>By default, this value is set to <code>open-source-rds-extended-support</code>, which enrolls your DB cluster into Amazon RDS Extended Support. \n              At the end of standard support, you can avoid charges for Extended Support by setting the value to <code>open-source-rds-extended-support-disabled</code>. In this case, \n              RDS automatically upgrades your restored DB cluster to a higher engine version, if the major engine version is past its end of standard support date.</p>\n         </note>\n         <p>You can use this setting to enroll your DB cluster into Amazon RDS Extended Support. With RDS Extended Support, \n        you can run the selected major engine version on your DB cluster past the end of standard support for that engine version. For more information, see the following sections:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora - <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon Aurora</a> in the <i>Amazon Aurora User Guide</i>\n               </p>\n            </li>\n            <li>\n               <p>Amazon RDS - <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon RDS</a> in the <i>Amazon RDS User Guide</i>\n               </p>\n            </li>\n         </ul>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values: <code>open-source-rds-extended-support | open-source-rds-extended-support-disabled</code>\n         </p>\n         <p>Default: <code>open-source-rds-extended-support</code>\n         </p>"}))
    RestoreDBClusterFromS3Message.type = Types::RestoreDBClusterFromS3Message
    RestoreDBClusterFromS3Result.add_member(:db_cluster, Smithy::Schema::Shapes::ShapeRef.new(shape: DBCluster, location_name: 'DBCluster'))
    RestoreDBClusterFromS3Result.type = Types::RestoreDBClusterFromS3Result
    RestoreDBClusterFromSnapshotMessage.add_member(:availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZones, location_name: 'AvailabilityZones', traits: {"smithy.api#documentation" => "<p>Provides the list of Availability Zones (AZs) where instances in the restored DB\n            cluster can be created.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB cluster to create from the DB snapshot or DB cluster snapshot.\n            This parameter isn't case-sensitive.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-snapshot-id</code>\n         </p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>", "smithy.api#required" => {}}))
    RestoreDBClusterFromSnapshotMessage.add_member(:snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnapshotIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the DB snapshot or DB cluster snapshot to restore from.</p>\n         <p>You can use either the name or the Amazon Resource Name (ARN) to specify a DB\n            cluster snapshot. However, you can use only the ARN to specify a DB snapshot.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing Snapshot.</p>\n            </li>\n         </ul>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>", "smithy.api#required" => {}}))
    RestoreDBClusterFromSnapshotMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The database engine to use for the new DB cluster.</p>\n         <p>Default: The same as source</p>\n         <p>Constraint: Must be compatible with the engine of the source</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>", "smithy.api#required" => {}}))
    RestoreDBClusterFromSnapshotMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version of the database engine to use for the new DB cluster. If you don't specify an engine version, the default version\n            for the database engine in the Amazon Web Services Region is used.</p>\n         <p>To list all of the available engine versions for Aurora MySQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine aurora-mysql --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>To list all of the available engine versions for Aurora PostgreSQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine aurora-postgresql --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>To list all of the available engine versions for RDS for MySQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine mysql --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>To list all of the available engine versions for RDS for PostgreSQL, use the following command:</p>\n         <p>\n            <code>aws rds describe-db-engine-versions --engine postgres --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>\n         <p>\n            <b>Aurora MySQL</b>\n         </p>\n         <p>See <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/AuroraMySQL.Updates.html\">Database \n            engine updates for Amazon Aurora MySQL</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>\n            <b>Aurora PostgreSQL</b>\n         </p>\n         <p>See <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/AuroraPostgreSQL.Updates.20180305.html\">Amazon \n            Aurora PostgreSQL releases and engine versions</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>\n            <b>MySQL</b>\n         </p>\n         <p>See <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_MySQL.html#MySQL.Concepts.VersionMgmt\">Amazon \n            RDS for MySQL</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>\n            <b>PostgreSQL</b>\n         </p>\n         <p>See <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_PostgreSQL.html#PostgreSQL.Concepts\">Amazon \n            RDS for PostgreSQL versions and extensions</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the new DB cluster accepts connections.</p>\n         <p>Constraints: This value must be <code>1150-65535</code>\n         </p>\n         <p>Default: The same port as the original DB cluster.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB subnet group to use for the new DB cluster.</p>\n         <p>Constraints: If supplied, must match the name of an existing DB subnet group.</p>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:database_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DatabaseName', traits: {"smithy.api#documentation" => "<p>The database name for the restored DB cluster.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The name of the option group to use for the restored DB cluster.</p>\n         <p>DB clusters are associated with a default option group that can't be modified.</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of VPC security groups that the new DB cluster will belong to.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags to be assigned to the restored DB cluster.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to use when restoring an encrypted DB cluster from a DB\n            snapshot or DB cluster snapshot.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n          To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>When you don't specify a value for the <code>KmsKeyId</code> parameter, then the\n            following occurs:</p>\n         <ul>\n            <li>\n               <p>If the DB snapshot or DB cluster snapshot in\n                    <code>SnapshotIdentifier</code> is encrypted, then the restored DB cluster\n                    is encrypted using the KMS key that was used to encrypt the DB snapshot or DB\n                    cluster snapshot.</p>\n            </li>\n            <li>\n               <p>If the DB snapshot or DB cluster snapshot in \n                    <code>SnapshotIdentifier</code> isn't encrypted, then the restored DB cluster\n                    isn't encrypted.</p>\n            </li>\n         </ul>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access\n            Management (IAM) accounts to database accounts. By default, mapping isn't\n            enabled.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.IAMDBAuth.html\"> IAM Database\n                Authentication</a> in the <i>Amazon Aurora User Guide</i> or\n                <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\"> IAM database\n                authentication for MariaDB, MySQL, and PostgreSQL</a> in the <i>Amazon\n                RDS User Guide</i>.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:backtrack_window, Smithy::Schema::Shapes::ShapeRef.new(shape: LongOptional, location_name: 'BacktrackWindow', traits: {"smithy.api#documentation" => "<p>The target backtrack window, in seconds. To disable backtracking, set this value to\n            0.</p>\n         <note>\n            <p>Currently, Backtrack is only supported for Aurora MySQL DB clusters.</p>\n         </note>\n         <p>Default: 0</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If specified, this value must be set to a number from 0 to 259,200 (72 hours).</p>\n            </li>\n         </ul>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>The list of logs that the restored DB cluster is to export to Amazon CloudWatch Logs.\n            The values in the list depend on the DB engine being used.</p>\n         <p>\n            <b>RDS for MySQL</b>\n         </p>\n         <p>Possible values are <code>error</code>, <code>general</code>, <code>slowquery</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>\n            <b>RDS for PostgreSQL</b>\n         </p>\n         <p>Possible values are <code>postgresql</code>, <code>upgrade</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>\n            <b>Aurora MySQL</b>\n         </p>\n         <p>Possible values are <code>audit</code>, <code>error</code>, <code>general</code>, <code>instance</code>, <code>slowquery</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>\n            <b>Aurora PostgreSQL</b>\n         </p>\n         <p>Possible value are <code>instance</code>, <code>postgresql</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>For more information about exporting CloudWatch Logs for Amazon RDS, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about exporting CloudWatch Logs for Amazon Aurora, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:engine_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineMode', traits: {"smithy.api#documentation" => "<p>The DB engine mode of the DB cluster, either <code>provisioned</code> or <code>serverless</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/APIReference/API_CreateDBCluster.html\">\n            CreateDBCluster</a>.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingConfiguration, location_name: 'ScalingConfiguration', traits: {"smithy.api#documentation" => "<p>For DB clusters in <code>serverless</code> DB engine mode, the scaling properties of the DB cluster.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB cluster parameter group to associate with this DB cluster. If this\n            argument is omitted, the default DB cluster parameter group for the specified engine is\n            used.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the name of an existing default DB cluster parameter group.</p>\n            </li>\n            <li>\n               <p>Must be 1 to 255 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable deletion protection for the DB cluster. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the restored DB cluster to snapshots of the restored DB cluster. The default is not to copy them.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The Active Directory directory ID to restore the DB cluster in.\n           The domain must be created prior to this operation. Currently, only MySQL, Microsoft SQL \n           Server, Oracle, and PostgreSQL DB instances can be created in an Active Directory Domain.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/kerberos-authentication.html\">\n            Kerberos Authentication</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM role to be used when making API calls to the Directory Service.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:db_cluster_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterInstanceClass', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of the each DB instance in the Multi-AZ DB cluster, for example db.m6gd.xlarge.\n            Not all DB instance classes are available in all Amazon Web Services Regions, or for all database engines.</p>\n         <p>For the full list of DB instance classes, and availability for your engine, see\n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">DB Instance Class</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Valid for: Multi-AZ DB clusters only</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>Specifies the storage type to be associated with the DB cluster.</p>\n         <p>When specified for a Multi-AZ DB cluster, a value for the <code>Iops</code> parameter is required.</p>\n         <p>Valid Values: <code>aurora</code>, <code>aurora-iopt1</code> (Aurora DB clusters); <code>io1</code> (Multi-AZ DB clusters)</p>\n         <p>Default: <code>aurora</code> (Aurora DB clusters); <code>io1</code> (Multi-AZ DB clusters)</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The amount of Provisioned IOPS (input/output operations per second) to be initially allocated for \n            each DB instance in the Multi-AZ DB cluster.</p>\n         <p>For information about valid IOPS values, \n            see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_Storage.html#USER_PIOPS\">Amazon RDS Provisioned IOPS storage</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Constraints: Must be a multiple between .5 and 50 of the storage amount for the DB instance.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB cluster is publicly accessible.</p>\n         <p>When the DB cluster is publicly accessible, its Domain Name System (DNS) endpoint resolves to the private IP address \n            from within the DB cluster's virtual private cloud (VPC). It resolves to the public IP address from outside of the DB cluster's VPC. \n            Access to the DB cluster is ultimately controlled by the security group it uses. \n            That public access is not permitted if the security group assigned to the DB cluster doesn't permit it.</p>\n         <p>When the DB cluster isn't publicly accessible, it is an internal DB cluster with a DNS name that resolves to a private IP address.</p>\n         <p>Default: The default behavior varies depending on whether <code>DBSubnetGroupName</code> is specified.</p>\n         <p>If <code>DBSubnetGroupName</code> isn't specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the default VPC in the target Region doesn’t have an internet gateway attached to it, the DB cluster is private.</p>\n            </li>\n            <li>\n               <p>If the default VPC in the target Region has an internet gateway attached to it, the DB cluster is public.</p>\n            </li>\n         </ul>\n         <p>If <code>DBSubnetGroupName</code> is specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the subnets are part of a VPC that doesn’t have an internet gateway attached to it, the DB cluster is private.</p>\n            </li>\n            <li>\n               <p>If the subnets are part of a VPC that has an internet gateway attached to it, the DB cluster is public.</p>\n            </li>\n         </ul>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:serverless_v2_scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2ScalingConfiguration, location_name: 'ServerlessV2ScalingConfiguration'))
    RestoreDBClusterFromSnapshotMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB cluster.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>IPV4</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>DUAL</code>\n               </p>\n            </li>\n         </ul>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB cluster. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon Aurora User Guide.</i>\n         </p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:rds_custom_cluster_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RdsCustomClusterConfiguration, location_name: 'RdsCustomClusterConfiguration', traits: {"smithy.api#documentation" => "<p>Reserved for future use.</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are collected for the DB cluster. To turn off \n            collecting Enhanced Monitoring metrics, specify <code>0</code>.</p>\n         <p>If <code>MonitoringRoleArn</code> is specified, also set <code>MonitoringInterval</code> to a value other than <code>0</code>.</p>\n         <p>Valid Values: <code>0 | 1 | 5 | 10 | 15 | 30 | 60</code>\n         </p>\n         <p>Default: <code>0</code>\n         </p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the IAM role that permits RDS to send Enhanced Monitoring metrics to Amazon CloudWatch Logs. \n            An example is <code>arn:aws:iam:123456789012:role/emaccess</code>.</p>\n         <p>If <code>MonitoringInterval</code> is set to a value other than <code>0</code>, supply a <code>MonitoringRoleArn</code> value.</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:enable_performance_insights, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnablePerformanceInsights', traits: {"smithy.api#documentation" => "<p>Specifies whether to turn on Performance Insights for the DB cluster.</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>If you don't specify a value for <code>PerformanceInsightsKMSKeyId</code>, then Amazon RDS uses your default KMS key. \n            There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:performance_insights_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PerformanceInsightsRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain Performance Insights data.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>7</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <i>month</i> * 31, where <i>month</i> is a number of months from 1-23. \n                    Examples: <code>93</code> (3 months * 31), <code>341</code> (11 months * 31), <code>589</code> (19 months * 31)</p>\n            </li>\n            <li>\n               <p>\n                  <code>731</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: <code>7</code> days</p>\n         <p>If you specify a retention period that isn't valid, such as <code>94</code>,  Amazon RDS issues an error.</p>"}))
    RestoreDBClusterFromSnapshotMessage.add_member(:engine_lifecycle_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineLifecycleSupport', traits: {"smithy.api#documentation" => "<p>The life cycle type for this DB cluster.</p>\n         <note>\n            <p>By default, this value is set to <code>open-source-rds-extended-support</code>, which enrolls your DB cluster into Amazon RDS Extended Support. \n              At the end of standard support, you can avoid charges for Extended Support by setting the value to <code>open-source-rds-extended-support-disabled</code>. In this case, \n              RDS automatically upgrades your restored DB cluster to a higher engine version, if the major engine version is past its end of standard support date.</p>\n         </note>\n         <p>You can use this setting to enroll your DB cluster into Amazon RDS Extended Support. With RDS Extended Support, \n        you can run the selected major engine version on your DB cluster past the end of standard support for that engine version. For more information, see the following sections:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora - <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon Aurora</a> in the <i>Amazon Aurora User Guide</i>\n               </p>\n            </li>\n            <li>\n               <p>Amazon RDS - <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon RDS</a> in the <i>Amazon RDS User Guide</i>\n               </p>\n            </li>\n         </ul>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values: <code>open-source-rds-extended-support | open-source-rds-extended-support-disabled</code>\n         </p>\n         <p>Default: <code>open-source-rds-extended-support</code>\n         </p>"}))
    RestoreDBClusterFromSnapshotMessage.type = Types::RestoreDBClusterFromSnapshotMessage
    RestoreDBClusterFromSnapshotResult.add_member(:db_cluster, Smithy::Schema::Shapes::ShapeRef.new(shape: DBCluster, location_name: 'DBCluster'))
    RestoreDBClusterFromSnapshotResult.type = Types::RestoreDBClusterFromSnapshotResult
    RestoreDBClusterToPointInTimeMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the new DB cluster to be created.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens</p>\n            </li>\n            <li>\n               <p>First character must be a letter</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens</p>\n            </li>\n         </ul>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>", "smithy.api#required" => {}}))
    RestoreDBClusterToPointInTimeMessage.add_member(:restore_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'RestoreType', traits: {"smithy.api#documentation" => "<p>The type of restore to be performed. You can specify one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>full-copy</code> - The new DB cluster is restored as a full copy of the\n                source DB cluster.</p>\n            </li>\n            <li>\n               <p>\n                  <code>copy-on-write</code> - The new DB cluster is restored as a clone of the\n                source DB cluster.</p>\n            </li>\n         </ul>\n         <p>If you don't specify a <code>RestoreType</code> value, then the new DB cluster is\n            restored as a full copy of the source DB cluster.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:source_db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDBClusterIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of the source DB cluster from which to restore.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing DBCluster.</p>\n            </li>\n         </ul>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:restore_to_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'RestoreToTime', traits: {"smithy.api#documentation" => "<p>The date and time to restore the DB cluster to.</p>\n         <p>Valid Values: Value must be a time in Universal Coordinated Time (UTC) format</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be before the latest restorable time for the DB instance</p>\n            </li>\n            <li>\n               <p>Must be specified if <code>UseLatestRestorableTime</code> parameter isn't provided</p>\n            </li>\n            <li>\n               <p>Can't be specified if the <code>UseLatestRestorableTime</code> parameter is enabled</p>\n            </li>\n            <li>\n               <p>Can't be specified if the <code>RestoreType</code> parameter is <code>copy-on-write</code>\n               </p>\n            </li>\n         </ul>\n         <p>Example: <code>2015-03-07T23:45:00Z</code>\n         </p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:use_latest_restorable_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'UseLatestRestorableTime', traits: {"smithy.api#documentation" => "<p>Specifies whether to restore the DB cluster to the latest \n            restorable backup time. By default, the DB cluster isn't restored to the latest \n            restorable backup time.</p>\n         <p>Constraints: Can't be specified if <code>RestoreToTime</code> parameter is provided.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the new DB cluster accepts connections.</p>\n         <p>Constraints: A value from <code>1150-65535</code>.</p>\n         <p>Default: The default port for the engine.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>The DB subnet group name to use for the new DB cluster.</p>\n         <p>Constraints: If supplied, must match the name of an existing DBSubnetGroup.</p>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The name of the option group for the new DB cluster.</p>\n         <p>DB clusters are associated with a default option group that can't be modified.</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of VPC security groups that the new DB cluster belongs to.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    RestoreDBClusterToPointInTimeMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to use when restoring an encrypted DB cluster from an encrypted DB cluster.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n          To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>You can restore to a new DB cluster and encrypt the new DB cluster with a KMS key that is different from the\n          KMS key used to encrypt the source DB cluster. The new DB cluster is encrypted with the KMS key\n          identified by the <code>KmsKeyId</code> parameter.</p>\n         <p>If you don't specify a value for the <code>KmsKeyId</code> parameter, then the following occurs:</p>\n         <ul>\n            <li>\n               <p>If the DB cluster is encrypted, then the restored DB cluster is encrypted using the KMS key that was used to encrypt the source DB cluster.</p>\n            </li>\n            <li>\n               <p>If the DB cluster isn't encrypted, then the restored DB cluster isn't encrypted.</p>\n            </li>\n         </ul>\n         <p>If <code>DBClusterIdentifier</code> refers to a DB cluster that isn't encrypted, then the restore request\n      is rejected.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access\n            Management (IAM) accounts to database accounts. By default, mapping isn't\n            enabled.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.IAMDBAuth.html\"> IAM Database\n                Authentication</a> in the <i>Amazon Aurora User Guide</i> or\n                <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\"> IAM database\n                authentication for MariaDB, MySQL, and PostgreSQL</a> in the <i>Amazon\n                RDS User Guide</i>.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:backtrack_window, Smithy::Schema::Shapes::ShapeRef.new(shape: LongOptional, location_name: 'BacktrackWindow', traits: {"smithy.api#documentation" => "<p>The target backtrack window, in seconds. To disable backtracking, set this value to\n            0.</p>\n         <p>Default: 0</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If specified, this value must be set to a number from 0 to 259,200 (72 hours).</p>\n            </li>\n         </ul>\n         <p>Valid for: Aurora MySQL DB clusters only</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>The list of logs that the restored DB cluster is to export to CloudWatch Logs. The values\n            in the list depend on the DB engine being used.</p>\n         <p>\n            <b>RDS for MySQL</b>\n         </p>\n         <p>Possible values are <code>error</code>, <code>general</code>, <code>slowquery</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>\n            <b>RDS for PostgreSQL</b>\n         </p>\n         <p>Possible values are <code>postgresql</code>, <code>upgrade</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>\n            <b>Aurora MySQL</b>\n         </p>\n         <p>Possible values are <code>audit</code>, <code>error</code>, <code>general</code>, <code>instance</code>, <code>slowquery</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>\n            <b>Aurora PostgreSQL</b>\n         </p>\n         <p>Possible value are <code>instance</code>, <code>postgresql</code>, and <code>iam-db-auth-error</code>.</p>\n         <p>For more information about exporting CloudWatch Logs for Amazon RDS, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about exporting CloudWatch Logs for Amazon Aurora, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the custom DB cluster parameter group to associate with this DB cluster.</p>\n         <p>If the <code>DBClusterParameterGroupName</code> parameter is omitted, the default DB cluster parameter group for the specified\n            engine is used.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the name of an existing DB cluster parameter group.</p>\n            </li>\n            <li>\n               <p>Must be 1 to 255 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable deletion protection for the DB cluster. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the restored DB cluster to snapshots of the restored DB cluster. The default is not to copy them.</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The Active Directory directory ID to restore the DB cluster in.\n          The domain must be created prior to this operation.</p>\n         <p>For Amazon Aurora DB clusters, Amazon RDS can use Kerberos Authentication to authenticate users that connect to the DB cluster.\n        For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/kerberos-authentication.html\">Kerberos Authentication</a>\n        in the <i>Amazon Aurora User Guide</i>.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM role to be used when making API calls to the Directory Service.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingConfiguration, location_name: 'ScalingConfiguration', traits: {"smithy.api#documentation" => "<p>For DB clusters in <code>serverless</code> DB engine mode, the scaling properties of the DB cluster.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:engine_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineMode', traits: {"smithy.api#documentation" => "<p>The engine mode of the new cluster. Specify <code>provisioned</code> or <code>serverless</code>,\n      depending on the type of the cluster you are creating. You can create an Aurora Serverless v1 clone\n      from a provisioned cluster, or a provisioned clone from an Aurora Serverless v1 cluster. To create a clone\n      that is an Aurora Serverless v1 cluster, the original cluster must be an Aurora Serverless v1 cluster or\n      an encrypted provisioned cluster. To create a full copy that is an Aurora Serverless v1 cluster, specify \n      the engine mode <code>serverless</code>.</p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:db_cluster_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterInstanceClass', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of the each DB instance in the Multi-AZ DB cluster,\n            for example db.m6gd.xlarge. Not all DB instance classes are available in all Amazon Web Services\n            Regions, or for all database engines.</p>\n         <p>For the full list of DB instance classes, and availability for your engine, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">DB instance class</a> in the \n            <i>Amazon RDS User Guide</i>.</p>\n         <p>Valid for: Multi-AZ DB clusters only</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>Specifies the storage type to be associated with the DB cluster.</p>\n         <p>When specified for a Multi-AZ DB cluster, a value for the <code>Iops</code> parameter is required.</p>\n         <p>Valid Values: <code>aurora</code>, <code>aurora-iopt1</code> (Aurora DB clusters); <code>io1</code> (Multi-AZ DB clusters)</p>\n         <p>Default: <code>aurora</code> (Aurora DB clusters); <code>io1</code> (Multi-AZ DB clusters)</p>\n         <p>Valid for: Aurora DB clusters and Multi-AZ DB clusters</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB cluster is publicly accessible.</p>\n         <p>When the DB cluster is publicly accessible, its Domain Name System (DNS) endpoint resolves to the private IP address \n            from within the DB cluster's virtual private cloud (VPC). It resolves\n            to the public IP address from outside of the DB cluster's VPC. \n            Access to the DB cluster is ultimately controlled by the security group it uses. \n            That public access is not permitted if the security group assigned to the DB cluster doesn't permit it.</p>\n         <p>When the DB cluster isn't publicly accessible, it is an internal DB cluster with a DNS name that resolves to a private IP address.</p>\n         <p>Default: The default behavior varies depending on whether <code>DBSubnetGroupName</code> is specified.</p>\n         <p>If <code>DBSubnetGroupName</code> isn't specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the default VPC in the target Region doesn’t have an internet gateway attached to it, the DB cluster is private.</p>\n            </li>\n            <li>\n               <p>If the default VPC in the target Region has an internet gateway attached to it, the DB cluster is public.</p>\n            </li>\n         </ul>\n         <p>If <code>DBSubnetGroupName</code> is specified, and <code>PubliclyAccessible</code> isn't specified, the following applies:</p>\n         <ul>\n            <li>\n               <p>If the subnets are part of a VPC that doesn’t have an internet gateway attached to it, the DB cluster is private.</p>\n            </li>\n            <li>\n               <p>If the subnets are part of a VPC that has an internet gateway attached to it, the DB cluster is public.</p>\n            </li>\n         </ul>\n         <p>Valid for: Multi-AZ DB clusters only</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The amount of Provisioned IOPS (input/output operations per second) to be initially allocated for \n            each DB instance in the Multi-AZ DB cluster.</p>\n         <p>For information about valid IOPS values, \n            see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_Storage.html#USER_PIOPS\">Amazon RDS Provisioned IOPS storage</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Constraints: Must be a multiple between .5 and 50 of the storage amount for the DB instance.</p>\n         <p>Valid for: Multi-AZ DB clusters only</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:serverless_v2_scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2ScalingConfiguration, location_name: 'ServerlessV2ScalingConfiguration'))
    RestoreDBClusterToPointInTimeMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB cluster.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>IPV4</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>DUAL</code>\n               </p>\n            </li>\n         </ul>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB cluster. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon Aurora User Guide.</i>\n         </p>\n         <p>Valid for: Aurora DB clusters only</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:source_db_cluster_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDbClusterResourceId', traits: {"smithy.api#documentation" => "<p>The resource ID of the source DB cluster from which to restore.</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:rds_custom_cluster_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: RdsCustomClusterConfiguration, location_name: 'RdsCustomClusterConfiguration', traits: {"smithy.api#documentation" => "<p>Reserved for future use.</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, between points when Enhanced Monitoring metrics are collected for the DB cluster. To turn off \n            collecting Enhanced Monitoring metrics, specify <code>0</code>.</p>\n         <p>If <code>MonitoringRoleArn</code> is specified, also set <code>MonitoringInterval</code> to a value other than <code>0</code>.</p>\n         <p>Valid Values: <code>0 | 1 | 5 | 10 | 15 | 30 | 60</code>\n         </p>\n         <p>Default: <code>0</code>\n         </p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) for the IAM role that permits RDS to send Enhanced Monitoring metrics to Amazon CloudWatch Logs. \n            An example is <code>arn:aws:iam:123456789012:role/emaccess</code>.</p>\n         <p>If <code>MonitoringInterval</code> is set to a value other than <code>0</code>, supply a <code>MonitoringRoleArn</code> value.</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:enable_performance_insights, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnablePerformanceInsights', traits: {"smithy.api#documentation" => "<p>Specifies whether to turn on Performance Insights for the DB cluster.</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>If you don't specify a value for <code>PerformanceInsightsKMSKeyId</code>, then Amazon RDS uses your default KMS key. \n            There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:performance_insights_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PerformanceInsightsRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain Performance Insights data.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>7</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <i>month</i> * 31, where <i>month</i> is a number of months from 1-23. \n                    Examples: <code>93</code> (3 months * 31), <code>341</code> (11 months * 31), <code>589</code> (19 months * 31)</p>\n            </li>\n            <li>\n               <p>\n                  <code>731</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: <code>7</code> days</p>\n         <p>If you specify a retention period that isn't valid, such as <code>94</code>,  Amazon RDS issues an error.</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:engine_lifecycle_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineLifecycleSupport', traits: {"smithy.api#documentation" => "<p>The life cycle type for this DB cluster.</p>\n         <note>\n            <p>By default, this value is set to <code>open-source-rds-extended-support</code>, which enrolls your DB cluster into Amazon RDS Extended Support. \n              At the end of standard support, you can avoid charges for Extended Support by setting the value to <code>open-source-rds-extended-support-disabled</code>. In this case, \n              RDS automatically upgrades your restored DB cluster to a higher engine version, if the major engine version is past its end of standard support date.</p>\n         </note>\n         <p>You can use this setting to enroll your DB cluster into Amazon RDS Extended Support. With RDS Extended Support, \n        you can run the selected major engine version on your DB cluster past the end of standard support for that engine version. For more information, see the following sections:</p>\n         <ul>\n            <li>\n               <p>Amazon Aurora - <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon Aurora</a> in the <i>Amazon Aurora User Guide</i>\n               </p>\n            </li>\n            <li>\n               <p>Amazon RDS - <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon RDS</a> in the <i>Amazon RDS User Guide</i>\n               </p>\n            </li>\n         </ul>\n         <p>Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters</p>\n         <p>Valid Values: <code>open-source-rds-extended-support | open-source-rds-extended-support-disabled</code>\n         </p>\n         <p>Default: <code>open-source-rds-extended-support</code>\n         </p>"}))
    RestoreDBClusterToPointInTimeMessage.type = Types::RestoreDBClusterToPointInTimeMessage
    RestoreDBClusterToPointInTimeResult.add_member(:db_cluster, Smithy::Schema::Shapes::ShapeRef.new(shape: DBCluster, location_name: 'DBCluster'))
    RestoreDBClusterToPointInTimeResult.type = Types::RestoreDBClusterToPointInTimeResult
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB instance to create from the DB snapshot. This parameter isn't case-sensitive.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 numbers, letters, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>my-snapshot-id</code>\n         </p>", "smithy.api#required" => {}}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:db_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSnapshotIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier for the DB snapshot to restore from.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing DB snapshot.</p>\n            </li>\n            <li>\n               <p>Can't be specified when <code>DBClusterSnapshotIdentifier</code> is specified.</p>\n            </li>\n            <li>\n               <p>Must be specified when <code>DBClusterSnapshotIdentifier</code> isn't specified.</p>\n            </li>\n            <li>\n               <p>If you are restoring from a shared manual DB snapshot, the <code>DBSnapshotIdentifier</code>\n              must be the ARN of the shared DB snapshot.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceClass', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of the Amazon RDS DB instance, for example db.m4.large.\n          Not all DB instance classes are available in all Amazon Web Services Regions, or for all database engines.\n          For the full list of DB instance classes,\n          and availability for your engine, see\n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">DB Instance Class</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Default: The same DBInstanceClass as the original DB instance.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the database accepts connections.</p>\n         <p>Default: The same port as the original DB instance</p>\n         <p>Constraints: Value must be <code>1150-65535</code>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZone', traits: {"smithy.api#documentation" => "<p>The Availability Zone (AZ) where the DB instance will be created.</p>\n         <p>Default: A random, system-chosen Availability Zone.</p>\n         <p>Constraint: You can't specify the <code>AvailabilityZone</code> parameter if the DB instance is a Multi-AZ deployment.</p>\n         <p>Example: <code>us-east-1a</code>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB subnet group to use for the new instance.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the name of an existing DB subnet group.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is a Multi-AZ deployment.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>Constraint: You can't specify the <code>AvailabilityZone</code> parameter if the DB instance is a Multi-AZ deployment.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is publicly accessible.</p>\n         <p>When the DB instance is publicly accessible, its Domain Name System (DNS) endpoint resolves to the private IP address \n          from within the DB instance's virtual private cloud (VPC). \n          It resolves to the public IP address from outside of the DB instance's VPC. Access to the DB instance is ultimately controlled \n          by the security group it uses. That public access is not permitted if the security group assigned to the DB instance doesn't permit it.</p>\n         <p>When the DB instance isn't publicly accessible, it is an internal DB instance with a DNS name that resolves to a private IP address.</p>\n         <p>For more information, see <a>CreateDBInstance</a>.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether to automatically apply minor version upgrades to the DB instance \n          during the maintenance window.</p>\n         <p>If you restore an RDS Custom DB instance, you must disable this parameter.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:license_model, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LicenseModel', traits: {"smithy.api#documentation" => "<p>License model information for the restored DB instance.</p>\n         <note>\n            <p>License models for RDS for Db2 require additional configuration. The Bring Your\n                Own License (BYOL) model requires a custom parameter group and an Amazon Web Services License Manager self-managed license. The Db2 license through\n                Amazon Web Services Marketplace model requires an Amazon Web Services Marketplace subscription. For more\n                information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/db2-licensing.html\">Amazon RDS for Db2 licensing\n                    options</a> in the <i>Amazon RDS User Guide</i>.</p>\n         </note>\n         <p>This setting doesn't apply to Amazon Aurora or RDS Custom DB instances.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>RDS for Db2 - <code>bring-your-own-license | marketplace-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - <code>general-public-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - <code>license-included</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>general-public-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Oracle - <code>bring-your-own-license | license-included</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql-license</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: Same as the source.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:db_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBName', traits: {"smithy.api#documentation" => "<p>The name of the database for the restored DB instance.</p>\n         <p>This parameter only applies to RDS for Oracle and RDS for SQL Server DB instances. It doesn't apply to the other engines or to RDS\n          Custom DB instances.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The database engine to use for the new instance.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>Default: The same as source</p>\n         <p>Constraint: Must be compatible with the engine of the source. For example, you can restore a MariaDB 10.1 DB instance from a MySQL 5.6 snapshot.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db2-ae</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>db2-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mariadb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>postgres</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ex</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-web</code>\n               </p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>Specifies the amount of provisioned IOPS for the DB instance, expressed in I/O operations per second. \n          If this parameter isn't specified, the IOPS value is taken from the backup. \n          If this parameter is set to 0, the new instance is converted to a non-PIOPS instance. \n          The conversion takes additional time, though your DB instance is available for connections before the conversion starts.</p>\n         <p>The provisioned IOPS value must follow the requirements for your database engine.\n          For more information, see \n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_Storage.html#USER_PIOPS\">Amazon RDS Provisioned IOPS storage</a> \n          in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Constraints: Must be an integer greater than 1000.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The name of the option group to be used for the restored DB instance.</p>\n         <p>Permanent options, such as the TDE option for Oracle Advanced Security TDE, can't be removed from an option \n        group, and that option group can't be removed from a DB instance after it is associated with a DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>Specifies the storage type to be associated with the DB instance.</p>\n         <p>Valid Values: <code>gp2 | gp3 | io1 | io2 | standard</code>\n         </p>\n         <p>If you specify <code>io1</code>, <code>io2</code>, or <code>gp3</code>, you must also include a value for the\n            <code>Iops</code> parameter.</p>\n         <p>Default: <code>io1</code> if the <code>Iops</code> parameter is specified, otherwise\n                <code>gp3</code>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:tde_credential_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialArn', traits: {"smithy.api#documentation" => "<p>The ARN from the key store with which to associate the instance for TDE encryption.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:tde_credential_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialPassword', traits: {"smithy.api#documentation" => "<p>The password for the given ARN from the key store in order to access the device.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of EC2 VPC security groups to associate with this DB instance.</p>\n         <p>Default: The default EC2 VPC security group for the DB subnet group's VPC.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The Active Directory directory ID to restore the DB instance in.\n           The domain/ must be created prior to this operation. Currently, you can create only Db2, MySQL, Microsoft SQL \n          Server, Oracle, and PostgreSQL DB instances in an Active Directory Domain.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/kerberos-authentication.html\">\n           Kerberos Authentication</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:domain_fqdn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainFqdn', traits: {"smithy.api#documentation" => "<p>The fully qualified domain name (FQDN) of an Active Directory domain.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mymanagedADtest.mymanagedAD.mydomain</code>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:domain_ou, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainOu', traits: {"smithy.api#documentation" => "<p>The Active Directory organizational unit for your DB instance to join.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the distinguished name format.</p>\n            </li>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>OU=mymanagedADtestOU,DC=mymanagedADtest,DC=mymanagedAD,DC=mydomain</code>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:domain_auth_secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainAuthSecretArn', traits: {"smithy.api#documentation" => "<p>The ARN for the Secrets Manager secret with the credentials for the user joining the domain.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>arn:aws:secretsmanager:region:account-number:secret:myselfmanagedADtestsecret-123456</code>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:domain_dns_ips, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'DomainDnsIps', traits: {"smithy.api#documentation" => "<p>The IPv4 DNS IP addresses of your primary and secondary Active Directory domain controllers.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Two IP addresses must be provided.  If there isn't a secondary domain controller, use the IP address of the primary domain controller for both entries in the list.</p>\n            </li>\n         </ul>\n         <p>Example: <code>123.124.125.126,234.235.236.237</code>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the restored DB instance to snapshots of the DB instance.</p>\n         <p>In most cases, tags aren't copied by default. However, when you restore a DB instance from a DB snapshot, RDS checks whether you \n          specify new tags. If yes, the new tags are added to the restored DB instance. If there are no new tags, RDS looks for the tags from\n          the source DB instance for the DB snapshot, and then adds those tags to the restored DB instance.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Tagging.html#USER_Tagging.CopyTags\">\n          Copying tags to DB instance snapshots</a> in the <i>Amazon RDS User Guide</i>.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM role to use when making API calls to the Directory Service.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access\n          Management (IAM) accounts to database accounts. By default, mapping is disabled.</p>\n         <p>For more information about IAM database authentication, see \n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\">\n              IAM Database Authentication for MySQL and PostgreSQL</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>The list of logs for the restored DB instance to export to CloudWatch Logs. The values\n            in the list depend on the DB engine. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessorFeatureList, location_name: 'ProcessorFeatures', traits: {"smithy.api#documentation" => "<p>The number of CPU cores and the number of threads per core for the DB instance class of the DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:use_default_processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseDefaultProcessorFeatures', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance class of the DB instance uses its default\n            processor features.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to associate with this DB instance.</p>\n         <p>If you don't specify a value for <code>DBParameterGroupName</code>, then RDS uses the default <code>DBParameterGroup</code> \n            for the specified DB engine.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the name of an existing DB parameter group.</p>\n            </li>\n            <li>\n               <p>Must be 1 to 255 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable deletion protection for the DB instance. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_DeleteInstance.html\">\n                Deleting a DB Instance</a>.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:enable_customer_owned_ip, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableCustomerOwnedIp', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable a customer-owned IP address (CoIP) for an RDS on Outposts DB instance.</p>\n         <p>A <i>CoIP</i> provides local or external connectivity to resources in\n            your Outpost subnets through your on-premises network. For some use cases, a CoIP can\n            provide lower latency for connections to the DB instance from outside of its virtual\n            private cloud (VPC) on your local network.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>For more information about RDS on Outposts, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-on-outposts.html\">Working with Amazon RDS on Amazon Web Services Outposts</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about CoIPs, see <a href=\"https://docs.aws.amazon.com/outposts/latest/userguide/routing.html#ip-addressing\">Customer-owned IP addresses</a> \n            in the <i>Amazon Web Services Outposts User Guide</i>.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:custom_iam_instance_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CustomIamInstanceProfile', traits: {"smithy.api#documentation" => "<p>The instance profile associated with the underlying Amazon EC2 instance of an \n            RDS Custom DB instance. The instance profile must meet the following requirements:</p>\n         <ul>\n            <li>\n               <p>The profile must exist in your account.</p>\n            </li>\n            <li>\n               <p>The profile must have an IAM role that Amazon EC2 has permissions to assume.</p>\n            </li>\n            <li>\n               <p>The instance profile name and the associated IAM role name must start with the prefix <code>AWSRDSCustom</code>.</p>\n            </li>\n         </ul>\n         <p>For the list of permissions required for the IAM role, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-setup-orcl.html#custom-setup-orcl.iam-vpc\">\n                Configure IAM and your VPC</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting is required for RDS Custom.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:backup_target, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BackupTarget', traits: {"smithy.api#documentation" => "<p>Specifies where automated backups and manual snapshots are stored for the restored DB instance.</p>\n         <p>Possible values are <code>local</code> (Dedicated Local Zone), <code>outposts</code> (Amazon Web Services Outposts), and <code>region</code> (Amazon Web Services Region). The default is <code>region</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-on-outposts.html\">Working \n            with Amazon RDS on Amazon Web Services Outposts</a> in the <i>Amazon RDS User Guide</i>.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB instance.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>IPV4</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>DUAL</code>\n               </p>\n            </li>\n         </ul>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB instance. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon RDS User Guide.</i>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'StorageThroughput', traits: {"smithy.api#documentation" => "<p>Specifies the storage throughput value for the DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom or Amazon Aurora.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:db_cluster_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterSnapshotIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier for the Multi-AZ DB cluster snapshot to restore from.</p>\n         <p>For more information on Multi-AZ DB clusters, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/multi-az-db-clusters-concepts.html\"> Multi-AZ DB\n                cluster deployments</a> in the <i>Amazon RDS User\n            Guide</i>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing Multi-AZ DB cluster snapshot.</p>\n            </li>\n            <li>\n               <p>Can't be specified when <code>DBSnapshotIdentifier</code> is specified.</p>\n            </li>\n            <li>\n               <p>Must be specified when <code>DBSnapshotIdentifier</code> isn't specified.</p>\n            </li>\n            <li>\n               <p>If you are restoring from a shared manual Multi-AZ DB cluster snapshot, the <code>DBClusterSnapshotIdentifier</code>\n                    must be the ARN of the shared snapshot.</p>\n            </li>\n            <li>\n               <p>Can't be the identifier of an Aurora DB cluster snapshot.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The amount of storage (in gibibytes) to allocate initially for the DB instance. Follow the allocation rules specified in\n            CreateDBInstance.</p>\n         <p>This setting isn't valid for RDS for SQL Server.</p>\n         <note>\n            <p>Be sure to allocate enough storage for your new DB instance so that the restore operation can succeed. You can also\n                allocate additional storage for future growth.</p>\n         </note>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:dedicated_log_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DedicatedLogVolume', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable a dedicated log volume (DLV) for the DB instance.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>The CA certificate identifier to use for the DB instance's server certificate.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n            instance</a> in the <i>Amazon RDS User Guide</i> and \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL.html\">\n                Using SSL/TLS to encrypt a connection to a DB cluster</a> in the <i>Amazon Aurora \n                    User Guide</i>.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:engine_lifecycle_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineLifecycleSupport', traits: {"smithy.api#documentation" => "<p>The life cycle type for this DB instance.</p>\n         <note>\n            <p>By default, this value is set to <code>open-source-rds-extended-support</code>, which enrolls your DB instance into Amazon RDS Extended Support. \n              At the end of standard support, you can avoid charges for Extended Support by setting the value to <code>open-source-rds-extended-support-disabled</code>. In this case,  \n              RDS automatically upgrades your restored DB instance to a higher engine version, if the major engine version is past its end of standard support date.</p>\n         </note>\n         <p>You can use this setting to enroll your DB instance into Amazon RDS Extended Support. With RDS Extended Support, \n        you can run the selected major engine version on your DB instance past the end of standard support for that engine version. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon RDS</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting applies only to RDS for MySQL and RDS for PostgreSQL. For Amazon Aurora DB instances, the life cycle type is managed by the DB cluster.</p>\n         <p>Valid Values: <code>open-source-rds-extended-support | open-source-rds-extended-support-disabled</code>\n         </p>\n         <p>Default: <code>open-source-rds-extended-support</code>\n         </p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager in the\n            restored DB instance.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Applies to RDS for Oracle only.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromDBSnapshotMessage.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and \n            managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets \n            Manager for the DB instance.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>If you don't specify <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> \n            KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't \n            use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer \n            managed KMS key.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>"}))
    RestoreDBInstanceFromDBSnapshotMessage.type = Types::RestoreDBInstanceFromDBSnapshotMessage
    RestoreDBInstanceFromDBSnapshotResult.add_member(:db_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: DBInstance, location_name: 'DBInstance'))
    RestoreDBInstanceFromDBSnapshotResult.type = Types::RestoreDBInstanceFromDBSnapshotResult
    RestoreDBInstanceFromS3Message.add_member(:db_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBName', traits: {"smithy.api#documentation" => "<p>The name of the database to create when the DB instance is created.\n            Follow the naming rules specified in <code>CreateDBInstance</code>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The DB instance identifier. This parameter is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbinstance</code>\n         </p>", "smithy.api#required" => {}}))
    RestoreDBInstanceFromS3Message.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The amount of storage (in gibibytes) to allocate initially for the DB instance.\n            Follow the allocation rules specified in <code>CreateDBInstance</code>.</p>\n         <p>This setting isn't valid for RDS for SQL Server.</p>\n         <note>\n            <p>Be sure to allocate enough storage for your new DB instance so that the restore operation can succeed.\n                You can also allocate additional storage for future growth.</p>\n         </note>"}))
    RestoreDBInstanceFromS3Message.add_member(:db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceClass', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The compute and memory capacity of the DB instance, \n            for example db.m4.large.\n            Not all DB instance classes are available in all Amazon Web Services Regions, \n            or for all database engines.\n            For the full list of DB instance classes,\n            and availability for your engine, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">DB Instance Class</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Importing from Amazon S3 isn't supported on the db.t2.micro DB instance class.</p>", "smithy.api#required" => {}}))
    RestoreDBInstanceFromS3Message.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the database engine to be used for this instance.</p>\n         <p>Valid Values: \n            <code>mysql</code>\n         </p>", "smithy.api#required" => {}}))
    RestoreDBInstanceFromS3Message.add_member(:master_username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUsername', traits: {"smithy.api#documentation" => "<p>The name for the master user.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be 1 to 16 letters or numbers.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't be a reserved word for the chosen database engine.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromS3Message.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>The password for the master user.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be specified if <code>ManageMasterUserPassword</code> is turned on.</p>\n            </li>\n            <li>\n               <p>Can include any printable ASCII character except \"/\", \"\"\", or \"@\". For RDS for Oracle, can't include the \"&\" (ampersand) or  the \"'\" (single quotes) character.</p>\n            </li>\n         </ul>\n         <p>Length Constraints:</p>\n         <ul>\n            <li>\n               <p>RDS for Db2 - Must contain from 8 to 128 characters.</p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - Must contain from 8 to 41 characters.</p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - Must contain from 8 to 128 characters.</p>\n            </li>\n            <li>\n               <p>RDS for MySQL - Must contain from 8 to 41 characters.</p>\n            </li>\n            <li>\n               <p>RDS for Oracle - Must contain from 8 to 30 characters.</p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - Must contain from 8 to 128 characters.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromS3Message.add_member(:db_security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: DBSecurityGroupNameList, location_name: 'DBSecurityGroups', traits: {"smithy.api#documentation" => "<p>A list of DB security groups to associate with this DB instance.</p>\n         <p>Default: The default DB security group for the database engine.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of VPC security groups to associate with this DB instance.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZone', traits: {"smithy.api#documentation" => "<p>The Availability Zone that the DB instance is created in. \n            For information about Amazon Web Services Regions and Availability Zones, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.RegionsAndAvailabilityZones.html\">Regions and Availability Zones</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Default: A random, system-chosen Availability Zone in the endpoint's Amazon Web Services Region.</p>\n         <p>Example: <code>us-east-1d</code>\n         </p>\n         <p>Constraint: The <code>AvailabilityZone</code> parameter can't be specified if the DB instance is a Multi-AZ deployment. \n            The specified Availability Zone must be in the same Amazon Web Services Region as the current endpoint.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>A DB subnet group to associate with this DB instance.</p>\n         <p>Constraints: If supplied, must match the name of an existing DBSubnetGroup.</p>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>"}))
    RestoreDBInstanceFromS3Message.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The time range each week during which system maintenance can occur, \n            in Universal Coordinated Time (UTC). \n            For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Maintenance.html#Concepts.DBMaintenance\">Amazon RDS Maintenance Window</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>ddd:hh24:mi-ddd:hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Valid Days: Mon, Tue, Wed, Thu, Fri, Sat, Sun.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred backup window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromS3Message.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to associate with this DB instance.</p>\n         <p>If you do not specify a value for <code>DBParameterGroupName</code>, then the default <code>DBParameterGroup</code> \n            for the specified DB engine is used.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days for which automated backups are retained. \n            Setting this parameter to a positive number enables backups.\n            For more information, see <code>CreateDBInstance</code>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The time range each day \n            during which automated backups are created \n            if automated backups are enabled. \n            For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_WorkingWithAutomatedBackups.html#USER_WorkingWithAutomatedBackups.BackupWindow\">Backup window</a> in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromS3Message.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the database accepts connections.</p>\n         <p>Type: Integer</p>\n         <p>Valid Values: <code>1150</code>-<code>65535</code>\n         </p>\n         <p>Default: <code>3306</code>\n         </p>"}))
    RestoreDBInstanceFromS3Message.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is a Multi-AZ deployment. \n            If the DB instance is a Multi-AZ deployment, you can't set the <code>AvailabilityZone</code> parameter.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to use.\n            Choose the latest minor version of your database engine. \n            For information about engine versions, see <code>CreateDBInstance</code>, or call <code>DescribeDBEngineVersions</code>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether to automatically apply minor engine upgrades  \n            to the DB instance during the maintenance window. By default, minor engine upgrades \n            are not applied automatically.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:license_model, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LicenseModel', traits: {"smithy.api#documentation" => "<p>The license model for this DB instance.\n            Use <code>general-public-license</code>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The amount of Provisioned IOPS (input/output operations per second) \n            to allocate initially for the DB instance.\n            For information about valid IOPS values, \n            see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/CHAP_Storage.html#USER_PIOPS\">Amazon RDS Provisioned IOPS storage</a> \n            in the <i>Amazon RDS User Guide.</i>\n         </p>"}))
    RestoreDBInstanceFromS3Message.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The name of the option group to associate with this DB instance. \n            If this argument is omitted, the default option group for the specified engine is used.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is publicly accessible.</p>\n         <p>When the DB instance is publicly accessible, its Domain Name System (DNS) endpoint resolves to the private IP address \n            from within the DB instance's virtual private cloud (VPC). \n            It resolves to the public IP address from outside of the DB instance's VPC. \n            Access to the DB instance is ultimately controlled by the security group it uses. \n            That public access is not permitted if the security group assigned to the DB instance doesn't permit it.</p>\n         <p>When the DB instance isn't publicly accessible, it is an internal DB instance with a DNS name that resolves to a private IP address.</p>\n         <p>For more information, see <a>CreateDBInstance</a>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of tags to associate with this DB instance.\n            For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Tagging.html\">Tagging Amazon RDS Resources</a> in the <i>Amazon RDS User Guide.</i>\n         </p>"}))
    RestoreDBInstanceFromS3Message.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>Specifies the storage type to be associated with the DB instance.</p>\n         <p>Valid Values: <code>gp2 | gp3 | io1 | io2 | standard</code>\n         </p>\n         <p>If you specify <code>io1</code>, <code>io2</code>, or <code>gp3</code>, \n            you must also include a value for the <code>Iops</code> parameter.</p>\n         <p>Default: <code>io1</code> \n            if the <code>Iops</code> parameter is specified; \n            otherwise <code>gp2</code>\n         </p>"}))
    RestoreDBInstanceFromS3Message.add_member(:storage_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'StorageEncrypted', traits: {"smithy.api#documentation" => "<p>Specifies whether the new DB instance is encrypted or not.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for an encrypted DB instance.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>If the <code>StorageEncrypted</code> parameter is enabled, \n            and you do not specify a value for the <code>KmsKeyId</code> parameter, \n            then Amazon RDS will use your default KMS key. \n            There is a default KMS key for your Amazon Web Services account. \n            Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the DB instance to snapshots of the DB instance. By default, tags are not copied.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:monitoring_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MonitoringInterval', traits: {"smithy.api#documentation" => "<p>The interval, in seconds, \n            between points when Enhanced Monitoring metrics are collected for the DB instance. \n            To disable collecting Enhanced Monitoring metrics, specify 0.</p>\n         <p>If <code>MonitoringRoleArn</code> is specified, \n            then you must also set <code>MonitoringInterval</code> to a value other than 0.</p>\n         <p>Valid Values: 0, 1, 5, 10, 15, 30, 60</p>\n         <p>Default: <code>0</code>\n         </p>"}))
    RestoreDBInstanceFromS3Message.add_member(:monitoring_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MonitoringRoleArn', traits: {"smithy.api#documentation" => "<p>The ARN for the IAM role that permits RDS \n            to send enhanced monitoring metrics to Amazon CloudWatch Logs. \n            For example, <code>arn:aws:iam:123456789012:role/emaccess</code>. \n            For information on creating a monitoring role, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Monitoring.OS.html#USER_Monitoring.OS.Enabling\">Setting Up and Enabling Enhanced Monitoring</a> \n            in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>If <code>MonitoringInterval</code> is set to a value other than 0, \n            then you must supply a <code>MonitoringRoleArn</code> value.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access Management\n            (IAM) accounts to database accounts. By default, mapping isn't enabled.</p>\n         <p>For more information about IAM database authentication, see \n         <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\">\n             IAM Database Authentication for MySQL and PostgreSQL</a> in the <i>Amazon RDS User Guide.</i>\n         </p>"}))
    RestoreDBInstanceFromS3Message.add_member(:source_engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceEngine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the engine of your source database.</p>\n         <p>Valid Values: \n            <code>mysql</code>\n         </p>", "smithy.api#required" => {}}))
    RestoreDBInstanceFromS3Message.add_member(:source_engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceEngineVersion', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The version of the database that the backup files were created from.</p>\n         <p>MySQL versions 5.6 and 5.7 are supported.</p>\n         <p>Example: <code>5.6.40</code>\n         </p>", "smithy.api#required" => {}}))
    RestoreDBInstanceFromS3Message.add_member(:s3_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3BucketName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of your Amazon S3 bucket \n            that contains your database backup file.</p>", "smithy.api#required" => {}}))
    RestoreDBInstanceFromS3Message.add_member(:s3_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3Prefix', traits: {"smithy.api#documentation" => "<p>The prefix of your Amazon S3 bucket.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:s3_ingestion_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3IngestionRoleArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>An Amazon Web Services Identity and Access Management (IAM) role with a trust policy and a permissions policy that allows Amazon RDS to access your Amazon S3 bucket. \n        For information about this role,\n            see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/MySQL.Procedural.Importing.html#MySQL.Procedural.Importing.Enabling.IAM\">\n            Creating an IAM role manually</a> in the <i>Amazon RDS User Guide.</i>\n         </p>", "smithy.api#required" => {}}))
    RestoreDBInstanceFromS3Message.add_member(:database_insights_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: DatabaseInsightsMode, location_name: 'DatabaseInsightsMode', traits: {"smithy.api#documentation" => "<p>Specifies the mode of Database Insights to enable for the DB instance.</p>\n         <note>\n            <p>Aurora DB instances inherit this value from the DB cluster, so you can't change this value.</p>\n         </note>"}))
    RestoreDBInstanceFromS3Message.add_member(:enable_performance_insights, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnablePerformanceInsights', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable Performance Insights for the DB instance.</p>\n         <p>For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PerfInsights.html\">Using Amazon Performance Insights</a> in the <i>Amazon RDS User Guide</i>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encryption of Performance Insights data.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>\n         <p>If you do not specify a value for <code>PerformanceInsightsKMSKeyId</code>, then Amazon RDS \n            uses your default KMS key. There is a default KMS key for your Amazon Web Services account. \n            Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:performance_insights_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PerformanceInsightsRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days to retain Performance Insights data. The default is 7 days. The following values are valid:</p>\n         <ul>\n            <li>\n               <p>7</p>\n            </li>\n            <li>\n               <p>\n                  <i>month</i> * 31, where <i>month</i> is a number of months from 1-23</p>\n            </li>\n            <li>\n               <p>731</p>\n            </li>\n         </ul>\n         <p>For example, the following values are valid:</p>\n         <ul>\n            <li>\n               <p>93 (3 months * 31)</p>\n            </li>\n            <li>\n               <p>341 (11 months * 31)</p>\n            </li>\n            <li>\n               <p>589 (19 months * 31)</p>\n            </li>\n            <li>\n               <p>731</p>\n            </li>\n         </ul>\n         <p>If you specify a retention period such as 94, which isn't a valid value, RDS issues an error.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>The list of logs that the restored DB instance is to export to CloudWatch Logs. The values\n            in the list depend on the DB engine being used. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessorFeatureList, location_name: 'ProcessorFeatures', traits: {"smithy.api#documentation" => "<p>The number of CPU cores and the number of threads per core for the DB instance class of the DB instance.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:use_default_processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseDefaultProcessorFeatures', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance class of the DB instance uses its default\n            processor features.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable deletion protection for the DB instance. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_DeleteInstance.html\">\n                Deleting a DB Instance</a>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:max_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxAllocatedStorage', traits: {"smithy.api#documentation" => "<p>The upper limit in gibibytes (GiB) to which Amazon RDS can automatically scale the storage of the DB instance.</p>\n         <p>For more information about this setting, including limitations that apply to it, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PIOPS.StorageTypes.html#USER_PIOPS.Autoscaling\">\n                Managing capacity automatically with Amazon RDS storage autoscaling</a> \n            in the <i>Amazon RDS User Guide</i>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB instance.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>IPV4</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>DUAL</code>\n               </p>\n            </li>\n         </ul>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB instance. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon RDS User Guide.</i>\n         </p>"}))
    RestoreDBInstanceFromS3Message.add_member(:storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'StorageThroughput', traits: {"smithy.api#documentation" => "<p>Specifies the storage throughput value for the DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom or Amazon Aurora.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't manage the master user password with Amazon Web Services Secrets Manager if <code>MasterUserPassword</code> \n                    is specified.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceFromS3Message.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and \n            managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets \n            Manager for the DB instance.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>If you don't specify <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> \n            KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't \n            use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer \n            managed KMS key.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:dedicated_log_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DedicatedLogVolume', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable a dedicated log volume (DLV) for the DB instance.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>The CA certificate identifier to use for the DB instance's server certificate.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n            instance</a> in the <i>Amazon RDS User Guide</i> and \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL.html\">\n                Using SSL/TLS to encrypt a connection to a DB cluster</a> in the <i>Amazon Aurora \n                    User Guide</i>.</p>"}))
    RestoreDBInstanceFromS3Message.add_member(:engine_lifecycle_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineLifecycleSupport', traits: {"smithy.api#documentation" => "<p>The life cycle type for this DB instance.</p>\n         <note>\n            <p>By default, this value is set to <code>open-source-rds-extended-support</code>, which enrolls your DB instance into Amazon RDS Extended Support. \n              At the end of standard support, you can avoid charges for Extended Support by setting the value to <code>open-source-rds-extended-support-disabled</code>. In this case,  \n              RDS automatically upgrades your restored DB instance to a higher engine version, if the major engine version is past its end of standard support date.</p>\n         </note>\n         <p>You can use this setting to enroll your DB instance into Amazon RDS Extended Support. With RDS Extended Support, \n        you can run the selected major engine version on your DB instance past the end of standard support for that engine version. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/extended-support.html\">Amazon RDS Extended Support Amazon RDS</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting applies only to RDS for MySQL and RDS for PostgreSQL. For Amazon Aurora DB instances, the life cycle type is managed by the DB cluster.</p>\n         <p>Valid Values: <code>open-source-rds-extended-support | open-source-rds-extended-support-disabled</code>\n         </p>\n         <p>Default: <code>open-source-rds-extended-support</code>\n         </p>"}))
    RestoreDBInstanceFromS3Message.type = Types::RestoreDBInstanceFromS3Message
    RestoreDBInstanceFromS3Result.add_member(:db_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: DBInstance, location_name: 'DBInstance'))
    RestoreDBInstanceFromS3Result.type = Types::RestoreDBInstanceFromS3Result
    RestoreDBInstanceToPointInTimeMessage.add_member(:source_db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDBInstanceIdentifier', traits: {"smithy.api#documentation" => "<p>The identifier of the source DB instance from which to restore.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing DB instance.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:target_db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetDBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the new DB instance to create.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:restore_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'RestoreTime', traits: {"smithy.api#documentation" => "<p>The date and time to restore from.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a time in Universal Coordinated Time (UTC) format.</p>\n            </li>\n            <li>\n               <p>Must be before the latest restorable time for the DB instance.</p>\n            </li>\n            <li>\n               <p>Can't be specified if the <code>UseLatestRestorableTime</code> parameter is enabled.</p>\n            </li>\n         </ul>\n         <p>Example: <code>2009-09-07T23:45:00Z</code>\n         </p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:use_latest_restorable_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'UseLatestRestorableTime', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is restored from the latest backup time. By default, the DB instance \n          isn't restored from the latest backup time.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be specified if the <code>RestoreTime</code> parameter is provided.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceClass', traits: {"smithy.api#documentation" => "<p>The compute and memory capacity of the Amazon RDS DB instance, for example\n                db.m4.large. Not all DB instance classes are available in all Amazon Web Services\n            Regions, or for all database engines. For the full list of DB instance classes, and\n            availability for your engine, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.DBInstanceClass.html\">DB Instance\n                Class</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Default: The same DB instance class as the original DB instance.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the database accepts connections.</p>\n         <p>Default: The same port as the original DB instance.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>The value must be <code>1150-65535</code>.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AvailabilityZone', traits: {"smithy.api#documentation" => "<p>The Availability Zone (AZ) where the DB instance will be created.</p>\n         <p>Default: A random, system-chosen Availability Zone.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>You can't specify the <code>AvailabilityZone</code> parameter if the DB instance is a Multi-AZ deployment.</p>\n            </li>\n         </ul>\n         <p>Example: <code>us-east-1a</code>\n         </p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>The DB subnet group name to use for the new instance.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the name of an existing DB subnet group.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbsubnetgroup</code>\n         </p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:multi_az, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'MultiAZ', traits: {"smithy.api#documentation" => "<p>Secifies whether the DB instance is a Multi-AZ deployment.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>You can't specify the <code>AvailabilityZone</code> parameter if the DB instance is a \n          Multi-AZ deployment.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:publicly_accessible, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'PubliclyAccessible', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is publicly accessible.</p>\n         <p>When the DB cluster is publicly accessible, its Domain Name System (DNS) endpoint\n          resolves to the private IP address from within the DB cluster's virtual private cloud\n          (VPC). It resolves to the public IP address from outside of the DB cluster's VPC. Access\n          to the DB cluster is ultimately controlled by the security group it uses. That public\n          access isn't permitted if the security group assigned to the DB cluster doesn't permit\n          it.</p>\n         <p>When the DB instance isn't publicly accessible, it is an internal DB instance with a DNS name that resolves to a private IP address.</p>\n         <p>For more information, see <a>CreateDBInstance</a>.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>Specifies whether minor version upgrades are applied automatically to the \n          DB instance during the maintenance window.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>For more information about automatic minor version upgrades, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_UpgradeDBInstance.Upgrading.html#USER_UpgradeDBInstance.Upgrading.AutoMinorVersionUpgrades\">Automatically upgrading the minor engine version</a>.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:license_model, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LicenseModel', traits: {"smithy.api#documentation" => "<p>The license model information for the restored DB instance.</p>\n         <note>\n            <p>License models for RDS for Db2 require additional configuration. The Bring Your\n                Own License (BYOL) model requires a custom parameter group and an Amazon Web Services License Manager self-managed license. The Db2 license through\n                Amazon Web Services Marketplace model requires an Amazon Web Services Marketplace subscription. For more\n                information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/db2-licensing.html\">Amazon RDS for Db2 licensing\n                    options</a> in the <i>Amazon RDS User Guide</i>.</p>\n         </note>\n         <p>This setting doesn't apply to Amazon Aurora or RDS Custom DB instances.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>RDS for Db2 - <code>bring-your-own-license | marketplace-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MariaDB - <code>general-public-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Microsoft SQL Server - <code>license-included</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for MySQL - <code>general-public-license</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for Oracle - <code>bring-your-own-license | license-included</code>\n               </p>\n            </li>\n            <li>\n               <p>RDS for PostgreSQL - <code>postgresql-license</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: Same as the source.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:db_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBName', traits: {"smithy.api#documentation" => "<p>The database name for the restored DB instance.</p>\n         <p>This parameter doesn't apply to the following DB instances:</p>\n         <ul>\n            <li>\n               <p>RDS Custom</p>\n            </li>\n            <li>\n               <p>RDS for Db2</p>\n            </li>\n            <li>\n               <p>RDS for MariaDB</p>\n            </li>\n            <li>\n               <p>RDS for MySQL</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#documentation" => "<p>The database engine to use for the new instance.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db2-ae</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>db2-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mariadb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>mysql</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-ee-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>oracle-se2-cdb</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>postgres</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ee</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-se</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-ex</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>sqlserver-web</code>\n               </p>\n            </li>\n         </ul>\n         <p>Default: The same as source</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be compatible with the engine of the source.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The amount of Provisioned IOPS (input/output operations per second) to initially allocate for the DB instance.</p>\n         <p>This setting doesn't apply to SQL Server.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be an integer greater than 1000.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:option_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'OptionGroupName', traits: {"smithy.api#documentation" => "<p>The name of the option group to use for the restored DB instance.</p>\n         <p>Permanent options, such as the TDE option for Oracle Advanced Security TDE, can't be removed from an \n        option group, and that option group can't be removed from a DB instance after it is associated with a DB instance</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>Specifies whether to copy all tags from the restored DB instance to snapshots of the DB instance. By default, tags are not copied.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags'))
    RestoreDBInstanceToPointInTimeMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type to associate with the DB instance.</p>\n         <p>Valid Values: <code>gp2 | gp3 | io1 | io2 | standard</code>\n         </p>\n         <p>Default: <code>io1</code>, if the <code>Iops</code> parameter is specified. Otherwise,\n                <code>gp3</code>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If you specify <code>io1</code>, <code>io2</code>, or <code>gp3</code>, you must also include a value for the\n            <code>Iops</code> parameter.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:tde_credential_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialArn', traits: {"smithy.api#documentation" => "<p>The ARN from the key store with which to associate the instance for TDE encryption.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:tde_credential_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TdeCredentialPassword', traits: {"smithy.api#documentation" => "<p>The password for the given ARN from the key store in order to access the device.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of EC2 VPC security groups to associate with this DB instance.</p>\n         <p>Default: The default EC2 VPC security group for the DB subnet group's VPC.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The Active Directory directory ID to restore the DB instance in.\n          Create the domain before running this command. Currently, you can create only the MySQL, Microsoft SQL \n          Server, Oracle, and PostgreSQL DB instances in an Active Directory Domain.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/kerberos-authentication.html\">\n          Kerberos Authentication</a> in the <i>Amazon RDS User Guide</i>.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:domain_iam_role_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainIAMRoleName', traits: {"smithy.api#documentation" => "<p>The name of the IAM role to use when making API calls to the Directory Service.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:domain_fqdn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainFqdn', traits: {"smithy.api#documentation" => "<p>The fully qualified domain name (FQDN) of an Active Directory domain.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mymanagedADtest.mymanagedAD.mydomain</code>\n         </p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:domain_ou, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainOu', traits: {"smithy.api#documentation" => "<p>The Active Directory organizational unit for your DB instance to join.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the distinguished name format.</p>\n            </li>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>OU=mymanagedADtestOU,DC=mymanagedADtest,DC=mymanagedAD,DC=mydomain</code>\n         </p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:domain_auth_secret_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DomainAuthSecretArn', traits: {"smithy.api#documentation" => "<p>The ARN for the Secrets Manager secret with the credentials for the user joining the domain.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Can't be longer than 64 characters.</p>\n            </li>\n         </ul>\n         <p>Example: <code>arn:aws:secretsmanager:region:account-number:secret:myselfmanagedADtestsecret-123456</code>\n         </p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:domain_dns_ips, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'DomainDnsIps', traits: {"smithy.api#documentation" => "<p>The IPv4 DNS IP addresses of your primary and secondary Active Directory domain controllers.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Two IP addresses must be provided.  If there isn't a secondary domain controller, use the IP address of the primary domain controller for both entries in the list.</p>\n            </li>\n         </ul>\n         <p>Example: <code>123.124.125.126,234.235.236.237</code>\n         </p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:enable_iam_database_authentication, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableIAMDatabaseAuthentication', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable mapping of Amazon Web Services Identity and Access Management\n            (IAM) accounts to database accounts. By default, mapping isn't enabled.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>For more information about IAM database authentication, see \n        <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.IAMDBAuth.html\">\n            IAM Database Authentication for MySQL and PostgreSQL</a> in the <i>Amazon RDS User Guide.</i>\n         </p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>The list of logs that the restored DB instance is to export to CloudWatch Logs. The values\n            in the list depend on the DB engine being used. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_LogAccess.html#USER_LogAccess.Procedural.UploadtoCloudWatch\">Publishing Database Logs to Amazon CloudWatch Logs</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessorFeatureList, location_name: 'ProcessorFeatures', traits: {"smithy.api#documentation" => "<p>The number of CPU cores and the number of threads per core for the DB instance class of the DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:use_default_processor_features, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'UseDefaultProcessorFeatures', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance class of the DB instance uses its default processor features.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:db_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the DB parameter group to associate with this DB instance.</p>\n         <p>If you do not specify a value for <code>DBParameterGroupName</code>, then the default <code>DBParameterGroup</code> \n                for the specified DB engine is used.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If supplied, must match the name of an existing DB parameter group.</p>\n            </li>\n            <li>\n               <p>Must be 1 to 255 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>First character must be a letter.</p>\n            </li>\n            <li>\n               <p>Can't end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance has deletion protection enabled. \n            The database can't be deleted when deletion protection is enabled. By default, \n            deletion protection isn't enabled. For more information, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_DeleteInstance.html\">\n                Deleting a DB Instance</a>.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:source_dbi_resource_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDbiResourceId', traits: {"smithy.api#documentation" => "<p>The resource ID of the source DB instance from which to restore.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:max_allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxAllocatedStorage', traits: {"smithy.api#documentation" => "<p>The upper limit in gibibytes (GiB) to which Amazon RDS can automatically scale the storage of the DB instance.</p>\n         <p>For more information about this setting, including limitations that apply to it, see \n          <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PIOPS.StorageTypes.html#USER_PIOPS.Autoscaling\">\n              Managing capacity automatically with Amazon RDS storage autoscaling</a> \n          in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:source_db_instance_automated_backups_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDBInstanceAutomatedBackupsArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the replicated automated backups from which to restore, for example, \n            <code>arn:aws:rds:us-east-1:123456789012:auto-backup:ab-L2IJCEXJP7XQ7HOJ4SIEXAMPLE</code>.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:enable_customer_owned_ip, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnableCustomerOwnedIp', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable a customer-owned IP address (CoIP) for an RDS on Outposts DB instance.</p>\n         <p>A <i>CoIP</i> provides local or external connectivity to resources in\n            your Outpost subnets through your on-premises network. For some use cases, a CoIP can\n            provide lower latency for connections to the DB instance from outside of its virtual\n            private cloud (VPC) on your local network.</p>\n         <p>This setting doesn't apply to RDS Custom.</p>\n         <p>For more information about RDS on Outposts, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-on-outposts.html\">Working with Amazon RDS on Amazon Web Services Outposts</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>For more information about CoIPs, see <a href=\"https://docs.aws.amazon.com/outposts/latest/userguide/routing.html#ip-addressing\">Customer-owned IP addresses</a> \n            in the <i>Amazon Web Services Outposts User Guide</i>.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:custom_iam_instance_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CustomIamInstanceProfile', traits: {"smithy.api#documentation" => "<p>The instance profile associated with the underlying Amazon EC2 instance of an \n            RDS Custom DB instance. The instance profile must meet the following requirements:</p>\n         <ul>\n            <li>\n               <p>The profile must exist in your account.</p>\n            </li>\n            <li>\n               <p>The profile must have an IAM role that Amazon EC2 has permissions to assume.</p>\n            </li>\n            <li>\n               <p>The instance profile name and the associated IAM role name must start with the prefix <code>AWSRDSCustom</code>.</p>\n            </li>\n         </ul>\n         <p>For the list of permissions required for the IAM role, see \n            <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/custom-setup-orcl.html#custom-setup-orcl.iam-vpc\">\n                Configure IAM and your VPC</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting is required for RDS Custom.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:backup_target, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BackupTarget', traits: {"smithy.api#documentation" => "<p>The location for storing automated backups and manual snapshots for the restored DB instance.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>local</code> (Dedicated Local Zone)</p>\n            </li>\n            <li>\n               <p>\n                  <code>outposts</code> (Amazon Web Services Outposts)</p>\n            </li>\n            <li>\n               <p>\n                  <code>region</code> (Amazon Web Services Region)</p>\n            </li>\n         </ul>\n         <p>Default: <code>region</code>\n         </p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-on-outposts.html\">Working \n            with Amazon RDS on Amazon Web Services Outposts</a> in the <i>Amazon RDS User Guide</i>.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:network_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NetworkType', traits: {"smithy.api#documentation" => "<p>The network type of the DB instance.</p>\n         <p>The network type is determined by the <code>DBSubnetGroup</code> specified for the DB instance. \n            A <code>DBSubnetGroup</code> can support only the IPv4 protocol or the IPv4 and the IPv6 \n            protocols (<code>DUAL</code>).</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_VPC.WorkingWithRDSInstanceinaVPC.html\">\n            Working with a DB instance in a VPC</a> in the \n            <i>Amazon RDS User Guide.</i>\n         </p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>IPV4</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>DUAL</code>\n               </p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:storage_throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'StorageThroughput', traits: {"smithy.api#documentation" => "<p>The storage throughput value for the DB instance.</p>\n         <p>This setting doesn't apply to RDS Custom or Amazon Aurora.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:allocated_storage, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'AllocatedStorage', traits: {"smithy.api#documentation" => "<p>The amount of storage (in gibibytes) to allocate initially for the DB instance.\n            Follow the allocation rules specified in <code>CreateDBInstance</code>.</p>\n         <p>This setting isn't valid for RDS for SQL Server.</p>\n         <note>\n            <p>Be sure to allocate enough storage for your new DB instance so that the restore operation can succeed.\n                You can also allocate additional storage for future growth.</p>\n         </note>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:dedicated_log_volume, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DedicatedLogVolume', traits: {"smithy.api#documentation" => "<p>Specifies whether to enable a dedicated log volume (DLV) for the DB instance.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>The CA certificate identifier to use for the DB instance's server certificate.</p>\n         <p>This setting doesn't apply to RDS Custom DB instances.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/UsingWithRDS.SSL.html\">Using SSL/TLS to encrypt a connection to a DB \n                instance</a> in the <i>Amazon RDS User Guide</i> and \n                <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/UsingWithRDS.SSL.html\">\n                    Using SSL/TLS to encrypt a connection to a DB cluster</a> in the <i>Amazon Aurora \n                        User Guide</i>.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:engine_lifecycle_support, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineLifecycleSupport', traits: {"smithy.api#documentation" => "<p>The life cycle type for this DB instance.</p>\n         <note>\n            <p>By default, this value is set to <code>open-source-rds-extended-support</code>, which enrolls your DB instance into Amazon RDS Extended Support. \n              At the end of standard support, you can avoid charges for Extended Support by setting the value to <code>open-source-rds-extended-support-disabled</code>. In this case, \n              RDS automatically upgrades your restored DB instance to a higher engine version, if the major engine version is past its end of standard support date.</p>\n         </note>\n         <p>You can use this setting to enroll your DB instance into Amazon RDS Extended Support. With RDS Extended Support, \n        you can run the selected major engine version on your DB instance past the end of standard support for that engine version. For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/extended-support.html\">Amazon RDS Extended Support with Amazon RDS</a> in the <i>Amazon RDS User Guide</i>.</p>\n         <p>This setting applies only to RDS for MySQL and RDS for PostgreSQL. For Amazon Aurora DB instances, the life cycle type is managed by the DB cluster.</p>\n         <p>Valid Values: <code>open-source-rds-extended-support | open-source-rds-extended-support-disabled</code>\n         </p>\n         <p>Default: <code>open-source-rds-extended-support</code>\n         </p>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager in the\n            restored DB instance.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-secrets-manager.html\">Password management with Amazon Web Services Secrets Manager</a> \n            in the <i>Amazon RDS User Guide</i>.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Applies to RDS for Oracle only.</p>\n            </li>\n         </ul>"}))
    RestoreDBInstanceToPointInTimeMessage.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and \n            managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets \n            Manager for the DB instance.</p>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.\n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>If you don't specify <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> \n            KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't \n            use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer \n            managed KMS key.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account\n            has a different default KMS key for each Amazon Web Services Region.</p>"}))
    RestoreDBInstanceToPointInTimeMessage.type = Types::RestoreDBInstanceToPointInTimeMessage
    RestoreDBInstanceToPointInTimeResult.add_member(:db_instance, Smithy::Schema::Shapes::ShapeRef.new(shape: DBInstance, location_name: 'DBInstance'))
    RestoreDBInstanceToPointInTimeResult.type = Types::RestoreDBInstanceToPointInTimeResult
    RestoreWindow.add_member(:earliest_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'EarliestTime', traits: {"smithy.api#documentation" => "<p>The earliest time you can restore an instance to.</p>"}))
    RestoreWindow.add_member(:latest_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'LatestTime', traits: {"smithy.api#documentation" => "<p>The latest time you can restore an instance to.</p>"}))
    RestoreWindow.type = Types::RestoreWindow
    RevokeDBSecurityGroupIngressMessage.add_member(:db_security_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSecurityGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the DB security group to revoke ingress from.</p>", "smithy.api#required" => {}}))
    RevokeDBSecurityGroupIngressMessage.add_member(:cidrip, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CIDRIP', traits: {"smithy.api#documentation" => "<p>The IP range to revoke access from. \n        Must be a valid CIDR range. If <code>CIDRIP</code> is specified, \n        <code>EC2SecurityGroupName</code>, <code>EC2SecurityGroupId</code> and <code>EC2SecurityGroupOwnerId</code>\n        can't be provided.</p>"}))
    RevokeDBSecurityGroupIngressMessage.add_member(:ec2_security_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EC2SecurityGroupName', traits: {"smithy.api#documentation" => "<p>The name of the EC2 security group to revoke access from.\n        For VPC DB security groups, <code>EC2SecurityGroupId</code> must be provided.\n        Otherwise, EC2SecurityGroupOwnerId and either <code>EC2SecurityGroupName</code> or <code>EC2SecurityGroupId</code> must be provided.</p>"}))
    RevokeDBSecurityGroupIngressMessage.add_member(:ec2_security_group_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EC2SecurityGroupId', traits: {"smithy.api#documentation" => "<p>The id of the EC2 security group to revoke access from.\n        For VPC DB security groups, <code>EC2SecurityGroupId</code> must be provided.\n        Otherwise, EC2SecurityGroupOwnerId and either <code>EC2SecurityGroupName</code> or <code>EC2SecurityGroupId</code> must be provided.</p>"}))
    RevokeDBSecurityGroupIngressMessage.add_member(:ec2_security_group_owner_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EC2SecurityGroupOwnerId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services account number of the owner of the EC2 security group\n        specified in the <code>EC2SecurityGroupName</code> parameter.\n        The Amazon Web Services access key ID isn't an acceptable value.\n        For VPC DB security groups, <code>EC2SecurityGroupId</code> must be provided.\n        Otherwise, EC2SecurityGroupOwnerId and either <code>EC2SecurityGroupName</code> or <code>EC2SecurityGroupId</code> must be provided.</p>"}))
    RevokeDBSecurityGroupIngressMessage.type = Types::RevokeDBSecurityGroupIngressMessage
    RevokeDBSecurityGroupIngressResult.add_member(:db_security_group, Smithy::Schema::Shapes::ShapeRef.new(shape: DBSecurityGroup, location_name: 'DBSecurityGroup'))
    RevokeDBSecurityGroupIngressResult.type = Types::RevokeDBSecurityGroupIngressResult
    SNSInvalidTopicFault.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: ExceptionMessage, location_name: 'message'))
    SNSInvalidTopicFault.type = Types::SNSInvalidTopicFault
    SNSNoAuthorizationFault.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: ExceptionMessage, location_name: 'message'))
    SNSNoAuthorizationFault.type = Types::SNSNoAuthorizationFault
    SNSTopicArnNotFoundFault.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: ExceptionMessage, location_name: 'message'))
    SNSTopicArnNotFoundFault.type = Types::SNSTopicArnNotFoundFault
    ScalarReferenceDetails.add_member(:value, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'Value', traits: {"smithy.api#documentation" => "<p>The value of a scalar reference.</p>"}))
    ScalarReferenceDetails.type = Types::ScalarReferenceDetails
    ScalingConfiguration.add_member(:min_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MinCapacity', traits: {"smithy.api#documentation" => "<p>The minimum capacity for an Aurora DB cluster in <code>serverless</code> DB engine mode.</p>\n         <p>For Aurora MySQL, valid capacity values are <code>1</code>, <code>2</code>, <code>4</code>, <code>8</code>, <code>16</code>, <code>32</code>, <code>64</code>, <code>128</code>, and <code>256</code>.</p>\n         <p>For Aurora PostgreSQL, valid capacity values are <code>2</code>, <code>4</code>, <code>8</code>, <code>16</code>, <code>32</code>, <code>64</code>, <code>192</code>, and <code>384</code>.</p>\n         <p>The minimum capacity must be less than or equal to the maximum capacity.</p>"}))
    ScalingConfiguration.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>The maximum capacity for an Aurora DB cluster in <code>serverless</code> DB engine mode.</p>\n         <p>For Aurora MySQL, valid capacity values are <code>1</code>, <code>2</code>, <code>4</code>, <code>8</code>, <code>16</code>, <code>32</code>, <code>64</code>, <code>128</code>, and <code>256</code>.</p>\n         <p>For Aurora PostgreSQL, valid capacity values are <code>2</code>, <code>4</code>, <code>8</code>, <code>16</code>, <code>32</code>, <code>64</code>, <code>192</code>, and <code>384</code>.</p>\n         <p>The maximum capacity must be greater than or equal to the minimum capacity.</p>"}))
    ScalingConfiguration.add_member(:auto_pause, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoPause', traits: {"smithy.api#documentation" => "<p>Indicates whether to allow or disallow automatic pause for an Aurora DB cluster in <code>serverless</code> DB engine mode.\n            A DB cluster can be paused only when it's idle (it has no connections).</p>\n         <note>\n            <p>If a DB cluster is paused for more than seven days, the DB cluster might be backed up with a snapshot.\n                In this case, the DB cluster is restored when there is a request to connect to it.</p>\n         </note>"}))
    ScalingConfiguration.add_member(:seconds_until_auto_pause, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SecondsUntilAutoPause', traits: {"smithy.api#documentation" => "<p>The time, in seconds, before an Aurora DB cluster in <code>serverless</code> mode is paused.</p>\n         <p>Specify a value between 300 and 86,400 seconds.</p>"}))
    ScalingConfiguration.add_member(:timeout_action, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TimeoutAction', traits: {"smithy.api#documentation" => "<p>The action to take when the timeout is reached, either <code>ForceApplyCapacityChange</code> or <code>RollbackCapacityChange</code>.</p>\n         <p>\n            <code>ForceApplyCapacityChange</code> sets the capacity to the specified value as soon as possible.</p>\n         <p>\n            <code>RollbackCapacityChange</code>, the default, ignores the capacity change if a scaling point isn't found in the timeout period.</p>\n         <important>\n            <p>If you specify <code>ForceApplyCapacityChange</code>, connections that\n                prevent Aurora Serverless v1 from finding a scaling point might be dropped.</p>\n         </important>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-serverless.how-it-works.html#aurora-serverless.how-it-works.auto-scaling\">\n                    Autoscaling for Aurora Serverless v1</a> in the <i>Amazon Aurora User Guide</i>.</p>"}))
    ScalingConfiguration.add_member(:seconds_before_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SecondsBeforeTimeout', traits: {"smithy.api#documentation" => "<p>The amount of time, in seconds, that Aurora Serverless v1 tries to find a scaling point\n            to perform seamless scaling before enforcing the timeout action. The default is 300.</p>\n         <p>Specify a value between 60 and 600 seconds.</p>"}))
    ScalingConfiguration.type = Types::ScalingConfiguration
    ScalingConfigurationInfo.add_member(:min_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MinCapacity', traits: {"smithy.api#documentation" => "<p>The minimum capacity for an Aurora DB cluster in <code>serverless</code> DB engine mode.</p>"}))
    ScalingConfigurationInfo.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>The maximum capacity for an Aurora DB cluster in <code>serverless</code> DB engine mode.</p>"}))
    ScalingConfigurationInfo.add_member(:auto_pause, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoPause', traits: {"smithy.api#documentation" => "<p>Indicates whether automatic pause is allowed for the Aurora DB cluster\n            in <code>serverless</code> DB engine mode.</p>\n         <p>When the value is set to false for an Aurora Serverless v1 DB cluster, the DB cluster automatically resumes.</p>"}))
    ScalingConfigurationInfo.add_member(:seconds_until_auto_pause, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SecondsUntilAutoPause', traits: {"smithy.api#documentation" => "<p>The remaining amount of time, in seconds, before the Aurora DB cluster in\n                <code>serverless</code> mode is paused. A DB cluster can be paused only when\n            it's idle (it has no connections).</p>"}))
    ScalingConfigurationInfo.add_member(:timeout_action, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TimeoutAction', traits: {"smithy.api#documentation" => "<p>The action that occurs when Aurora times out while attempting to change the capacity of an\n            Aurora Serverless v1 cluster. The value is either <code>ForceApplyCapacityChange</code> or\n            <code>RollbackCapacityChange</code>.</p>\n         <p>\n            <code>ForceApplyCapacityChange</code>, the default, sets the capacity to the specified value as soon as possible.</p>\n         <p>\n            <code>RollbackCapacityChange</code> ignores the capacity change if a scaling point isn't found in the timeout period.</p>"}))
    ScalingConfigurationInfo.add_member(:seconds_before_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SecondsBeforeTimeout', traits: {"smithy.api#documentation" => "<p>The number of seconds before scaling times out. What happens when an attempted scaling action times out\n            is determined by the <code>TimeoutAction</code> setting.</p>"}))
    ScalingConfigurationInfo.type = Types::ScalingConfigurationInfo
    ServerlessV2FeaturesSupport.add_member(:min_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MinCapacity', traits: {"smithy.api#documentation" => "<p>If the minimum capacity is 0 ACUs, the engine version or platform version supports the automatic pause/resume\n         feature of Aurora Serverless v2.</p>"}))
    ServerlessV2FeaturesSupport.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>\n         Specifies the upper Aurora Serverless v2 capacity limit for a particular engine version or platform version.\n         Depending on the engine version, the maximum capacity for an Aurora Serverless v2 cluster might be\n         <code>256</code> or <code>128</code>.\n         </p>"}))
    ServerlessV2FeaturesSupport.type = Types::ServerlessV2FeaturesSupport
    ServerlessV2ScalingConfiguration.add_member(:min_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MinCapacity', traits: {"smithy.api#documentation" => "<p>The minimum number of Aurora capacity units (ACUs) for a DB instance in an Aurora Serverless v2 cluster.\n            You can specify ACU values in half-step increments, such as 8, 8.5, 9, and so on.\n            For Aurora versions that support the Aurora Serverless v2 auto-pause feature, the smallest value that you can use is 0.\n            For versions that don't support Aurora Serverless v2 auto-pause, the smallest value that you can use is 0.5.\n        </p>"}))
    ServerlessV2ScalingConfiguration.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>The maximum number of Aurora capacity units (ACUs) for a DB instance in an Aurora Serverless v2 cluster.\n            You can specify ACU values in half-step increments, such as 32, 32.5, 33, and so on. The largest value\n            that you can use is 256 for recent Aurora versions, or 128 for older versions. You can check the attributes of your engine version or platform version to determine the specific maximum capacity supported.</p>"}))
    ServerlessV2ScalingConfiguration.add_member(:seconds_until_auto_pause, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SecondsUntilAutoPause', traits: {"smithy.api#documentation" => "<p>Specifies the number of seconds an Aurora Serverless v2 DB instance must be idle before\n         Aurora attempts to automatically pause it.\n       </p>\n         <p>Specify a value between 300 seconds (five minutes) and 86,400 seconds (one day). The default is 300 seconds.</p>"}))
    ServerlessV2ScalingConfiguration.type = Types::ServerlessV2ScalingConfiguration
    ServerlessV2ScalingConfigurationInfo.add_member(:min_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MinCapacity', traits: {"smithy.api#documentation" => "<p>The minimum number of Aurora capacity units (ACUs) for a DB instance in an Aurora Serverless v2 cluster.\n            You can specify ACU values in half-step increments, such as 8, 8.5, 9, and so on.\n            For Aurora versions that support the Aurora Serverless v2 auto-pause feature, the smallest value that you can use is 0.\n            For versions that don't support Aurora Serverless v2 auto-pause, the smallest value that you can use is 0.5.\n        </p>"}))
    ServerlessV2ScalingConfigurationInfo.add_member(:max_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: DoubleOptional, location_name: 'MaxCapacity', traits: {"smithy.api#documentation" => "<p>The maximum number of Aurora capacity units (ACUs) for a DB instance in an Aurora Serverless v2 cluster.\n            You can specify ACU values in half-step increments, such as 32, 32.5, 33, and so on. The largest value\n            that you can use is 256 for recent Aurora versions, or 128 for older versions. You can check the attributes of your engine version or platform version to determine the specific maximum capacity supported.</p>"}))
    ServerlessV2ScalingConfigurationInfo.add_member(:seconds_until_auto_pause, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'SecondsUntilAutoPause', traits: {"smithy.api#documentation" => "<p>\n         The number of seconds an Aurora Serverless v2 DB instance must be idle before\n         Aurora attempts to automatically pause it.\n         This property is only shown when the minimum capacity for the cluster is set to 0 ACUs.\n         Changing the minimum capacity to a nonzero value removes this property. If you later\n         change the minimum capacity back to 0 ACUs, this property is reset to its default value\n         unless you specify it again.\n       </p>\n         <p>This value ranges between 300 seconds (five minutes) and 86,400 seconds (one day). The default is 300 seconds.</p>"}))
    ServerlessV2ScalingConfigurationInfo.type = Types::ServerlessV2ScalingConfigurationInfo
