    StartActivityStreamRequest.add_member(:mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ActivityStreamMode, location_name: 'Mode', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the mode of the database activity stream.\n            Database events such as a change or access generate an activity stream event.\n            The database session can handle these events either synchronously or asynchronously.</p>", "smithy.api#required" => {}}))
    StartActivityStreamRequest.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier for encrypting messages in the database activity stream.\n            The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key.</p>", "smithy.api#required" => {}}))
    StartActivityStreamRequest.add_member(:apply_immediately, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ApplyImmediately', traits: {"smithy.api#documentation" => "<p>Specifies whether or not the database activity stream is to start as soon as possible, \n            regardless of the maintenance window for the database.</p>"}))
    StartActivityStreamRequest.add_member(:engine_native_audit_fields_included, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EngineNativeAuditFieldsIncluded', traits: {"smithy.api#documentation" => "<p>Specifies whether the database activity stream includes engine-native audit fields. This option applies\n        to an Oracle or Microsoft SQL Server DB instance. By default, no engine-native audit fields are included.</p>"}))
