    StartExportTaskMessage.add_member(:export_task_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ExportTaskIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A unique identifier for the export task. This ID isn't an identifier for\n            the Amazon S3 bucket where the data is to be exported.</p>", "smithy.api#required" => {}}))
    StartExportTaskMessage.add_member(:source_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the snapshot or cluster to export to Amazon S3.</p>", "smithy.api#required" => {}}))
    StartExportTaskMessage.add_member(:s3_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3BucketName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Amazon S3 bucket to export the snapshot or cluster data to.</p>", "smithy.api#required" => {}}))
    StartExportTaskMessage.add_member(:iam_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'IamRoleArn', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the IAM role to use for writing to the Amazon S3 bucket \n            when exporting a snapshot or cluster.</p>\n         <p>In the IAM policy attached to your IAM role, include the following required actions to allow the transfer of files from Amazon\n            RDS or Amazon Aurora to an S3 bucket:</p>\n         <ul>\n            <li>\n               <p>s3:PutObject*</p>\n            </li>\n            <li>\n               <p>s3:GetObject*</p>\n            </li>\n            <li>\n               <p>s3:ListBucket</p>\n            </li>\n            <li>\n               <p>s3:DeleteObject*</p>\n            </li>\n            <li>\n               <p>s3:GetBucketLocation </p>\n            </li>\n         </ul>\n         <p>In the policy, include the resources to identify the S3 bucket and objects in the bucket. The following list of resources shows\n            the Amazon Resource Name (ARN) format for accessing S3:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>arn:aws:s3:::<i>your-s3-bucket</i>\n                  </code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>arn:aws:s3:::<i>your-s3-bucket</i>/*</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    StartExportTaskMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the Amazon Web Services KMS key to use to encrypt the data exported to Amazon S3. The Amazon Web Services KMS \n            key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key. \n            The caller of this operation must be authorized to run the following operations. \n            These can be set in the Amazon Web Services KMS key policy:</p>\n         <ul>\n            <li>\n               <p>kms:CreateGrant</p>\n            </li>\n            <li>\n               <p>kms:DescribeKey</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    StartExportTaskMessage.add_member(:s3_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'S3Prefix', traits: {"smithy.api#documentation" => "<p>The Amazon S3 bucket prefix to use as the file name and path of the exported data.</p>"}))
    StartExportTaskMessage.add_member(:export_only, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'ExportOnly', traits: {"smithy.api#documentation" => "<p>The data to be exported from the snapshot or cluster. \n            If this parameter isn't provided, all of the data is exported.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>database</code> - Export all the data from a specified database.</p>\n            </li>\n            <li>\n               <p>\n                  <code>database.table</code>\n                  <i>table-name</i> - \n                    Export a table of the snapshot or cluster. This format is valid only for RDS for MySQL, RDS for MariaDB, and Aurora MySQL.</p>\n            </li>\n            <li>\n               <p>\n                  <code>database.schema</code>\n                  <i>schema-name</i> - Export a database schema of the snapshot or cluster. \n                This format is valid only for RDS for PostgreSQL and Aurora PostgreSQL.</p>\n            </li>\n            <li>\n               <p>\n                  <code>database.schema.table</code>\n                  <i>table-name</i> - Export a table of the database schema. \n                This format is valid only for RDS for PostgreSQL and Aurora PostgreSQL.</p>\n            </li>\n         </ul>"}))
    StartExportTaskMessage.type = Types::StartExportTaskMessage
    StartExportTaskOutput.add_member(:export_task_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'ExportTaskIdentifier', traits: {"smithy.api#documentation" => "<p>A unique identifier for the snapshot or cluster export task. This ID isn't an identifier for\n            the Amazon S3 bucket where the data is exported.</p>"}))
    StartExportTaskOutput.add_member(:source_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the snapshot or cluster exported to Amazon S3.</p>"}))
    StartExportTaskOutput.add_member(:export_only, Smithy::Schema::Shapes::ShapeRef.new(shape: StringList, location_name: 'ExportOnly', traits: {"smithy.api#documentation" => "<p>The data exported from the snapshot or cluster.</p>\n         <p>Valid Values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>database</code> - Export all the data from a specified database.</p>\n            </li>\n            <li>\n               <p>\n                  <code>database.table</code>\n                  <i>table-name</i> - \n                    Export a table of the snapshot or cluster. This format is valid only for RDS for MySQL, RDS for MariaDB, and Aurora MySQL.</p>\n            </li>\n            <li>\n               <p>\n                  <code>database.schema</code>\n                  <i>schema-name</i> - Export a database schema of the snapshot or cluster. \n                This format is valid only for RDS for PostgreSQL and Aurora PostgreSQL.</p>\n            </li>\n            <li>\n               <p>\n                  <code>database.schema.table</code>\n                  <i>table-name</i> - Export a table of the database schema. \n                This format is valid only for RDS for PostgreSQL and Aurora PostgreSQL.</p>\n            </li>\n         </ul>"}))
    StartExportTaskOutput.add_member(:snapshot_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'SnapshotTime', traits: {"smithy.api#documentation" => "<p>The time when the snapshot was created.</p>"}))
    StartExportTaskOutput.add_member(:task_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'TaskStartTime', traits: {"smithy.api#documentation" => "<p>The time when the snapshot or cluster export task started.</p>"}))
    StartExportTaskOutput.add_member(:task_end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'TaskEndTime', traits: {"smithy.api#documentation" => "<p>The time when the snapshot or cluster export task ended.</p>"}))
